-- Portico baseline schema (generated by Phase34 — Scripts/baseline/gen_baseline.py
-- from the 265-migration schema and core.sql; see Compact Catalogue — Direct Design.md).

-- ===== catalogue core and derived tables (core.sql, derived.sql)
-- Catalogue kinds are data (Direct Design §2). Numbers are permanent: never
-- reused or renumbered. Reserved: 14-19 video/audio growth, 20-29 reading,
-- 30-39 photos, 40-99 unassigned. A new kind is one INSERT here (plus, if it
-- has kind-specific facts, one side table).
CREATE TABLE catalog_kinds(
 id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 99),
 name TEXT NOT NULL UNIQUE,
 playable INTEGER NOT NULL CHECK(playable IN(0,1)),
 container INTEGER NOT NULL CHECK(container IN(0,1)),
 searchable INTEGER NOT NULL CHECK(searchable IN(0,1)),
 browsable INTEGER NOT NULL CHECK(browsable IN(0,1)),
 listening INTEGER NOT NULL CHECK(listening IN(0,1))) STRICT;
INSERT INTO catalog_kinds VALUES
 (1,'movie',1,0,1,1,0),(2,'show',0,1,1,1,0),(3,'season',0,1,0,1,0),(4,'episode',1,0,1,1,0),
 (5,'artist',0,1,1,1,1),(6,'album',0,1,1,1,1),(7,'song',1,0,1,1,1),(8,'book',0,1,1,1,1),
 (9,'audiobook_file',1,0,0,1,1),(10,'collection',0,1,0,1,0),(11,'extra',1,0,0,1,0),
 (12,'disc',0,1,0,0,1),(13,'author',0,1,0,1,1);

-- A library's integer handle for catalogue rows; libraries keeps its public TEXT id.
-- root is the identity root: the folder the library was created from, fixed for
-- its life, so entity identity keys survive a later change of its source path
-- and a library re-added from the same folder finds its old public ids.
CREATE TABLE catalog_libraries(
 id INTEGER PRIMARY KEY,
 library_id TEXT NOT NULL UNIQUE REFERENCES libraries(id) ON DELETE CASCADE,
 root TEXT NOT NULL,
 name TEXT NOT NULL,
 kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 99),
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))) STRICT;

-- The backbone: one row per catalogue entity of any kind.
CREATE TABLE catalog_entities(
 id INTEGER PRIMARY KEY,
 public_id BLOB NOT NULL UNIQUE CHECK(length(public_id)=16),
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 kind INTEGER NOT NULL REFERENCES catalog_kinds(id),
 parent_id INTEGER REFERENCES catalog_entities(id),
 title TEXT NOT NULL,
 sort_title TEXT NOT NULL DEFAULT '',
 metadata_language TEXT NOT NULL DEFAULT '',
 sort_key TEXT NOT NULL,
 sort_head TEXT NOT NULL,
 year INTEGER NOT NULL DEFAULT 0,
 added_ms INTEGER,
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))) STRICT;
CREATE INDEX catalog_entities_title ON catalog_entities(library_id,kind,sort_key,id);
CREATE INDEX catalog_entities_added ON catalog_entities(library_id,added_ms DESC,id DESC) WHERE added_ms IS NOT NULL;
CREATE INDEX catalog_entities_parent ON catalog_entities(parent_id,id) WHERE parent_id IS NOT NULL;
CREATE INDEX catalog_entities_library ON catalog_entities(library_id,kind,id);

-- The entity-identity ledger (Direct Design §4): the same folder and source
-- key get the same public id after a rescan or a re-added library. Never deleted.
CREATE TABLE catalog_identities(
 public_id BLOB PRIMARY KEY CHECK(length(public_id)=16),
 root TEXT NOT NULL,
 source_key TEXT NOT NULL,
 kind INTEGER NOT NULL,
 UNIQUE(root,source_key)) WITHOUT ROWID, STRICT;

-- One asset table: physical evidence and probed facts. token is the asset's
-- public id (assets are not entities; the format is unchanged).
CREATE TABLE catalog_assets(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 path TEXT NOT NULL UNIQUE,
 size INTEGER NOT NULL,
 modified_ns INTEGER NOT NULL,
 container TEXT NOT NULL,
 video_codec TEXT NOT NULL,
 audio_codec TEXT NOT NULL,
 width INTEGER NOT NULL,
 height INTEGER NOT NULL,
 duration REAL NOT NULL,
 available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1))) STRICT;
CREATE TABLE catalog_asset_links(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id INTEGER NOT NULL REFERENCES catalog_assets(id) ON DELETE CASCADE,
 part_index INTEGER NOT NULL DEFAULT 0,
 available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)),
 start_seconds REAL NOT NULL DEFAULT 0,
 end_seconds REAL,
 PRIMARY KEY(entity_id,asset_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_asset_links_order ON catalog_asset_links(entity_id,part_index,asset_id);
CREATE INDEX catalog_asset_links_asset ON catalog_asset_links(asset_id,entity_id);

-- Descriptive facts of items and containers that have them.
CREATE TABLE catalog_item_details(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 added_text TEXT,
 overview TEXT NOT NULL DEFAULT '',
 poster_url TEXT NOT NULL DEFAULT '',
 backdrop_url TEXT NOT NULL DEFAULT '',
 original_title TEXT NOT NULL DEFAULT '',
 edition TEXT NOT NULL DEFAULT '',
 tagline TEXT NOT NULL DEFAULT '',
 release_date TEXT NOT NULL DEFAULT '',
 content_rating TEXT NOT NULL DEFAULT '',
 studio TEXT NOT NULL DEFAULT '',
 network TEXT NOT NULL DEFAULT '',
 country TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 labels TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE catalog_item_availability(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 available INTEGER NOT NULL CHECK(available IN(0,1)),
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))) STRICT;

-- Kind side tables.
CREATE TABLE catalog_shows(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 local_key TEXT NOT NULL,
 provider_match_status TEXT NOT NULL DEFAULT 'unmatched',
 original_title TEXT NOT NULL DEFAULT '',
 tagline TEXT NOT NULL DEFAULT '',
 overview TEXT NOT NULL DEFAULT '',
 content_rating TEXT NOT NULL DEFAULT '',
 studio TEXT NOT NULL DEFAULT '',
 network TEXT NOT NULL DEFAULT '',
 country TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 labels TEXT NOT NULL DEFAULT '') STRICT;
CREATE INDEX catalog_shows_local_key ON catalog_shows(local_key,entity_id);
CREATE TABLE catalog_seasons(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 show_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 number INTEGER NOT NULL,
 title TEXT NOT NULL DEFAULT '',
 overview TEXT NOT NULL DEFAULT '',
 UNIQUE(show_id,number)) STRICT;
CREATE TABLE catalog_episodes(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 show_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 season_id INTEGER REFERENCES catalog_entities(id),
 numbering TEXT NOT NULL,
 number INTEGER NOT NULL,
 local_identity_status TEXT NOT NULL DEFAULT 'parsed',
 ordering_basis TEXT NOT NULL DEFAULT 'unspecified',
 air_date INTEGER) STRICT;
CREATE INDEX catalog_episodes_show ON catalog_episodes(show_id,season_id,number,entity_id);
CREATE INDEX catalog_episodes_season ON catalog_episodes(season_id,number,entity_id) WHERE season_id IS NOT NULL;
CREATE UNIQUE INDEX catalog_episodes_position ON catalog_episodes(show_id,COALESCE(season_id,0),numbering,number);
CREATE TABLE catalog_artists(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 local_key TEXT NOT NULL,
 overview TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '') STRICT;
CREATE INDEX catalog_artists_local_key ON catalog_artists(local_key,entity_id);
CREATE TABLE catalog_albums(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 artist_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 local_key TEXT NOT NULL,
 edition_key TEXT NOT NULL DEFAULT '',
 provider_match_status TEXT NOT NULL DEFAULT 'unmatched',
 overview TEXT NOT NULL DEFAULT '',
 label TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 release_id TEXT NOT NULL DEFAULT '',
 release_group_id TEXT NOT NULL DEFAULT '',
 release_date TEXT NOT NULL DEFAULT '',
 release_country TEXT NOT NULL DEFAULT '',
 provider_observed_at TEXT NOT NULL DEFAULT '') STRICT;
CREATE INDEX catalog_albums_artist ON catalog_albums(artist_id,entity_id);
CREATE INDEX catalog_albums_local_key ON catalog_albums(local_key,entity_id);
CREATE TABLE catalog_songs(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 album_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 disc_number INTEGER,
 track_number INTEGER,
 release_status TEXT NOT NULL DEFAULT 'unmatched',
 recording_id TEXT NOT NULL DEFAULT '',
 release_id TEXT NOT NULL DEFAULT '',
 release_group_id TEXT NOT NULL DEFAULT '',
 track_id TEXT NOT NULL DEFAULT '',
 provider_observed_at TEXT NOT NULL DEFAULT '',
 provider_title TEXT NOT NULL DEFAULT '',
 provider_artist TEXT NOT NULL DEFAULT '') STRICT;
CREATE INDEX catalog_songs_album_order ON catalog_songs(album_id,disc_number,track_number,entity_id);
CREATE INDEX catalog_songs_listening_order ON catalog_songs(album_id,COALESCE(disc_number,0),COALESCE(track_number,0),entity_id);
CREATE TABLE catalog_song_artists(
 song_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 artist_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 PRIMARY KEY(song_id,artist_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_song_artists_artist ON catalog_song_artists(artist_id,song_id);
CREATE TABLE catalog_books(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 local_key TEXT NOT NULL,
 author TEXT NOT NULL DEFAULT '',
 narrator TEXT NOT NULL DEFAULT '',
 provider_match_status TEXT NOT NULL DEFAULT 'deferred',
 overview TEXT NOT NULL DEFAULT '',
 series TEXT NOT NULL DEFAULT '',
 series_position TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 labels TEXT NOT NULL DEFAULT '',
 local_metadata_payload TEXT NOT NULL DEFAULT '') STRICT;
CREATE INDEX catalog_books_author_seek ON catalog_books(library_id,author COLLATE NOCASE,entity_id);
CREATE INDEX catalog_books_local_key ON catalog_books(local_key,entity_id);
CREATE TABLE catalog_book_files(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 book_id INTEGER NOT NULL REFERENCES catalog_entities(id),
 disc_number INTEGER,
 part_number INTEGER) STRICT;
CREATE INDEX catalog_book_files_order ON catalog_book_files(book_id,disc_number,part_number,entity_id);
CREATE INDEX catalog_book_files_listening_order ON catalog_book_files(book_id,COALESCE(disc_number,0),COALESCE(part_number,0),entity_id);
CREATE TABLE catalog_book_chapters(
 id INTEGER PRIMARY KEY,
 file_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 chapter_index INTEGER NOT NULL,
 title TEXT NOT NULL,
 start_seconds REAL NOT NULL,
 end_seconds REAL NOT NULL,
 UNIQUE(file_id,chapter_index)) STRICT;
CREATE TABLE catalog_collections(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 name_key TEXT NOT NULL,
 created_at TEXT NOT NULL,
 member_count INTEGER NOT NULL DEFAULT 0 CHECK(member_count>=0)) STRICT;
CREATE UNIQUE INDEX catalog_collections_name ON catalog_collections(library_id,name_key);
CREATE TABLE catalog_collection_members(
 collection_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 order_key TEXT NOT NULL,
 PRIMARY KEY(collection_id,item_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_collection_members_item ON catalog_collection_members(item_id,collection_id);
CREATE INDEX catalog_collection_members_page ON catalog_collection_members(collection_id,order_key,item_id);

-- Playlists are not catalogue entities: token is the public playlist id and
-- an entry's token its public entry id (both keep today's format).
CREATE TABLE catalog_playlists(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 owner_authority TEXT NOT NULL,
 owner_account TEXT NOT NULL,
 owner_profile TEXT NOT NULL,
 name TEXT NOT NULL,
 summary TEXT NOT NULL DEFAULT '',
 creation_operation TEXT NOT NULL,
 creation_hash TEXT NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1,
 deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1)),
 created_at TEXT NOT NULL,
 entry_count INTEGER NOT NULL DEFAULT 0 CHECK(entry_count>=0),
 UNIQUE(owner_authority,owner_account,owner_profile,creation_operation)) STRICT;
CREATE INDEX catalog_playlists_owner ON catalog_playlists(owner_authority,owner_account,owner_profile,deleted,name COLLATE NOCASE,id);
CREATE TABLE catalog_playlist_entries(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 playlist_id INTEGER NOT NULL REFERENCES catalog_playlists(id) ON DELETE CASCADE,
 item_id INTEGER REFERENCES catalog_entities(id) ON DELETE SET NULL,
 position INTEGER NOT NULL,
 order_key TEXT NOT NULL DEFAULT '',
 UNIQUE(playlist_id,position)) STRICT;
CREATE INDEX catalog_playlist_entries_page ON catalog_playlist_entries(playlist_id,order_key,id);
CREATE INDEX catalog_playlist_entries_item ON catalog_playlist_entries(item_id) WHERE item_id IS NOT NULL;

-- People are not entities: token is the public person id (format unchanged).
CREATE TABLE catalog_people(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 identity_key TEXT NOT NULL,
 name TEXT NOT NULL,
 sort_name TEXT NOT NULL,
 biography TEXT NOT NULL DEFAULT '',
 birth_date TEXT NOT NULL DEFAULT '',
 death_date TEXT NOT NULL DEFAULT '',
 portrait_url TEXT NOT NULL DEFAULT '',
 provider_ids TEXT NOT NULL DEFAULT '{}',
 revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE INDEX catalog_people_name ON catalog_people(sort_name,id);
CREATE UNIQUE INDEX catalog_people_identity ON catalog_people(identity_key);
CREATE TABLE catalog_credits(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 ord INTEGER NOT NULL,
 person_id INTEGER REFERENCES catalog_people(id),
 role_id INTEGER NOT NULL REFERENCES catalog_credit_labels(id),
 department_id INTEGER NOT NULL REFERENCES catalog_credit_labels(id),
 credited_name TEXT NOT NULL,
 provider TEXT NOT NULL,
 credit_id TEXT NOT NULL,
 provider_person_id TEXT NOT NULL DEFAULT '',
 source_ordinal INTEGER NOT NULL,
 PRIMARY KEY(entity_id,ord)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_credits_person ON catalog_credits(person_id,entity_id);
CREATE INDEX catalog_credits_provider_person ON catalog_credits(provider,provider_person_id,entity_id) WHERE provider_person_id<>'';

-- Genres and every other open vocabulary (Direct Design §3.4).
CREATE TABLE catalog_term_sources(
 entity_id INTEGER NOT NULL,
 term_id INTEGER NOT NULL,
 provider TEXT NOT NULL,
 source_id TEXT NOT NULL,
 label_override TEXT,
 source_name TEXT NOT NULL DEFAULT '',
 -- The term's position in the provider's list: the first genre a provider
 -- names is the title's primary one.
 ordinal INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(entity_id,provider,source_id),
 FOREIGN KEY(entity_id,term_id) REFERENCES catalog_entity_terms(entity_id,term_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_term_source_membership ON catalog_term_sources(entity_id,term_id);
CREATE INDEX catalog_term_sources_provider ON catalog_term_sources(provider,source_id,entity_id);
CREATE INDEX catalog_term_sources_name_seek ON catalog_term_sources(source_name COLLATE NOCASE,entity_id);

CREATE TABLE catalog_related_facets(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 relation INTEGER NOT NULL CHECK(relation IN(1,2)),
 provider TEXT NOT NULL,
 facet_id TEXT NOT NULL,
 year INTEGER NOT NULL,
 PRIMARY KEY(entity_id,relation,provider,facet_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_related_lookup ON catalog_related_facets(library_id,relation,provider,facet_id,year DESC,entity_id);

-- kind is the entity kind as a token ('k1' a movie): a search group matches
-- "kind : k1 AND title : (…)" inside the index and ranks there, so a group
-- never filters a whole library's matches by kind afterwards.
CREATE TABLE catalog_search_documents(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 title TEXT NOT NULL,
 kind TEXT NOT NULL) STRICT;
CREATE VIRTUAL TABLE catalog_search_titles USING fts5(
 title,kind,content='catalog_search_documents',content_rowid='entity_id',
 tokenize='unicode61 remove_diacritics 2',prefix='2 3 4');

-- The one dirty queue for derived data (Direct Design §6).
CREATE TABLE catalog_dirty(
 domain INTEGER NOT NULL,
 entity_id INTEGER NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 PRIMARY KEY(domain,entity_id)) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_derivations(
 domain INTEGER PRIMARY KEY,
 version INTEGER NOT NULL DEFAULT 1,
 rebuilding INTEGER NOT NULL DEFAULT 0 CHECK(rebuilding IN(0,1)),
 rebuild_cursor INTEGER NOT NULL DEFAULT 0,
 served_ms INTEGER NOT NULL DEFAULT 0) STRICT;

-- Personal state per profile and item. not_interested hides a title from
-- recommendations and counts against similar titles (recommendations plan).
CREATE TABLE personal_items(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,watchlisted INTEGER NOT NULL DEFAULT 0 CHECK(watchlisted IN(0,1)),favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN(0,1)),rating REAL CHECK(rating IS NULL OR (rating>=0.5 AND rating<=5 AND rating*2=CAST(rating*2 AS INTEGER))),revision INTEGER NOT NULL, reaction TEXT NOT NULL DEFAULT 'none' CHECK(reaction IN('none','like','dislike')), watched INTEGER NOT NULL DEFAULT 0 CHECK(watched IN(0,1)), last_played_at TEXT NOT NULL DEFAULT '', not_interested INTEGER NOT NULL DEFAULT 0 CHECK(not_interested IN(0,1)),PRIMARY KEY(profile_id,item_id)) STRICT;
-- Its indexes, as the 265 schema had them (a core.sql table replaces the old
-- definition, indexes included).
CREATE INDEX personal_watchlist ON personal_items(profile_id,watchlisted,item_id);
CREATE INDEX personal_favorites ON personal_items(profile_id,favorite,item_id);
CREATE INDEX personal_play_state ON personal_items(profile_id,watched,item_id);
CREATE INDEX personal_last_played ON personal_items(profile_id,last_played_at,item_id);
CREATE INDEX personal_rating_range ON personal_items(profile_id,rating,item_id);
CREATE INDEX personal_home_watched ON personal_items(profile_id,watched,last_played_at DESC,item_id DESC);

-- Derived catalogue tables keyed by integer ids (Direct Design §6). Every kind
-- check allows the permanent 1-99 range, so a new kind never rewrites a table.

CREATE TABLE catalog_browse_rows(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 99),
 title TEXT NOT NULL,
 sort_key TEXT NOT NULL,
 head TEXT NOT NULL,
 year INTEGER NOT NULL,
 added_text TEXT,
 item_id INTEGER REFERENCES catalog_entities(id),
 rating_key TEXT NOT NULL,
 label_key TEXT NOT NULL,
 available INTEGER NOT NULL CHECK(available IN(0,1)),
 recent INTEGER NOT NULL CHECK(recent IN(0,1)),
 backdrop INTEGER NOT NULL CHECK(backdrop IN(0,1)),
 duration_max REAL,
 rating_max REAL,
 -- A work's newest addition, for Recently Added: a show, album or book's newest
 -- available member (fanned out like the metrics), a standalone item's own
 -- added time; NULL for members (episodes, songs, book files) and the rest.
 recent_text TEXT) STRICT;
CREATE INDEX catalog_browse_title ON catalog_browse_rows(library_id,kind,sort_key COLLATE NOCASE,entity_id);
-- Sort orders are ascending (key, entity_id): a descending page scans them
-- backwards, and the counted blocks below serve both directions.
CREATE INDEX catalog_browse_added ON catalog_browse_rows(library_id,kind,COALESCE(added_text,''),entity_id);
CREATE INDEX catalog_browse_year ON catalog_browse_rows(library_id,kind,year,entity_id);
CREATE INDEX catalog_browse_item ON catalog_browse_rows(item_id) WHERE item_id IS NOT NULL;
CREATE INDEX catalog_browse_feature ON catalog_browse_rows(library_id,kind,available,backdrop,entity_id);
CREATE INDEX catalog_browse_recent_kind ON catalog_browse_rows(library_id,kind,COALESCE(added_text,'') DESC,entity_id DESC) WHERE item_id IS NOT NULL;
CREATE INDEX catalog_browse_recent_all ON catalog_browse_rows(library_id,COALESCE(added_text,'') DESC,entity_id DESC) WHERE item_id IS NOT NULL;
CREATE INDEX catalog_browse_duration ON catalog_browse_rows(library_id,kind,COALESCE(duration_max,0),entity_id);
CREATE INDEX catalog_browse_rating ON catalog_browse_rows(library_id,kind,COALESCE(rating_max,0),entity_id);
CREATE INDEX catalog_browse_recent_dated ON catalog_browse_rows(library_id,COALESCE(added_text,'') DESC,entity_id DESC) WHERE item_id IS NOT NULL AND added_text IS NOT NULL;
CREATE INDEX catalog_browse_recent_undated ON catalog_browse_rows(library_id,entity_id DESC) WHERE item_id IS NOT NULL AND added_text IS NULL;
CREATE INDEX catalog_browse_recent_works ON catalog_browse_rows(library_id,recent_text DESC,entity_id DESC) WHERE recent_text IS NOT NULL;
CREATE TRIGGER catalog_visibility_sort_browse_insert AFTER INSERT ON catalog_browse_rows BEGIN
 INSERT INTO catalog_visibility_sort_entity_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
CREATE TRIGGER catalog_visibility_sort_browse_update AFTER UPDATE OF title,sort_key,head,year,added_text,duration_max,rating_max ON catalog_browse_rows BEGIN
 INSERT INTO catalog_visibility_sort_entity_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
CREATE TRIGGER catalog_visibility_sort_browse_delete AFTER DELETE ON catalog_browse_rows BEGIN
 INSERT INTO catalog_visibility_sort_entity_jobs(entity_id) VALUES(OLD.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
CREATE TRIGGER catalog_personal_sort_browse_insert AFTER INSERT ON catalog_browse_rows BEGIN
 INSERT INTO catalog_personal_sort_entity_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
CREATE TRIGGER catalog_personal_sort_browse_update AFTER UPDATE OF library_id,kind ON catalog_browse_rows BEGIN
 INSERT INTO catalog_personal_sort_entity_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
CREATE TRIGGER catalog_personal_sort_browse_delete AFTER DELETE ON catalog_browse_rows BEGIN
 INSERT INTO catalog_personal_sort_entity_jobs(entity_id) VALUES(OLD.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1;
END;
-- Content eligibility is kept for container kinds (the kinds table says which).
CREATE TRIGGER catalog_content_eligible_browse_insert AFTER INSERT ON catalog_browse_rows
WHEN (SELECT container FROM catalog_kinds WHERE id=NEW.kind)=1 BEGIN
 INSERT INTO catalog_content_eligible_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1,after_item_id=0,found=0;
END;
CREATE TRIGGER catalog_content_eligible_browse_update AFTER UPDATE ON catalog_browse_rows
WHEN (SELECT container FROM catalog_kinds WHERE id=NEW.kind)=1 OR (SELECT container FROM catalog_kinds WHERE id=OLD.kind)=1 BEGIN
 INSERT INTO catalog_content_eligible_jobs(entity_id) VALUES(NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1,after_item_id=0,found=0;
END;
CREATE TRIGGER catalog_content_eligible_browse_delete AFTER DELETE ON catalog_browse_rows
WHEN (SELECT container FROM catalog_kinds WHERE id=OLD.kind)=1 BEGIN
 INSERT INTO catalog_content_eligible_jobs(entity_id) VALUES(OLD.entity_id) ON CONFLICT(entity_id) DO UPDATE SET sequence=sequence+1,after_item_id=0,found=0;
END;

CREATE TABLE catalog_browse_counted_rows(
 entity_id INTEGER PRIMARY KEY,
 library_id INTEGER NOT NULL,
 kind INTEGER NOT NULL,
 container INTEGER NOT NULL CHECK(container IN(0,1)),
 head TEXT NOT NULL,
 year INTEGER NOT NULL,
 added_text TEXT,
 rating_key TEXT NOT NULL,
 label_key TEXT NOT NULL,
 duration_bucket TEXT NOT NULL DEFAULT '',
 rating_bucket TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE catalog_browse_item_metrics(
 item_id INTEGER PRIMARY KEY,
 duration REAL,
 rating REAL,
 added TEXT) STRICT;
CREATE TABLE catalog_browse_member_metrics(
 entity_id INTEGER NOT NULL,
 item_id INTEGER NOT NULL,
 source INTEGER NOT NULL,
 duration REAL,
 rating REAL,
 added TEXT,
 PRIMARY KEY(entity_id,item_id,source)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_browse_metric_item ON catalog_browse_member_metrics(item_id,entity_id,source);
CREATE INDEX catalog_browse_metric_duration ON catalog_browse_member_metrics(entity_id,duration DESC) WHERE duration IS NOT NULL;
CREATE INDEX catalog_browse_metric_rating ON catalog_browse_member_metrics(entity_id,rating DESC) WHERE rating IS NOT NULL;
CREATE INDEX catalog_browse_metric_added ON catalog_browse_member_metrics(entity_id,added DESC) WHERE added IS NOT NULL;
CREATE TABLE catalog_browse_metric_cursors(
 domain INTEGER NOT NULL,
 entity_id INTEGER NOT NULL,
 sequence INTEGER NOT NULL,
 projection_version INTEGER NOT NULL,
 after_entity INTEGER NOT NULL DEFAULT 0,
 after_source INTEGER NOT NULL DEFAULT -1,
 after_item INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(domain,entity_id)) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_home_counted_rows(
 entity_id INTEGER PRIMARY KEY,library_id INTEGER NOT NULL,kind INTEGER NOT NULL,
 available INTEGER NOT NULL,recent INTEGER NOT NULL,backdrop INTEGER NOT NULL,
 rating_key TEXT NOT NULL,label_key TEXT NOT NULL,dated INTEGER NOT NULL,retired INTEGER NOT NULL) STRICT;

CREATE TABLE catalog_movie_category_cursors(
 item_id INTEGER PRIMARY KEY,
 sequence INTEGER NOT NULL,
 projection_version INTEGER NOT NULL,
 after_library INTEGER NOT NULL DEFAULT 0,
 after_kind INTEGER NOT NULL DEFAULT -1,
 after_value TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE catalog_movie_category_members(
 library_id INTEGER NOT NULL,
 kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),
 value TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 title TEXT NOT NULL,
 poster_url TEXT NOT NULL,
 PRIMARY KEY(library_id,kind,value,item_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_movie_category_poster ON catalog_movie_category_members(library_id,kind,value,title COLLATE NOCASE,item_id) WHERE poster_url<>'';
CREATE INDEX catalog_movie_category_member_id ON catalog_movie_category_members(item_id,library_id,kind,value);
CREATE TRIGGER catalog_movie_category_visible_member_insert AFTER INSERT ON catalog_movie_category_members BEGIN
 INSERT INTO catalog_movie_category_visible_pair_jobs(library_id,kind,value,item_id) VALUES(NEW.library_id,NEW.kind,NEW.value,NEW.item_id)
 ON CONFLICT(library_id,kind,value,item_id) DO UPDATE SET sequence=sequence+1;
END;
