CREATE TABLE catalog_book_series_contrib(
 file_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id INTEGER NOT NULL REFERENCES catalog_assets(id) ON DELETE CASCADE,
