 PRIMARY KEY(kind,key)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_book_evidence_jobs_turn ON catalog_book_evidence_jobs(turn,kind,key);
CREATE TABLE catalog_book_groups(
