CREATE TABLE compact_visibility_blocks(
 class_id INTEGER NOT NULL,
 generation INTEGER NOT NULL,
 library_id INTEGER NOT NULL,
 kind INTEGER NOT NULL,
 ordering INTEGER NOT NULL CHECK(ordering BETWEEN 0 AND 4),
 sort_value ANY NOT NULL,
 entity_id INTEGER NOT NULL,
 total INTEGER NOT NULL CHECK(total>=0),
 PRIMARY KEY(class_id,generation,library_id,kind,ordering,sort_value,entity_id)) WITHOUT ROWID, STRICT;
CREATE INDEX compact_visibility_blocks_full ON compact_visibility_blocks(class_id,generation,library_id,kind,ordering) WHERE total>2048;
