  WHERE NOT EXISTS(SELECT 1 FROM compact_visibility_blocks WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND (sort_value<lower(NEW.sort_key) OR sort_value=lower(NEW.sort_key) AND entity_id<=NEW.entity_id));
