-- END BLOCKS

-- ===== everything else
CREATE TABLE configuration(key TEXT PRIMARY KEY,value TEXT NOT NULL) STRICT;
CREATE TABLE accounts(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash BLOB NOT NULL,profile_id TEXT NOT NULL,epoch INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE libraries(id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,root TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE metadata_jobs(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE provider_evidence(item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_id INTEGER NOT NULL,payload TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(item_id,provider)) STRICT;
CREATE TABLE jobs(id TEXT PRIMARY KEY,library_id TEXT NOT NULL REFERENCES libraries(id),status TEXT NOT NULL,processed INTEGER NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL) STRICT;
CREATE TABLE scan_queue(job_id TEXT NOT NULL REFERENCES jobs(id),path TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(job_id,path)) STRICT;
CREATE TABLE playback_sessions(id TEXT PRIMARY KEY,session_hash TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id),asset_id TEXT NOT NULL REFERENCES catalog_assets(token),generation INTEGER NOT NULL,sequence INTEGER NOT NULL DEFAULT -1,state TEXT NOT NULL,grant_hash TEXT NOT NULL UNIQUE,grant_token TEXT NOT NULL,expires_at TEXT NOT NULL,request_id TEXT NOT NULL,duration REAL NOT NULL,mode TEXT NOT NULL DEFAULT 'direct',UNIQUE(account_id,profile_id,request_id)) STRICT;
CREATE TABLE progress_activity(profile_id TEXT NOT NULL,library_id TEXT NOT NULL REFERENCES libraries(id),item_id INTEGER NOT NULL,updated_at TEXT NOT NULL,state TEXT NOT NULL,PRIMARY KEY(profile_id,item_id),FOREIGN KEY(profile_id,item_id) REFERENCES progress(profile_id,item_id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_artifacts(session_id TEXT PRIMARY KEY,directory TEXT NOT NULL,status TEXT NOT NULL,error TEXT NOT NULL DEFAULT '', failure_code TEXT NOT NULL DEFAULT '', diagnostic TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE playback_requests(account_id TEXT NOT NULL,profile_id TEXT NOT NULL,request_id TEXT NOT NULL,item_id INTEGER NOT NULL,response TEXT NOT NULL,PRIMARY KEY(account_id,profile_id,request_id)) STRICT;
CREATE TABLE progress(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,position INTEGER NOT NULL,unit INTEGER NOT NULL DEFAULT 0 CHECK(unit BETWEEN 0 AND 99),completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)),playback_id TEXT NOT NULL,PRIMARY KEY(profile_id,item_id)) STRICT;
CREATE TABLE library_network_policy(library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,revision INTEGER NOT NULL,approvals_json TEXT NOT NULL) STRICT;
CREATE TABLE remote_playback(session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,descriptor_digest TEXT NOT NULL,network_revision INTEGER NOT NULL) STRICT;
CREATE TABLE book_resume(profile_id TEXT NOT NULL,book_id INTEGER NOT NULL REFERENCES catalog_entities(id),item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,playback_id TEXT NOT NULL,position INTEGER NOT NULL,unit INTEGER NOT NULL DEFAULT 0 CHECK(unit BETWEEN 0 AND 99),completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)),PRIMARY KEY(profile_id,book_id)) STRICT;
CREATE TABLE audio_tag_evidence(library_id TEXT NOT NULL REFERENCES libraries(id),asset_id TEXT NOT NULL REFERENCES catalog_assets(token),field TEXT NOT NULL,source TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(library_id,asset_id,field)) STRICT;
CREATE TABLE audio_source_metadata(library_id TEXT NOT NULL REFERENCES libraries(id),asset_id TEXT NOT NULL REFERENCES catalog_assets(token),issue TEXT NOT NULL DEFAULT '',PRIMARY KEY(library_id,asset_id)) STRICT;
CREATE TABLE episode_asset_boundaries(item_id INTEGER NOT NULL,asset_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('whole_source','unknown_multi_episode')),PRIMARY KEY(item_id,asset_id),FOREIGN KEY(item_id) REFERENCES catalog_entities(id) ON DELETE CASCADE,FOREIGN KEY(asset_id) REFERENCES catalog_assets(token) ON DELETE CASCADE) STRICT;
CREATE TABLE episodic_sources(library_id TEXT NOT NULL REFERENCES libraries(id),asset_id TEXT NOT NULL REFERENCES catalog_assets(token),manual INTEGER NOT NULL DEFAULT 0,issue TEXT NOT NULL DEFAULT '',source_name TEXT NOT NULL,PRIMARY KEY(library_id,asset_id)) STRICT;
CREATE TABLE policy(server_id TEXT PRIMARY KEY,revision INTEGER NOT NULL,payload TEXT NOT NULL,expires_at TEXT NOT NULL) STRICT;
CREATE TABLE restriction_outbox(operation_id TEXT PRIMARY KEY,local_revision INTEGER NOT NULL UNIQUE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending') STRICT;
CREATE TABLE restrictions(profile_id TEXT PRIMARY KEY,revision INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,allowed_libraries TEXT NOT NULL DEFAULT '[]') STRICT;
CREATE TABLE library_revisions(library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,revision INTEGER NOT NULL) STRICT;
CREATE TABLE viewer_revisions(profile_id TEXT NOT NULL,library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,revision INTEGER NOT NULL,PRIMARY KEY(profile_id,library_id)) STRICT;
CREATE TABLE personal_receipts(account_id TEXT NOT NULL,profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT '',PRIMARY KEY(account_id,profile_id,item_id,operation_id)) STRICT;
CREATE TABLE metadata_details(item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_id TEXT NOT NULL,source_url TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(item_id,provider)) STRICT;
CREATE TABLE metadata_ratings(item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,provider TEXT NOT NULL,value REAL NOT NULL,scale REAL NOT NULL,votes INTEGER NOT NULL,source_url TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(item_id,provider)) STRICT;
CREATE TABLE detail_jobs(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE playlist_shares(playlist_id TEXT NOT NULL REFERENCES catalog_playlists(token) ON DELETE CASCADE,authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('viewer','editor')),PRIMARY KEY(playlist_id,authority,account_id,profile_id)) STRICT;
CREATE TABLE playlist_receipts(authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(authority,account_id,profile_id,operation_id)) STRICT;
CREATE TABLE playlist_directory_revisions(authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(authority,account_id,profile_id)) STRICT;
CREATE TABLE metadata_provider_cooldowns(provider TEXT PRIMARY KEY,next_attempt TEXT NOT NULL) STRICT;
CREATE TABLE tvdb_jobs(show_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending_search',revision INTEGER NOT NULL DEFAULT 1,generation INTEGER NOT NULL DEFAULT 1,provider_id INTEGER NOT NULL DEFAULT 0,episode_order TEXT NOT NULL DEFAULT '',page INTEGER NOT NULL DEFAULT 0,apply_after TEXT NOT NULL DEFAULT '',staged_bytes INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',retry_status TEXT NOT NULL DEFAULT '',lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE tvdb_series_candidates(show_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL,name TEXT NOT NULL,year INTEGER NOT NULL,overview TEXT NOT NULL,payload TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(show_id,provider_id)) STRICT;
CREATE TABLE tvdb_episode_evidence(show_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,generation INTEGER NOT NULL,provider_id INTEGER NOT NULL,season_number INTEGER,number INTEGER,absolute_number INTEGER,title TEXT NOT NULL,overview TEXT NOT NULL,payload TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(show_id,generation,provider_id)) STRICT;
CREATE TABLE tvdb_episode_links(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL,observed_at TEXT NOT NULL) STRICT;
CREATE TABLE admin_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL) STRICT;
CREATE TABLE library_configuration(library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE job_observations(job_id TEXT PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,updated_at TEXT NOT NULL,finished_at TEXT) STRICT;
CREATE TABLE metadata_publication_heads(
 item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 incarnation TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))),
 source_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(source_revision)='integer' AND source_revision>0),
 identity_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(identity_revision)='integer' AND identity_revision>0),
 metadata_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(metadata_revision)='integer' AND metadata_revision>0)) STRICT;
CREATE TABLE metadata_provider_policies(
 library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(provider='tmdb'),
 incarnation TEXT NOT NULL DEFAULT (lower(hex(randomblob(16)))),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),
 language TEXT NOT NULL DEFAULT '' CHECK(length(language)<=64),
 region TEXT NOT NULL DEFAULT '' CHECK(length(region)<=2),
 refresh_mode TEXT NOT NULL DEFAULT 'replace_unlocked' CHECK(refresh_mode IN('fill_missing','replace_unlocked')),
 algorithm TEXT NOT NULL DEFAULT 'tmdb-exact-title-year-v1' CHECK(length(algorithm) BETWEEN 1 AND 128),
 PRIMARY KEY(library_id,provider)) STRICT;
CREATE TABLE metadata_work(
 item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 kind TEXT NOT NULL CHECK(kind IN('match','detail')),
 generation INTEGER NOT NULL DEFAULT 1 CHECK(typeof(generation)='integer' AND generation>0),
 lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(item_id,kind)) STRICT;
CREATE TABLE metadata_publication_operations(
 id TEXT PRIMARY KEY,item_id INTEGER NOT NULL,incarnation TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN('match','detail')),generation INTEGER NOT NULL,
 library_id TEXT NOT NULL,source_revision INTEGER NOT NULL,identity_revision INTEGER NOT NULL,metadata_revision INTEGER NOT NULL,
 qualification TEXT NOT NULL CHECK(qualification='catalog_observation'),
 provider TEXT NOT NULL CHECK(provider='tmdb'),entity_type TEXT NOT NULL CHECK(entity_type='movie'),
 accepted_provider_id INTEGER NOT NULL DEFAULT 0 CHECK(accepted_provider_id>=0),
 policy_incarnation TEXT NOT NULL,policy_revision INTEGER NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL,refresh_mode TEXT NOT NULL,algorithm TEXT NOT NULL,
 query_title TEXT NOT NULL CHECK(length(query_title)<=2048),query_year INTEGER NOT NULL,
 query_digest TEXT NOT NULL CHECK(length(query_digest)=64),result_digest TEXT NOT NULL DEFAULT '',
 result_provider_id INTEGER NOT NULL DEFAULT 0 CHECK(result_provider_id>=0),published_revision INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL CHECK(status IN('claimed','staged','applied','stale','failed')),
 created_at TEXT NOT NULL,finished_at TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '' CHECK(length(reason)<=128)) STRICT;
CREATE TABLE metadata_operation_identities(
 operation_id TEXT NOT NULL REFERENCES metadata_publication_operations(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(length(provider) BETWEEN 1 AND 64),entity_type TEXT NOT NULL CHECK(entity_type='movie'),provider_id INTEGER NOT NULL CHECK(provider_id>0),
 PRIMARY KEY(operation_id,provider)) STRICT;
CREATE TABLE metadata_operation_sources(
 operation_id TEXT NOT NULL REFERENCES metadata_publication_operations(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),asset_id TEXT NOT NULL,
 part_index INTEGER NOT NULL,start_seconds REAL NOT NULL,end_seconds REAL,
 path TEXT NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,available INTEGER NOT NULL,
 PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE metadata_stage_movies(
 operation_id TEXT PRIMARY KEY REFERENCES metadata_publication_operations(id) ON DELETE CASCADE,
 provider_id INTEGER NOT NULL CHECK(provider_id>0),title TEXT NOT NULL CHECK(length(title)<=2048),
 overview TEXT NOT NULL CHECK(length(overview)<=65536),poster_path TEXT NOT NULL CHECK(length(poster_path)<=2048),backdrop_path TEXT NOT NULL CHECK(length(backdrop_path)<=2048),
 vote_average REAL NOT NULL DEFAULT 0 CHECK(vote_average>=0 AND vote_average<=10),vote_count INTEGER NOT NULL DEFAULT 0 CHECK(vote_count>=0),
 raw_evidence TEXT NOT NULL DEFAULT '' CHECK(length(CAST(raw_evidence AS BLOB))<=1048576)) STRICT;
CREATE TABLE metadata_stage_genres(
 operation_id TEXT NOT NULL REFERENCES metadata_publication_operations(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<64),provider_id INTEGER NOT NULL CHECK(provider_id>0),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 200),
 PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE metadata_stage_credits(
 operation_id TEXT NOT NULL REFERENCES metadata_publication_operations(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<100),credit_id TEXT NOT NULL CHECK(length(credit_id) BETWEEN 1 AND 256),
 person_id INTEGER NOT NULL CHECK(person_id>0),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 300),role TEXT NOT NULL CHECK(length(role)<=500),department TEXT NOT NULL CHECK(length(department)<=200),
 PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE mb_jobs(kind TEXT NOT NULL CHECK(kind IN('album','song')),entity_id INTEGER NOT NULL,album_id INTEGER REFERENCES catalog_entities(id) ON DELETE CASCADE,item_id INTEGER REFERENCES catalog_entities(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','matched','needs_selection','unavailable','unresolved')),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>0),selected_id TEXT NOT NULL DEFAULT '',manual INTEGER NOT NULL DEFAULT 0 CHECK(manual IN(0,1)),review_search INTEGER NOT NULL DEFAULT 0 CHECK(review_search IN(0,1)),attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0),next_attempt TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',PRIMARY KEY(kind,entity_id),CHECK((kind='album' AND album_id=entity_id AND item_id IS NULL) OR(kind='song' AND item_id=entity_id AND album_id IS NULL))) STRICT;
CREATE TABLE mb_album_heads(album_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),membership_revision INTEGER NOT NULL DEFAULT 1 CHECK(membership_revision>0)) STRICT;
CREATE TABLE mb_song_heads(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE mb_provider_policies(library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),algorithm TEXT NOT NULL DEFAULT 'mb-exact-identity-v1' CHECK(algorithm='mb-exact-identity-v1')) STRICT;
CREATE TABLE mb_recording_evidence(revision_id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,digest TEXT NOT NULL CHECK(length(digest)=64),title TEXT NOT NULL,artist TEXT NOT NULL,length_millis INTEGER CHECK(length_millis IS NULL OR length_millis>=0),disambiguation TEXT NOT NULL,observed_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=4194304),sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),UNIQUE(revision_id,provider_id),UNIQUE(provider_id,digest)) STRICT;
CREATE TABLE mb_release_evidence(revision_id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,digest TEXT NOT NULL CHECK(length(digest)=64),title TEXT NOT NULL,artist TEXT NOT NULL,release_group_id TEXT NOT NULL,group_title TEXT NOT NULL,primary_type TEXT NOT NULL,date TEXT NOT NULL,country TEXT NOT NULL,barcode TEXT NOT NULL,disambiguation TEXT NOT NULL,observed_at TEXT NOT NULL,payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=4194304),sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),UNIQUE(revision_id,provider_id),UNIQUE(provider_id,digest)) STRICT;
CREATE TABLE mb_recording_credits(revision_id TEXT NOT NULL REFERENCES mb_recording_evidence(revision_id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),artist_id TEXT NOT NULL,name TEXT NOT NULL,artist_name TEXT NOT NULL,sort_name TEXT NOT NULL,disambiguation TEXT NOT NULL,join_phrase TEXT NOT NULL,PRIMARY KEY(revision_id,ordinal)) STRICT;
CREATE TABLE mb_release_credits(revision_id TEXT NOT NULL REFERENCES mb_release_evidence(revision_id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),artist_id TEXT NOT NULL,name TEXT NOT NULL,artist_name TEXT NOT NULL,sort_name TEXT NOT NULL,disambiguation TEXT NOT NULL,join_phrase TEXT NOT NULL,PRIMARY KEY(revision_id,ordinal)) STRICT;
CREATE TABLE mb_release_group_types(release_revision TEXT NOT NULL REFERENCES mb_release_evidence(revision_id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<64),value TEXT NOT NULL,PRIMARY KEY(release_revision,ordinal)) STRICT;
CREATE TABLE mb_release_media(release_revision TEXT NOT NULL REFERENCES mb_release_evidence(revision_id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(position>0),format TEXT NOT NULL,title TEXT NOT NULL,PRIMARY KEY(release_revision,position)) STRICT;
CREATE TABLE mb_release_tracks(release_revision TEXT NOT NULL,track_id TEXT NOT NULL,medium_position INTEGER NOT NULL,position INTEGER NOT NULL CHECK(position>0),number TEXT NOT NULL,title TEXT NOT NULL,artist TEXT NOT NULL,length_millis INTEGER CHECK(length_millis IS NULL OR length_millis>=0),recording_revision TEXT NOT NULL REFERENCES mb_recording_evidence(revision_id),PRIMARY KEY(release_revision,track_id),UNIQUE(release_revision,medium_position,position),FOREIGN KEY(release_revision,medium_position) REFERENCES mb_release_media(release_revision,position) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_track_credits(release_revision TEXT NOT NULL,track_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),artist_id TEXT NOT NULL,name TEXT NOT NULL,artist_name TEXT NOT NULL,sort_name TEXT NOT NULL,disambiguation TEXT NOT NULL,join_phrase TEXT NOT NULL,PRIMARY KEY(release_revision,track_id,ordinal),FOREIGN KEY(release_revision,track_id) REFERENCES mb_release_tracks(release_revision,track_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_recording_aliases(requested_id TEXT NOT NULL,canonical_id TEXT NOT NULL,evidence_revision TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(requested_id,evidence_revision),FOREIGN KEY(evidence_revision,canonical_id) REFERENCES mb_recording_evidence(revision_id,provider_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_release_aliases(requested_id TEXT NOT NULL,canonical_id TEXT NOT NULL,evidence_revision TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(requested_id,evidence_revision),FOREIGN KEY(evidence_revision,canonical_id) REFERENCES mb_release_evidence(revision_id,provider_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_album_links(album_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,release_revision TEXT NOT NULL,release_id TEXT NOT NULL,requested_id TEXT NOT NULL,observed_at TEXT NOT NULL,FOREIGN KEY(release_revision,release_id) REFERENCES mb_release_evidence(revision_id,provider_id)) STRICT;
CREATE TABLE mb_song_links(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,recording_revision TEXT,recording_id TEXT,release_revision TEXT,release_id TEXT,track_id TEXT,release_status TEXT NOT NULL DEFAULT 'unmatched',observed_at TEXT NOT NULL,CHECK((recording_revision IS NULL)=(recording_id IS NULL)),CHECK((release_revision IS NULL)=(release_id IS NULL)),CHECK(track_id IS NULL OR release_revision IS NOT NULL),FOREIGN KEY(recording_revision,recording_id) REFERENCES mb_recording_evidence(revision_id,provider_id),FOREIGN KEY(release_revision,release_id) REFERENCES mb_release_evidence(revision_id,provider_id),FOREIGN KEY(release_revision,track_id) REFERENCES mb_release_tracks(release_revision,track_id)) STRICT;
CREATE TABLE mb_publication_operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('album','song')),entity_id INTEGER NOT NULL,incarnation TEXT NOT NULL,job_generation INTEGER NOT NULL,lease TEXT NOT NULL,lease_until TEXT NOT NULL,library_id TEXT NOT NULL,policy_incarnation TEXT NOT NULL,policy_revision INTEGER NOT NULL,algorithm TEXT NOT NULL,base_revision INTEGER NOT NULL,item_incarnation TEXT NOT NULL DEFAULT '',item_source_revision INTEGER NOT NULL DEFAULT 0,item_identity_revision INTEGER NOT NULL DEFAULT 0,item_metadata_revision INTEGER NOT NULL DEFAULT 0,album_id INTEGER NOT NULL DEFAULT 0,album_incarnation TEXT NOT NULL DEFAULT '',album_revision INTEGER NOT NULL DEFAULT 0,album_membership_revision INTEGER NOT NULL DEFAULT 0,accepted_recording_revision TEXT REFERENCES mb_recording_evidence(revision_id),accepted_release_revision TEXT REFERENCES mb_release_evidence(revision_id),selected_id TEXT NOT NULL,manual INTEGER NOT NULL CHECK(manual IN(0,1)),review_search INTEGER NOT NULL CHECK(review_search IN(0,1)),query_title TEXT NOT NULL,query_artist TEXT NOT NULL,query_digest TEXT NOT NULL CHECK(length(query_digest)=64),hint_id TEXT NOT NULL DEFAULT '',hint_problem TEXT NOT NULL DEFAULT '',qualification TEXT NOT NULL CHECK(qualification='catalog_observation'),result_recording_revision TEXT REFERENCES mb_recording_evidence(revision_id),result_release_revision TEXT REFERENCES mb_release_evidence(revision_id),result_digest TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('claimed','staged','applied','stale','failed')),created_at TEXT NOT NULL,finished_at TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '',FOREIGN KEY(kind,entity_id) REFERENCES mb_jobs(kind,entity_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_operation_sources(operation_id TEXT NOT NULL REFERENCES mb_publication_operations(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),asset_id TEXT NOT NULL,part_index INTEGER NOT NULL,start_seconds REAL NOT NULL,end_seconds REAL,path TEXT NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,available INTEGER NOT NULL,PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE mb_operation_artists(operation_id TEXT NOT NULL REFERENCES mb_publication_operations(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),artist_id TEXT NOT NULL,name TEXT NOT NULL,PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE mb_candidates(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,provider_id TEXT NOT NULL,entity_type TEXT NOT NULL CHECK(entity_type IN('recording','release')),title TEXT NOT NULL,artist TEXT NOT NULL,edition TEXT NOT NULL,confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1),decision TEXT NOT NULL CHECK(decision IN('candidate','accepted','rejected','superseded')),query_digest TEXT NOT NULL CHECK(length(query_digest)=64),payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=1048576),observed_at TEXT NOT NULL,PRIMARY KEY(kind,entity_id,provider_id),FOREIGN KEY(kind,entity_id) REFERENCES mb_jobs(kind,entity_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_candidate_reasons(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,provider_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<16),reason TEXT NOT NULL,PRIMARY KEY(kind,entity_id,provider_id,ordinal),FOREIGN KEY(kind,entity_id,provider_id) REFERENCES mb_candidates(kind,entity_id,provider_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_selection_receipts(id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,job_generation INTEGER NOT NULL,actor_authority TEXT NOT NULL,actor_account_id TEXT NOT NULL,actor_profile_id TEXT NOT NULL,candidate_id TEXT NOT NULL,query_digest TEXT NOT NULL CHECK(length(query_digest)=64),prior_revision_id TEXT NOT NULL DEFAULT '',accepted_revision_id TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('pending','applied','superseded','failed')),created_at TEXT NOT NULL,finished_at TEXT NOT NULL DEFAULT '',FOREIGN KEY(kind,entity_id) REFERENCES mb_jobs(kind,entity_id) ON DELETE CASCADE) STRICT;
CREATE TABLE mb_album_reconciliations(album_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,release_revision TEXT NOT NULL REFERENCES mb_release_evidence(revision_id),membership_revision INTEGER NOT NULL,cursor TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('pending','complete')),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE mb_album_hint_scans(album_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,incarnation TEXT NOT NULL,base_revision INTEGER NOT NULL,membership_revision INTEGER NOT NULL,cursor TEXT NOT NULL DEFAULT '',hint_id TEXT NOT NULL DEFAULT '',problem TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('pending','complete'))) STRICT;
CREATE TABLE audio_metadata_policies(
  library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  local_mode TEXT NOT NULL DEFAULT 'prefer' CHECK(local_mode IN('off','supplement','prefer')),
  acoustid_enabled INTEGER NOT NULL DEFAULT 0 CHECK(acoustid_enabled IN(0,1))) STRICT;
CREATE TABLE audio_local_evidence(
  library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
  asset_id TEXT NOT NULL REFERENCES catalog_assets(token) ON DELETE CASCADE,
  ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<512),
  field TEXT NOT NULL,source TEXT NOT NULL,value TEXT NOT NULL,
  source_revision TEXT NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,observed_at TEXT NOT NULL,
  PRIMARY KEY(library_id,asset_id,ordinal)) STRICT;
CREATE TABLE music_acoustid_health(
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),configuration_digest TEXT NOT NULL,reason TEXT NOT NULL,observed_at TEXT NOT NULL) STRICT;
CREATE TABLE music_match_observations(
  kind TEXT NOT NULL,entity_id INTEGER NOT NULL,query_digest TEXT NOT NULL,
  fingerprint_status TEXT NOT NULL,provider_error TEXT NOT NULL DEFAULT '',
  confidence REAL NOT NULL DEFAULT 0,margin REAL NOT NULL DEFAULT 0,strong_signals INTEGER NOT NULL DEFAULT 0,
  algorithm TEXT NOT NULL DEFAULT 'music-evidence-v1',
  PRIMARY KEY(kind,entity_id),FOREIGN KEY(kind,entity_id) REFERENCES mb_jobs(kind,entity_id) ON DELETE CASCADE) STRICT;
CREATE TABLE tvdb_publication_heads(
 show_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),
 source_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(source_revision)='integer' AND source_revision>0),
 hierarchy_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(hierarchy_revision)='integer' AND hierarchy_revision>0),
 selection_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(selection_revision)='integer' AND selection_revision>0),
 descriptive_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(descriptive_revision)='integer' AND descriptive_revision>0)) STRICT;
CREATE TABLE tvdb_provider_policies(
 library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),
 algorithm TEXT NOT NULL DEFAULT 'tvdb-series-exact-title-year-v1' CHECK(algorithm='tvdb-series-exact-title-year-v1'),
 refresh_mode TEXT NOT NULL DEFAULT 'replace_unlocked' CHECK(refresh_mode IN('fill_missing','replace_unlocked'))) STRICT;
CREATE TABLE tvdb_publication_sets(
 show_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),
 generation INTEGER NOT NULL CHECK(generation>0),provider_id INTEGER NOT NULL CHECK(provider_id>0),
 episode_order TEXT NOT NULL CHECK(episode_order IN('official','dvd','absolute','default','alternate','regional')),
 policy_incarnation TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>0),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN(0,1)),
 UNIQUE(show_id,incarnation),UNIQUE(show_id,incarnation,generation)) STRICT;
CREATE TABLE tvdb_publication_pages(
 show_id INTEGER NOT NULL,set_incarnation TEXT NOT NULL,page INTEGER NOT NULL CHECK(page>=0 AND page<100),
 next_page INTEGER CHECK(next_page IS NULL OR next_page=page+1),
 row_count INTEGER NOT NULL DEFAULT 0 CHECK(row_count>=0 AND row_count<=1000),
 byte_count INTEGER NOT NULL DEFAULT 0 CHECK(byte_count>=0 AND byte_count<=16777216),
 result_digest TEXT NOT NULL DEFAULT '' CHECK(length(result_digest) IN(0,64)),
 content_revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(content_revision)='integer' AND content_revision>0),
 validated_revision INTEGER NOT NULL DEFAULT 0 CHECK(typeof(validated_revision)='integer' AND validated_revision>=0 AND validated_revision<=content_revision),
 PRIMARY KEY(show_id,set_incarnation,page),
 FOREIGN KEY(show_id,set_incarnation) REFERENCES tvdb_publication_sets(show_id,incarnation) ON DELETE CASCADE) STRICT;
CREATE TABLE tvdb_evidence_page_ownership(
 show_id INTEGER NOT NULL,generation INTEGER NOT NULL,provider_id INTEGER NOT NULL,
 set_incarnation TEXT NOT NULL,page INTEGER NOT NULL,
 PRIMARY KEY(show_id,generation,provider_id),
 FOREIGN KEY(show_id,generation,provider_id) REFERENCES tvdb_episode_evidence(show_id,generation,provider_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(show_id,set_incarnation,generation) REFERENCES tvdb_publication_sets(show_id,incarnation,generation) ON DELETE CASCADE,
 FOREIGN KEY(show_id,set_incarnation,page) REFERENCES tvdb_publication_pages(show_id,set_incarnation,page) ON DELETE CASCADE) STRICT;
CREATE TABLE tvdb_projection_coverage(
 show_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 set_incarnation TEXT NOT NULL,set_revision INTEGER NOT NULL,
 source_revision INTEGER NOT NULL,hierarchy_revision INTEGER NOT NULL,selection_revision INTEGER NOT NULL,
 policy_incarnation TEXT NOT NULL,policy_revision INTEGER NOT NULL,
 after_item TEXT NOT NULL DEFAULT '',complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN(0,1))) STRICT;
CREATE TABLE tvdb_publication_operations(
 id TEXT PRIMARY KEY,show_id INTEGER NOT NULL,show_incarnation TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN('search','page','projection')),
 library_id TEXT NOT NULL,query_title TEXT NOT NULL CHECK(length(query_title)<=2048),query_year INTEGER NOT NULL,
 job_generation INTEGER NOT NULL CHECK(job_generation>0),job_revision INTEGER NOT NULL CHECK(job_revision>0),lease_until TEXT NOT NULL,
 accepted_provider_id INTEGER NOT NULL DEFAULT 0 CHECK(accepted_provider_id>=0),episode_order TEXT NOT NULL CHECK(episode_order IN('','official','dvd','absolute','default','alternate','regional')),
 policy_incarnation TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>0),
 algorithm TEXT NOT NULL CHECK(algorithm='tvdb-series-exact-title-year-v1'),
 refresh_mode TEXT NOT NULL CHECK(refresh_mode IN('fill_missing','replace_unlocked')),
 source_revision INTEGER NOT NULL,hierarchy_revision INTEGER NOT NULL,selection_revision INTEGER NOT NULL,descriptive_revision INTEGER NOT NULL,
 set_incarnation TEXT NOT NULL DEFAULT '',set_revision INTEGER NOT NULL DEFAULT 0,
 page INTEGER NOT NULL DEFAULT 0 CHECK(page>=0 AND page<100),after_item TEXT NOT NULL DEFAULT '',
 input_digest TEXT NOT NULL CHECK(length(input_digest)=64),result_digest TEXT NOT NULL DEFAULT '' CHECK(length(result_digest) IN(0,64)),
 status TEXT NOT NULL CHECK(status IN('claimed','ready','applied','stale','failed')),
 created_at TEXT NOT NULL,finished_at TEXT NOT NULL DEFAULT '',reason TEXT NOT NULL DEFAULT '' CHECK(length(reason)<=128)) STRICT;
CREATE TABLE tvdb_projection_targets(
 operation_id TEXT NOT NULL REFERENCES tvdb_publication_operations(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<100),item_id INTEGER NOT NULL,item_incarnation TEXT NOT NULL,
 source_revision INTEGER NOT NULL,identity_revision INTEGER NOT NULL,metadata_revision INTEGER NOT NULL,
 library_id TEXT NOT NULL,show_id INTEGER NOT NULL,season_id INTEGER,season_number INTEGER,
 numbering TEXT NOT NULL CHECK(numbering IN('seasonal','absolute')),number INTEGER NOT NULL,
 local_identity_status TEXT NOT NULL CHECK(local_identity_status IN('parsed','manual')),
 accepted_provider_id INTEGER NOT NULL DEFAULT 0 CHECK(accepted_provider_id>=0),
 result_status TEXT NOT NULL CHECK(result_status IN('matched','not_found','ambiguous','order_mismatch','manual_preserved','identity_conflict')),
 result_provider_id INTEGER NOT NULL DEFAULT 0 CHECK(result_provider_id>=0),
 title TEXT NOT NULL DEFAULT '' CHECK(length(title)<=2048),overview TEXT NOT NULL DEFAULT '' CHECK(length(overview)<=65536),
 evidence_payload TEXT NOT NULL DEFAULT '' CHECK(length(CAST(evidence_payload AS BLOB))<=1048576),
 PRIMARY KEY(operation_id,ordinal),UNIQUE(operation_id,item_id)) STRICT;
CREATE TABLE tvdb_publication_candidates(
 operation_id TEXT NOT NULL REFERENCES tvdb_publication_operations(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<25),provider_id INTEGER NOT NULL CHECK(provider_id>0),
 name TEXT NOT NULL CHECK(length(name)<=2048),year INTEGER NOT NULL,overview TEXT NOT NULL CHECK(length(overview)<=65536),
 payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=1048576),
 PRIMARY KEY(operation_id,ordinal),UNIQUE(operation_id,provider_id)) STRICT;
CREATE TABLE tvdb_publication_candidate_aliases(
 operation_id TEXT NOT NULL,candidate_ordinal INTEGER NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<128),
 alias TEXT NOT NULL CHECK(length(alias) BETWEEN 1 AND 2048),
 PRIMARY KEY(operation_id,candidate_ordinal,ordinal),
 FOREIGN KEY(operation_id,candidate_ordinal) REFERENCES tvdb_publication_candidates(operation_id,ordinal) ON DELETE CASCADE) STRICT;
CREATE TABLE metadata_movie_candidates(item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL,title TEXT NOT NULL,year INTEGER NOT NULL,payload TEXT NOT NULL,source_fence TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(item_id,provider_id)) STRICT;
CREATE TABLE metadata_movie_selections(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,provider_id INTEGER NOT NULL,revision INTEGER NOT NULL,locked INTEGER NOT NULL,status TEXT NOT NULL,actor TEXT NOT NULL,observed_at TEXT NOT NULL) STRICT;
CREATE TABLE metadata_owner_fields(
 kind TEXT NOT NULL,entity_id INTEGER NOT NULL,field TEXT NOT NULL,value TEXT NOT NULL,automatic_value TEXT NOT NULL,
 locked INTEGER NOT NULL CHECK(locked IN(0,1)),actor TEXT NOT NULL,observed_at TEXT NOT NULL,
 PRIMARY KEY(kind,entity_id,field)) STRICT;
CREATE TABLE metadata_owner_history(
 id INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,base_revision TEXT NOT NULL,
 revision TEXT NOT NULL,trigger TEXT NOT NULL,actor TEXT NOT NULL,observed_at TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL) STRICT;
CREATE TABLE metadata_relationship_decisions(
 kind TEXT NOT NULL,entity_id INTEGER NOT NULL,relationship TEXT NOT NULL,value_json TEXT NOT NULL,
 source TEXT NOT NULL,locked INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,observed_at TEXT NOT NULL,
 PRIMARY KEY(kind,entity_id,relationship)) STRICT;
CREATE TABLE metadata_repair_cascades(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,library_id TEXT NOT NULL,actor TEXT NOT NULL,
 intent TEXT NOT NULL,base_revision TEXT NOT NULL,after_item TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending',
 processed INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL) STRICT;
CREATE TABLE metadata_repair_cascade_items(
 operation_id TEXT NOT NULL REFERENCES metadata_repair_cascades(id) ON DELETE CASCADE,item_id INTEGER NOT NULL,
 base_revision TEXT NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',PRIMARY KEY(operation_id,item_id)) STRICT;
CREATE TABLE artwork_entity_heads(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(kind,entity_id)) STRICT;
CREATE TABLE artwork_objects(
 digest TEXT PRIMARY KEY,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,bytes INTEGER NOT NULL,
 created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ready' CHECK(status IN('ready','deleting'))) STRICT;
CREATE TABLE artwork_candidates(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,role TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',
 provider TEXT NOT NULL,image_id TEXT NOT NULL,origin TEXT NOT NULL,locale TEXT NOT NULL DEFAULT '',rank REAL NOT NULL DEFAULT 0,
 attribution TEXT NOT NULL,source_fence TEXT NOT NULL,observed_at TEXT NOT NULL, votes INTEGER CHECK(votes IS NULL OR votes>=0),
 UNIQUE(kind,entity_id,role,subject,provider,image_id)) STRICT;
CREATE TABLE artwork_selections(
 kind TEXT NOT NULL,entity_id INTEGER NOT NULL,role TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',
 candidate_id TEXT NOT NULL REFERENCES artwork_candidates(id),digest TEXT NOT NULL REFERENCES artwork_objects(digest),
 thumbnail_digest TEXT NOT NULL REFERENCES artwork_objects(digest),locked INTEGER NOT NULL DEFAULT 0,
 revision INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,observed_at TEXT NOT NULL,
 PRIMARY KEY(kind,entity_id,role,subject)) STRICT;
CREATE TABLE artwork_jobs(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,role TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',
 candidate_id TEXT NOT NULL DEFAULT '',origin TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL DEFAULT '',
 source_fence TEXT NOT NULL DEFAULT '',selection_revision INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',
 lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',actor TEXT NOT NULL DEFAULT '',
 locked INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,preview INTEGER NOT NULL DEFAULT 0,
 UNIQUE(kind,entity_id,role,subject,preview)) STRICT;
CREATE TABLE artwork_previews(candidate_id TEXT PRIMARY KEY REFERENCES artwork_candidates(id) ON DELETE CASCADE,digest TEXT NOT NULL REFERENCES artwork_objects(digest),source_fence TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TABLE artwork_discovery(
 kind TEXT NOT NULL,entity_id INTEGER NOT NULL,provider TEXT NOT NULL,identity TEXT NOT NULL,source_fence TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',
 lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(kind,entity_id,provider)) STRICT;
CREATE TABLE artwork_dirty(kind TEXT NOT NULL,entity_id INTEGER NOT NULL,PRIMARY KEY(kind,entity_id)) STRICT;
CREATE TABLE playback_origin_roots(id TEXT NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES libraries(id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_assets(id TEXT NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_assets(token) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_items(id INTEGER NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_associations(item_id INTEGER NOT NULL,asset_id TEXT NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(item_id,asset_id),FOREIGN KEY(item_id) REFERENCES catalog_entities(id) ON DELETE CASCADE,FOREIGN KEY(asset_id) REFERENCES catalog_assets(token) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_shows(id INTEGER NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_seasons(id INTEGER NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_books(id INTEGER NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE playback_origin_albums(id INTEGER NOT NULL,
 incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))) CHECK(length(incarnation)=32 AND incarnation NOT GLOB '*[^0-9a-f]*'),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0),
 PRIMARY KEY(id), FOREIGN KEY(id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE asset_stream_facts(asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,revision INTEGER NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,fingerprint TEXT NOT NULL,detail_version INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE asset_streams(asset_id TEXT NOT NULL REFERENCES asset_stream_facts(asset_id) ON DELETE CASCADE,stream_index INTEGER NOT NULL,type TEXT NOT NULL,codec TEXT NOT NULL,language TEXT NOT NULL,title TEXT NOT NULL,channels INTEGER NOT NULL,channel_layout TEXT NOT NULL,is_default INTEGER NOT NULL,is_forced INTEGER NOT NULL,color_transfer TEXT NOT NULL DEFAULT '',color_primaries TEXT NOT NULL DEFAULT '',detail_json TEXT NOT NULL DEFAULT '',PRIMARY KEY(asset_id,stream_index)) STRICT;
CREATE TABLE playback_hls_reservations(session_id TEXT PRIMARY KEY,bytes INTEGER NOT NULL CHECK(bytes=4294967296)) STRICT;
CREATE TABLE asset_subtitle_facts(asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,revision INTEGER NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,origin_us INTEGER NOT NULL,timing_known INTEGER NOT NULL,status TEXT NOT NULL,fingerprint TEXT NOT NULL) STRICT;
CREATE TABLE subtitle_sidecars(id TEXT PRIMARY KEY,path TEXT NOT NULL UNIQUE,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,digest TEXT NOT NULL) STRICT;
CREATE TABLE asset_subtitles(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES asset_subtitle_facts(asset_id) ON DELETE CASCADE,origin TEXT NOT NULL CHECK(origin IN ('embedded','sidecar')),locator TEXT NOT NULL,stream_index INTEGER NOT NULL,sidecar_id TEXT REFERENCES subtitle_sidecars(id),format TEXT NOT NULL,language TEXT NOT NULL,title TEXT NOT NULL,is_default INTEGER NOT NULL,is_forced INTEGER NOT NULL,reason TEXT NOT NULL,UNIQUE(asset_id,origin,locator),CHECK((origin='embedded' AND sidecar_id IS NULL AND stream_index>=0) OR (origin='sidecar' AND sidecar_id IS NOT NULL AND stream_index=-1))) STRICT;
CREATE TABLE playback_subtitle_plans(session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,revision TEXT NOT NULL UNIQUE,policy_version INTEGER NOT NULL CHECK(policy_version=1),facts_revision INTEGER NOT NULL,association_revision INTEGER NOT NULL,origin_us INTEGER NOT NULL,status TEXT NOT NULL,reason TEXT NOT NULL,clock INTEGER,chunk_ms INTEGER NOT NULL CHECK(chunk_ms=240000)) STRICT;
CREATE TABLE playback_subtitle_tracks(session_id TEXT NOT NULL REFERENCES playback_subtitle_plans(session_id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal>=0 AND ordinal<8),id TEXT NOT NULL,origin TEXT NOT NULL,locator TEXT NOT NULL,stream_index INTEGER NOT NULL,sidecar_id TEXT,source_size INTEGER NOT NULL,source_modified_ns INTEGER NOT NULL,source_digest TEXT NOT NULL,format TEXT NOT NULL,label TEXT NOT NULL,language TEXT NOT NULL,is_default INTEGER NOT NULL,is_forced INTEGER NOT NULL,group_id TEXT NOT NULL,manifest_name TEXT NOT NULL,playlist_file TEXT NOT NULL,PRIMARY KEY(session_id,ordinal),UNIQUE(session_id,id),UNIQUE(session_id,playlist_file)) STRICT;
CREATE TABLE playback_subtitle_files(session_id TEXT NOT NULL REFERENCES playback_subtitle_plans(session_id) ON DELETE CASCADE,name TEXT NOT NULL,track_ordinal INTEGER NOT NULL,size INTEGER NOT NULL,digest TEXT NOT NULL,PRIMARY KEY(session_id,name),FOREIGN KEY(session_id,track_ordinal) REFERENCES playback_subtitle_tracks(session_id,ordinal) ON DELETE CASCADE) STRICT;
CREATE TABLE subtitle_collections(
  item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE subtitle_resources(
  id TEXT PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES catalog_assets(token), scope TEXT NOT NULL CHECK(scope IN ('shared','personal')),
  owner TEXT NOT NULL, current_revision INTEGER NOT NULL CHECK(current_revision>0),
  deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)),
  discovery_id TEXT NOT NULL DEFAULT '', discovery_revision INTEGER NOT NULL DEFAULT 0,
  CHECK((scope='shared' AND owner='') OR (scope='personal' AND owner!=''))) STRICT;
CREATE TABLE subtitle_revisions(
  resource_id TEXT NOT NULL REFERENCES subtitle_resources(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL CHECK(revision>0), digest TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0),
  format TEXT NOT NULL, language TEXT NOT NULL, title TEXT NOT NULL,
  origin TEXT NOT NULL CHECK(origin IN ('upload','sidecar','embedded','provider')),
  provider TEXT NOT NULL DEFAULT '', attribution TEXT NOT NULL DEFAULT '', rights TEXT NOT NULL,
  original_digest TEXT NOT NULL, offset_us INTEGER NOT NULL DEFAULT 0,
  source_size INTEGER NOT NULL, source_modified_ns INTEGER NOT NULL,
  source_facts_revision INTEGER NOT NULL, created_at TEXT NOT NULL,
  PRIMARY KEY(resource_id,revision)) STRICT;
CREATE TABLE subtitle_render_revisions(
 resource_id TEXT NOT NULL, revision INTEGER NOT NULL,
 renderer TEXT NOT NULL CHECK(renderer IN ('external_text','burn_in')),
 is_default INTEGER NOT NULL DEFAULT 0, is_forced INTEGER NOT NULL DEFAULT 0,
 source_evidence TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(resource_id,revision),
 FOREIGN KEY(resource_id,revision) REFERENCES subtitle_revisions(resource_id,revision) ON DELETE CASCADE) STRICT;
CREATE TABLE subtitle_inventory_evidence(
 asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,
 revision INTEGER NOT NULL, evidence TEXT NOT NULL) STRICT;
CREATE TABLE subtitle_remote_sessions(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 evidence TEXT NOT NULL) STRICT;
CREATE TABLE playback_subtitle_presentations(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 render_id TEXT NOT NULL, generation INTEGER NOT NULL, position_us INTEGER NOT NULL,
 policy_revision INTEGER NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE subtitle_operations(
  actor TEXT NOT NULL, operation_id TEXT NOT NULL, request_digest TEXT NOT NULL,
  item_id INTEGER NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL,
  PRIMARY KEY(actor,operation_id)) STRICT;
CREATE TABLE subtitle_provider_candidates(
  id TEXT PRIMARY KEY, actor TEXT NOT NULL, item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL, source_size INTEGER NOT NULL, source_modified_ns INTEGER NOT NULL,
  provider TEXT NOT NULL, file_id INTEGER NOT NULL, language TEXT NOT NULL,
  title TEXT NOT NULL, attribution TEXT NOT NULL, expires_at TEXT NOT NULL) STRICT;
CREATE TABLE playback_subtitle_state(
  session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
  generation INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
  resource_id TEXT NOT NULL DEFAULT '', resource_revision INTEGER NOT NULL DEFAULT 0,
  offset_us INTEGER NOT NULL DEFAULT 0, renderer TEXT NOT NULL DEFAULT 'external_text') STRICT;
CREATE TABLE subtitle_selection_operations(
  actor TEXT NOT NULL, operation_id TEXT NOT NULL, request_digest TEXT NOT NULL,
  session_id TEXT NOT NULL REFERENCES playback_sessions(id) ON DELETE CASCADE,
  selection_revision INTEGER NOT NULL, created_at TEXT NOT NULL,
  PRIMARY KEY(actor,operation_id)) STRICT;
CREATE TABLE playback_manifest_subtitles(
 session_id TEXT NOT NULL REFERENCES playback_sessions(id) ON DELETE CASCADE,
 resource_id TEXT NOT NULL,resource_revision INTEGER NOT NULL,
 PRIMARY KEY(session_id,resource_id,resource_revision),
 FOREIGN KEY(resource_id,resource_revision) REFERENCES subtitle_revisions(resource_id,revision)) STRICT;
CREATE TABLE playback_subtitle_pins(
  session_id TEXT NOT NULL REFERENCES playback_sessions(id) ON DELETE CASCADE,
  resource_id TEXT NOT NULL, resource_revision INTEGER NOT NULL,
  PRIMARY KEY(session_id,resource_id,resource_revision),
  FOREIGN KEY(resource_id,resource_revision) REFERENCES subtitle_revisions(resource_id,revision)) STRICT;
CREATE TABLE playback_observations(ordinal INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL UNIQUE REFERENCES playback_sessions(id) ON DELETE CASCADE,created_at TEXT,reported_at TEXT,position REAL) STRICT;
CREATE TABLE playback_admin_operations(operation_id TEXT PRIMARY KEY,actor TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,created_at INTEGER NOT NULL) STRICT;
CREATE TABLE playback_delivery_plans(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 profile TEXT NOT NULL,source_id TEXT NOT NULL,source_size INTEGER NOT NULL,source_modified_ns INTEGER NOT NULL,
 facts_revision INTEGER NOT NULL CHECK(facts_revision>=0),source_container TEXT NOT NULL,source_video TEXT NOT NULL,source_audio TEXT NOT NULL,duration REAL NOT NULL,
 mode TEXT NOT NULL CHECK(mode IN ('direct','remote','hls')),
 strategy TEXT NOT NULL CHECK(strategy IN ('original','copy_remux','audio_conversion','video_conversion')),
 reason TEXT NOT NULL,output_container TEXT NOT NULL,video_action TEXT NOT NULL,audio_action TEXT NOT NULL,output_video TEXT NOT NULL,output_audio TEXT NOT NULL,audio_channels INTEGER NOT NULL,
 reason_codes TEXT NOT NULL DEFAULT '',
 quality_id TEXT NOT NULL DEFAULT 'auto',
 target_width INTEGER NOT NULL DEFAULT 0 CHECK(target_width>=0 AND target_width<=32768),
 target_height INTEGER NOT NULL DEFAULT 0 CHECK(target_height>=0 AND target_height<=4320),
 video_bitrate INTEGER NOT NULL DEFAULT 0 CHECK(video_bitrate>=0),
 audio_bitrate INTEGER NOT NULL DEFAULT 0 CHECK(audio_bitrate>=0),
 tone_map INTEGER NOT NULL DEFAULT 0 CHECK(tone_map IN (0,1)),
 tone_map_algorithm TEXT NOT NULL DEFAULT '',
 hardware_backend TEXT NOT NULL DEFAULT 'software',
 hardware_device TEXT NOT NULL DEFAULT '',
 hardware_native INTEGER NOT NULL DEFAULT 0 CHECK(hardware_native IN (0,1)),
 software_preset TEXT NOT NULL DEFAULT '',
 policy_json TEXT NOT NULL DEFAULT ''
 , trace_json TEXT NOT NULL DEFAULT '', audio_stream INTEGER NOT NULL DEFAULT -1, deinterlace INTEGER NOT NULL DEFAULT 0 CHECK(deinterlace IN (0,1)), max_frame_rate REAL NOT NULL DEFAULT 0, downmix TEXT NOT NULL DEFAULT '', renditions_json TEXT NOT NULL DEFAULT '', burn_in_json TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE playback_copy_timelines(
 asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,
 size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,
 boundaries TEXT NOT NULL CHECK(length(boundaries)<=1048576),
 created_at_ms INTEGER NOT NULL
 ) STRICT;
CREATE TABLE playback_hls_windows(
 session_id TEXT NOT NULL REFERENCES playback_sessions(id) ON DELETE CASCADE,
 start_index INTEGER NOT NULL CHECK(start_index>=0),
 status TEXT NOT NULL CHECK(status IN ('running','throttled','complete','failed')),
 highest_produced INTEGER NOT NULL DEFAULT -1,
 started_at_ms INTEGER NOT NULL,
 PRIMARY KEY(session_id,start_index)
 ) STRICT;
CREATE TABLE playback_hls_demand(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 highest_served INTEGER NOT NULL DEFAULT -1,
 throttled INTEGER NOT NULL DEFAULT 0 CHECK(throttled IN (0,1))
 ) STRICT;
CREATE TABLE playback_hls_stages(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 backend TEXT NOT NULL,
 stages_json TEXT NOT NULL
 ) STRICT;
CREATE TABLE playback_vod_plans(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 policy TEXT NOT NULL,source_size INTEGER NOT NULL,source_modified_ns INTEGER NOT NULL,
 duration REAL NOT NULL,fps REAL NOT NULL,video_index INTEGER NOT NULL,audio_index INTEGER NOT NULL,
 width INTEGER NOT NULL,height INTEGER NOT NULL,interval_count INTEGER NOT NULL,
 manifest_hash TEXT NOT NULL,status TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0,
 analysis_wall REAL NOT NULL,analysis_cpu REAL NOT NULL,probe_output_bytes INTEGER NOT NULL) STRICT;
CREATE TABLE playback_vod_intervals(
 session_id TEXT NOT NULL REFERENCES playback_vod_plans(session_id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL,status TEXT NOT NULL,generation INTEGER NOT NULL DEFAULT 0,
 requested_order INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,sha256 TEXT NOT NULL DEFAULT '',
 start REAL NOT NULL,end REAL NOT NULL,decode_from REAL NOT NULL DEFAULT 0,
 encode_wall REAL NOT NULL DEFAULT 0,encode_cpu REAL NOT NULL DEFAULT 0,probe_wall REAL NOT NULL DEFAULT 0,
 attempts INTEGER NOT NULL DEFAULT 0,error_code TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(session_id,ordinal)) STRICT;
CREATE TABLE asset_chapter_facts(asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,revision INTEGER NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL,status TEXT NOT NULL,fingerprint TEXT NOT NULL) STRICT;
CREATE TABLE asset_chapters(asset_id TEXT NOT NULL REFERENCES asset_chapter_facts(asset_id) ON DELETE CASCADE,chapter_index INTEGER NOT NULL,title TEXT NOT NULL,start_seconds REAL NOT NULL,end_seconds REAL NOT NULL,PRIMARY KEY(asset_id,chapter_index)) STRICT;
CREATE TABLE playback_source_pins(session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,asset_id TEXT NOT NULL,size INTEGER NOT NULL,modified_ns INTEGER NOT NULL) STRICT;
CREATE TABLE authorization_session_families(
 id TEXT PRIMARY KEY,
 server_id TEXT NOT NULL CHECK(length(server_id)>0),
 account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 authority TEXT NOT NULL CHECK(authority IN ('local','hosted')),
 role TEXT NOT NULL, epoch INTEGER NOT NULL,
 authorization_horizon TEXT NOT NULL,
 current_generation INTEGER NOT NULL CHECK(current_generation>0),
 revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN (0,1))
, revoked_reason TEXT NOT NULL DEFAULT ''
 CHECK(revoked_reason IN ('','refresh_reuse','explicit_signout','admin_revoke','membership_removed','device_disapproved','password_change')), revoked_at TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE authorization_family_tokens(
 token_hash TEXT PRIMARY KEY,
 family_id TEXT NOT NULL REFERENCES authorization_session_families(id),
 generation INTEGER NOT NULL CHECK(generation>0),
 expires_at TEXT NOT NULL,
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN (0,1)),
 UNIQUE(family_id,generation)
) STRICT;
CREATE TABLE playback_owner_policy(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(revision>0),
 transcoding_enabled INTEGER NOT NULL CHECK(transcoding_enabled IN (0,1)),
 per_account_cap INTEGER CHECK(per_account_cap IS NULL OR per_account_cap>0),
 server_cap INTEGER CHECK(server_cap IS NULL OR server_cap>0)
) STRICT;
CREATE TABLE playback_marker_skips(
  playback_id TEXT NOT NULL,
  marker_id TEXT NOT NULL,
  mode TEXT NOT NULL CHECK(mode IN('automatic','manual')),
  position_us INTEGER NOT NULL CHECK(position_us>=0),
  generation INTEGER NOT NULL CHECK(generation>0),
  created_ms INTEGER NOT NULL,
  PRIMARY KEY(playback_id,marker_id)
 ) STRICT;
CREATE TABLE playback_preparation_episode_bindings(
 attempt_id TEXT PRIMARY KEY REFERENCES playback_preparation_attempts(id),
 show_id INTEGER NOT NULL,show_library_id TEXT NOT NULL,show_incarnation TEXT NOT NULL,show_revision INTEGER NOT NULL CHECK(show_revision>0),
 season_id INTEGER,season_show_id TEXT,season_number INTEGER,season_incarnation TEXT,season_revision INTEGER,
 numbering TEXT NOT NULL CHECK(numbering IN ('seasonal','absolute')),number INTEGER NOT NULL CHECK(number>0 AND number<=9999),
 ordering_basis TEXT NOT NULL,local_identity_status TEXT NOT NULL CHECK(local_identity_status IN ('parsed','manual')),
 CHECK((numbering='absolute' AND season_id IS NULL AND season_show_id IS NULL AND season_number IS NULL AND season_incarnation IS NULL AND season_revision IS NULL) OR
       (numbering='seasonal' AND season_id IS NOT NULL AND season_show_id IS NOT NULL AND season_show_id=show_id AND season_number IS NOT NULL AND season_number>=0 AND season_number<=99 AND season_incarnation IS NOT NULL AND season_revision IS NOT NULL AND season_revision>0))
) STRICT;
CREATE TABLE playback_preparation_book_bindings(
 attempt_id TEXT PRIMARY KEY REFERENCES playback_preparation_attempts(id),book_id INTEGER NOT NULL,library_id TEXT NOT NULL,
 incarnation TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),
 disc_number INTEGER CHECK(disc_number IS NULL OR disc_number>=0),part_number INTEGER CHECK(part_number IS NULL OR part_number>=0)
) STRICT;
CREATE TABLE playback_source_versions(
 id TEXT PRIMARY KEY,evidence_kind TEXT NOT NULL CHECK(evidence_kind IN ('local_revision','strong_etag','immutable_provider_version','content_sha256')),
 protected_scope TEXT NOT NULL,protected_object TEXT NOT NULL,protected_revision TEXT NOT NULL,
 size INTEGER NOT NULL CHECK(size>=0),no_in_place_mutation INTEGER NOT NULL CHECK(no_in_place_mutation IN (0,1))
) STRICT;
CREATE TABLE playback_observed_acquisitions(
 id TEXT PRIMARY KEY,attempt_id TEXT NOT NULL REFERENCES playback_preparation_attempts(id),
 access TEXT CHECK(access IS NULL OR access IN ('finite_random','finite_sequential','growing')),
 length_bytes INTEGER CHECK(length_bytes IS NULL OR length_bytes>=0),
 continuity TEXT NOT NULL CHECK(continuity IN ('intact','lost')),
 highest_observation INTEGER NOT NULL CHECK(highest_observation>0),UNIQUE(id,attempt_id)
) STRICT;
CREATE TABLE playback_source_observations(
 acquisition_id TEXT NOT NULL REFERENCES playback_observed_acquisitions(id),sequence INTEGER NOT NULL CHECK(sequence>0),
 root_binding_id TEXT NOT NULL,object_binding_id TEXT NOT NULL,
 size INTEGER CHECK(size IS NULL OR size>=0),modified_ns INTEGER,change_token TEXT,
 PRIMARY KEY(acquisition_id,sequence)
) STRICT;
CREATE TABLE playback_preparation_dependencies(
 attempt_id TEXT NOT NULL REFERENCES playback_preparation_attempts(id),dependency_id TEXT NOT NULL,role TEXT NOT NULL,
 reference_kind TEXT NOT NULL CHECK(reference_kind IN ('strong_version','observed_acquisition')),
 source_version_id TEXT REFERENCES playback_source_versions(id),acquisition_id TEXT REFERENCES playback_observed_acquisitions(id),
 observation_first INTEGER,observation_last INTEGER,protected_digest TEXT,
 PRIMARY KEY(attempt_id,dependency_id),
 FOREIGN KEY(acquisition_id,attempt_id) REFERENCES playback_observed_acquisitions(id,attempt_id),
 CHECK((reference_kind='strong_version' AND source_version_id IS NOT NULL AND acquisition_id IS NULL AND observation_first IS NULL AND observation_last IS NULL) OR
       (reference_kind='observed_acquisition' AND source_version_id IS NULL AND acquisition_id IS NOT NULL AND observation_first IS NOT NULL AND observation_last IS NOT NULL AND observation_first>0 AND observation_last>=observation_first))
) STRICT;
CREATE TABLE media_analyses (
 publication_id TEXT PRIMARY KEY, identity_digest TEXT NOT NULL,
 attempt_id TEXT NOT NULL, process_owner TEXT NOT NULL,
 source_kind TEXT NOT NULL CHECK(source_kind IN ('observed_acquisition','strong_version')), source_id TEXT NOT NULL,
 tool_sha256 TEXT NOT NULL, tool_version TEXT NOT NULL, schema_version INTEGER NOT NULL,
 observation_first INTEGER, observation_last INTEGER,
 root_binding_id TEXT, object_binding_id TEXT,
 size_known INTEGER, size_value INTEGER,
 modified_known INTEGER, modified_value INTEGER, change_token TEXT,
 final_sequence INTEGER, continuity TEXT,
 format_start_num INTEGER, format_start_den INTEGER,
 format_duration_num INTEGER, format_duration_den INTEGER
) STRICT;
CREATE TABLE media_analysis_dependencies (
 publication_id TEXT NOT NULL REFERENCES media_analyses(publication_id), dependency_id TEXT NOT NULL,
 role TEXT NOT NULL, reference_kind TEXT NOT NULL, reference_id TEXT NOT NULL, evidence_json TEXT NOT NULL,
 PRIMARY KEY(publication_id,dependency_id)
) STRICT;
CREATE TABLE media_analysis_formats (
 publication_id TEXT NOT NULL REFERENCES media_analyses(publication_id), ordinal INTEGER NOT NULL,
 name TEXT NOT NULL, PRIMARY KEY(publication_id,ordinal)
) STRICT;
CREATE TABLE media_analysis_streams (
 publication_id TEXT NOT NULL REFERENCES media_analyses(publication_id), stream_index INTEGER NOT NULL,
 kind TEXT NOT NULL, codec TEXT NOT NULL, is_default INTEGER NOT NULL,
 timebase_num INTEGER, timebase_den INTEGER, start_ticks INTEGER, duration_ticks INTEGER,
 width INTEGER, height INTEGER, sample_rate INTEGER, channels INTEGER,
 PRIMARY KEY(publication_id,stream_index)
) STRICT;
CREATE TABLE media_analysis_chunks (
 publication_id TEXT NOT NULL REFERENCES media_analyses(publication_id), offset_bytes INTEGER NOT NULL,
 length_bytes INTEGER NOT NULL, object_digest TEXT NOT NULL, object_size INTEGER NOT NULL,
 source_kind TEXT NOT NULL, source_id TEXT NOT NULL, observation_first INTEGER,
 observation_last INTEGER, PRIMARY KEY(publication_id,offset_bytes)
) STRICT;
CREATE TABLE media_analysis_item_mappings (
 publication_id TEXT NOT NULL REFERENCES media_analyses(publication_id), item_id INTEGER NOT NULL,
 asset_id TEXT NOT NULL, library_id TEXT NOT NULL, root_id TEXT NOT NULL,
 selection_digest TEXT NOT NULL,
 root_incarnation TEXT NOT NULL, root_revision INTEGER NOT NULL,
 asset_incarnation TEXT NOT NULL, asset_revision INTEGER NOT NULL,
 item_incarnation TEXT NOT NULL, item_revision INTEGER NOT NULL,
 association_incarnation TEXT NOT NULL, association_revision INTEGER NOT NULL,
 playback_id TEXT NOT NULL, presentation_id TEXT NOT NULL,
 desired_revision INTEGER NOT NULL, ownership_revision INTEGER NOT NULL,
 lease_generation INTEGER NOT NULL, lease_authority_revision INTEGER NOT NULL,
 policy_revision INTEGER NOT NULL, stream_index INTEGER NOT NULL,
 source_start_num INTEGER NOT NULL, source_start_den INTEGER NOT NULL,
 source_end_num INTEGER NOT NULL, source_end_den INTEGER NOT NULL,
 duration_us INTEGER NOT NULL CHECK(duration_us>0),
 PRIMARY KEY(publication_id,item_id),
 FOREIGN KEY(publication_id,stream_index) REFERENCES media_analysis_streams(publication_id,stream_index)
) STRICT;
CREATE TABLE library_sources (
 id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id),
 kind TEXT NOT NULL DEFAULT 'local', name TEXT NOT NULL DEFAULT '',
 configured_root TEXT NOT NULL, root TEXT NOT NULL,
 classification TEXT NOT NULL DEFAULT 'local' CHECK(classification IN('local','network')),
 generation INTEGER NOT NULL DEFAULT 1, incarnation TEXT NOT NULL DEFAULT(lower(hex(randomblob(16)))),
 root_identity TEXT NOT NULL DEFAULT '', identity_confirmed INTEGER NOT NULL DEFAULT 0, health TEXT NOT NULL DEFAULT 'ready',
 enabled INTEGER NOT NULL DEFAULT 1, follow_symlinks INTEGER NOT NULL DEFAULT 0,
 missing_grace_seconds INTEGER NOT NULL DEFAULT 86400 CHECK(missing_grace_seconds>=0),
 interval_seconds INTEGER NOT NULL DEFAULT 0 CHECK(interval_seconds=0 OR interval_seconds>=900),
 next_scan_at TEXT NOT NULL DEFAULT '', last_complete_job TEXT NOT NULL DEFAULT '',
 last_complete_at TEXT NOT NULL DEFAULT '', last_progress_at TEXT NOT NULL DEFAULT '',
 UNIQUE(library_id,root)
) STRICT;
CREATE TABLE library_scan_policies (
 library_id TEXT PRIMARY KEY REFERENCES libraries(id), revision INTEGER NOT NULL DEFAULT 1,
 tier TEXT NOT NULL DEFAULT 'basic' CHECK(tier IN('file_list_only','basic','complete','custom')),
 operations_json TEXT NOT NULL DEFAULT '["probe","local_metadata","subtitles"]'
, trickplay_interval_seconds INTEGER NOT NULL DEFAULT 0, trickplay_tile_width INTEGER NOT NULL DEFAULT 0, trickplay_max_tiles INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE source_strm_analysis(library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,enabled INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE inventory_policy_pending (
 library_id TEXT PRIMARY KEY REFERENCES libraries(id), revision INTEGER NOT NULL
) STRICT;
CREATE TABLE inventory_runs (
 job_id TEXT PRIMARY KEY REFERENCES jobs(id), source_id TEXT NOT NULL REFERENCES library_sources(id),
 source_generation INTEGER NOT NULL, root_incarnation TEXT NOT NULL, root_identity TEXT NOT NULL,
 policy_revision INTEGER NOT NULL, phase TEXT NOT NULL DEFAULT 'inventory',
 authoritative INTEGER NOT NULL DEFAULT 0, discovered INTEGER NOT NULL DEFAULT 0,
 analyzed INTEGER NOT NULL DEFAULT 0, warnings INTEGER NOT NULL DEFAULT 0,
 reconcile_cursor TEXT NOT NULL DEFAULT '', verify_cursor TEXT NOT NULL DEFAULT '',
 last_turn TEXT NOT NULL DEFAULT '', pause_reason TEXT NOT NULL DEFAULT '',
 inventory_completed_at TEXT NOT NULL DEFAULT '', finished_at TEXT NOT NULL DEFAULT ''
, scan_mode TEXT NOT NULL DEFAULT 'full' CHECK(scan_mode IN('first-import','incremental','integrity','full'))) STRICT;
CREATE TABLE inventory_source_active (
 source_id TEXT PRIMARY KEY REFERENCES library_sources(id), job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id)
) STRICT;
CREATE TABLE inventory_directories (
 job_id TEXT NOT NULL REFERENCES jobs(id), relative_path TEXT NOT NULL,
 identity TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL DEFAULT '', cursor TEXT NOT NULL DEFAULT '',
 state TEXT NOT NULL DEFAULT 'pending', pages INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(job_id,relative_path)
) STRICT;
CREATE TABLE inventory_objects (
 id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES library_sources(id),
 asset_id TEXT NOT NULL REFERENCES catalog_assets(token), root_incarnation TEXT NOT NULL,
 relative_path TEXT NOT NULL, object_identity TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL,
 evidence_json TEXT NOT NULL, size INTEGER NOT NULL, modified_ns INTEGER NOT NULL,
 seen_job TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'available',
 retired INTEGER NOT NULL DEFAULT 0, missing_since TEXT NOT NULL DEFAULT '', missing_observations INTEGER NOT NULL DEFAULT 0,
 last_missing_job TEXT NOT NULL DEFAULT '', trashed_at TEXT NOT NULL DEFAULT '', unsupported_reason TEXT NOT NULL DEFAULT '',
 analysis_revision TEXT NOT NULL DEFAULT '', analysis_policy INTEGER NOT NULL DEFAULT 0, analysis_operations_json TEXT NOT NULL DEFAULT '[]',
 analysis_state TEXT NOT NULL DEFAULT 'pending', analysis_error TEXT NOT NULL DEFAULT ''
, directory_path TEXT NOT NULL DEFAULT '.') STRICT;
CREATE TABLE inventory_changes (
 sequence INTEGER PRIMARY KEY AUTOINCREMENT, source_id TEXT NOT NULL, job_id TEXT NOT NULL,
 object_id TEXT NOT NULL DEFAULT '', asset_id TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL DEFAULT '',
 kind TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(job_id,object_id,revision,kind)
) STRICT;
CREATE TABLE inventory_operation_jobs (
 operation_id TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id),
 PRIMARY KEY(operation_id,job_id)
) STRICT;
CREATE TABLE inventory_analysis_queue (
 job_id TEXT NOT NULL REFERENCES jobs(id), object_id TEXT NOT NULL REFERENCES inventory_objects(id),
 revision TEXT NOT NULL, policy_revision INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'pending',
 PRIMARY KEY(job_id,object_id)
) STRICT;
CREATE TABLE inventory_version_links (
 library_id TEXT NOT NULL, asset_id TEXT NOT NULL, item_id INTEGER NOT NULL,
 PRIMARY KEY(library_id,asset_id),FOREIGN KEY(item_id) REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE dvr_catalog_retirements(item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,requested_ms INTEGER NOT NULL) STRICT;
CREATE TABLE analysis_probe_bindings (
 object_id TEXT PRIMARY KEY, source_revision TEXT NOT NULL, evidence TEXT NOT NULL
) STRICT;
CREATE TABLE analysis_results (
 id TEXT PRIMARY KEY, object_id TEXT NOT NULL, asset_id TEXT NOT NULL,
 source_revision TEXT NOT NULL, root_incarnation TEXT NOT NULL,
 configuration_generation INTEGER NOT NULL, policy_revision INTEGER NOT NULL,
 stage TEXT NOT NULL, algorithm TEXT NOT NULL, evidence TEXT NOT NULL,
 tool_digest TEXT NOT NULL, duration_us INTEGER NOT NULL, summary_json TEXT NOT NULL,
 created_ms INTEGER NOT NULL, retired_ms INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE analysis_heads (
 object_id TEXT NOT NULL, source_revision TEXT NOT NULL, stage TEXT NOT NULL,
 result_id TEXT NOT NULL REFERENCES analysis_results(id),
 PRIMARY KEY(object_id,source_revision,stage)
) STRICT;
CREATE TABLE analysis_artifacts (
 id TEXT PRIMARY KEY, result_id TEXT NOT NULL REFERENCES analysis_results(id),
 digest TEXT NOT NULL, size INTEGER NOT NULL, kind TEXT NOT NULL,
 mime TEXT NOT NULL, ordinal INTEGER NOT NULL, start_us INTEGER NOT NULL,
 end_us INTEGER NOT NULL, width INTEGER NOT NULL DEFAULT 0, height INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE analysis_marker_sets (
 object_id TEXT NOT NULL, source_revision TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
 PRIMARY KEY(object_id,source_revision)
) STRICT;
CREATE TABLE analysis_markers (
 id TEXT PRIMARY KEY, object_id TEXT NOT NULL, source_revision TEXT NOT NULL, source_binding TEXT NOT NULL,
 kind TEXT NOT NULL, start_us INTEGER NOT NULL, end_us INTEGER NOT NULL,
 confidence REAL NOT NULL, provenance TEXT NOT NULL, result_id TEXT NOT NULL,
 approved INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0,
 edited INTEGER NOT NULL DEFAULT 0, title TEXT NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE analysis_marker_history (
 object_id TEXT NOT NULL, source_revision TEXT NOT NULL, revision INTEGER NOT NULL,
 actor TEXT NOT NULL, mutation_json TEXT NOT NULL, created_ms INTEGER NOT NULL,
 PRIMARY KEY(object_id,source_revision,revision)
) STRICT;
CREATE TABLE analysis_marker_receipts (
 actor TEXT NOT NULL,request_id TEXT NOT NULL,mutation_digest TEXT NOT NULL,
 marker_revision INTEGER NOT NULL,marker_id TEXT NOT NULL,created_ms INTEGER NOT NULL,
 PRIMARY KEY(actor,request_id)
) STRICT;
CREATE TABLE analysis_stage_runs (
 job_id TEXT NOT NULL, object_id TEXT NOT NULL, source_revision TEXT NOT NULL,
 policy_revision INTEGER NOT NULL, stage TEXT NOT NULL, algorithm TEXT NOT NULL,
 state TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0,
 processed_bytes INTEGER NOT NULL DEFAULT 0, error_code TEXT NOT NULL DEFAULT '',
 next_ms INTEGER NOT NULL DEFAULT 0, updated_ms INTEGER NOT NULL,
 PRIMARY KEY(job_id,object_id,source_revision,policy_revision,stage,algorithm)
) STRICT;
CREATE TABLE console_documents(scope TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL,updated_ms INTEGER NOT NULL) STRICT;
CREATE TABLE console_receipts(scope TEXT NOT NULL,key TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,expires_ms INTEGER NOT NULL,PRIMARY KEY(scope,key)) STRICT;
CREATE TABLE console_audit(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,time_ms INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,revision INTEGER NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL) STRICT;
CREATE TABLE console_records(sequence INTEGER PRIMARY KEY AUTOINCREMENT,lane TEXT NOT NULL,time_ms INTEGER NOT NULL,severity TEXT NOT NULL,component TEXT NOT NULL,code TEXT NOT NULL,fields TEXT NOT NULL) STRICT;
CREATE TABLE console_alerts(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,severity TEXT NOT NULL,status TEXT NOT NULL,first_ms INTEGER NOT NULL,last_ms INTEGER NOT NULL,occurrences INTEGER NOT NULL,revision INTEGER NOT NULL) STRICT;
CREATE TABLE console_exports(id TEXT PRIMARY KEY,actor TEXT NOT NULL,expires_ms INTEGER NOT NULL,body TEXT NOT NULL) STRICT;
CREATE TABLE console_reports(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,scope TEXT NOT NULL,created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,category TEXT NOT NULL,message TEXT NOT NULL,item_id INTEGER NOT NULL,attachment TEXT NOT NULL,expires_ms INTEGER NOT NULL) STRICT;
CREATE TABLE console_report_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,report_id TEXT NOT NULL REFERENCES console_reports(id) ON DELETE CASCADE,time_ms INTEGER NOT NULL,revision INTEGER NOT NULL,status TEXT NOT NULL,reply TEXT NOT NULL,actor_class TEXT NOT NULL) STRICT;
CREATE TABLE console_notifications(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,scope TEXT NOT NULL,created_ms INTEGER NOT NULL,read_ms INTEGER,code TEXT NOT NULL,target_id TEXT NOT NULL,expires_ms INTEGER NOT NULL,dedupe TEXT NOT NULL,UNIQUE(scope,dedupe)) STRICT;
CREATE TABLE console_operations(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,resource TEXT NOT NULL,actor TEXT NOT NULL,trigger TEXT NOT NULL,state TEXT NOT NULL,phase TEXT NOT NULL,revision INTEGER NOT NULL,attempt INTEGER NOT NULL,created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL,next_ms INTEGER NOT NULL,domain_id TEXT NOT NULL,error_code TEXT NOT NULL,predecessor TEXT NOT NULL,settings_revision INTEGER NOT NULL,processed INTEGER) STRICT;
CREATE TABLE console_schedules(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,kind TEXT NOT NULL,resource TEXT NOT NULL,enabled INTEGER NOT NULL,timezone TEXT NOT NULL,start_minute INTEGER NOT NULL,window_minutes INTEGER NOT NULL,catch_up INTEGER NOT NULL,last_slot TEXT NOT NULL,created_ms INTEGER NOT NULL) STRICT;
CREATE TABLE console_settings_revision(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL) STRICT;
CREATE TABLE dvr_private_libraries(
 library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
 authority TEXT NOT NULL CHECK(authority IN('local','hosted')),
 account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 UNIQUE(authority,account_id,profile_id)) STRICT;
CREATE TABLE dvr_catalog_provenance(
 item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 recording_id TEXT NOT NULL UNIQUE,asset_id TEXT NOT NULL REFERENCES catalog_assets(token),
 source_id TEXT NOT NULL,channel_id TEXT NOT NULL,programme_id TEXT NOT NULL,
 guide_generation TEXT NOT NULL,artifact_digest TEXT NOT NULL,
 captured_start_ms INTEGER NOT NULL,captured_end_ms INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN('completed','incomplete-playable'))) STRICT;
CREATE TABLE continue_dismissals(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,playback_id TEXT NOT NULL,PRIMARY KEY(profile_id,item_id)) STRICT;
CREATE TABLE personal_evidence_fences(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,playback_id TEXT NOT NULL,PRIMARY KEY(profile_id,item_id)) STRICT;
CREATE TABLE personal_history(id TEXT NOT NULL,profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,started_at TEXT NOT NULL,updated_at TEXT NOT NULL,sequence INTEGER NOT NULL,position INTEGER NOT NULL,unit INTEGER NOT NULL DEFAULT 0 CHECK(unit BETWEEN 0 AND 99),completed INTEGER NOT NULL,PRIMARY KEY(profile_id,id)) STRICT;
CREATE TABLE personal_activity_revisions(profile_id TEXT PRIMARY KEY,revision INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE saved_operation_fences(owner_key TEXT NOT NULL,domain TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(owner_key,domain,operation_id)) STRICT;
CREATE TABLE personal_snapshots(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,revision INTEGER NOT NULL,state TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(profile_id,item_id,revision)) STRICT;
CREATE TABLE personal_device_sequences(profile_id TEXT NOT NULL,device_id TEXT NOT NULL,sequence INTEGER NOT NULL,PRIMARY KEY(profile_id,device_id)) STRICT;
CREATE TABLE personal_explicit_events(profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,operation_id TEXT NOT NULL,field TEXT NOT NULL,base_revision INTEGER NOT NULL,base_value TEXT NOT NULL,value TEXT NOT NULL,device_id TEXT NOT NULL,device_mutation_id TEXT NOT NULL,sequence INTEGER NOT NULL,authored_at TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(profile_id,operation_id),UNIQUE(profile_id,device_id,device_mutation_id)) STRICT;
CREATE TABLE personal_conflicts(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,field TEXT NOT NULL,base_revision INTEGER NOT NULL,base_value TEXT NOT NULL,resolved INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE personal_activity_receipts(profile_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(profile_id,operation_id)) STRICT;
CREATE TABLE saved_resources(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('collection','view')),owner_key TEXT NOT NULL,owner_authority TEXT NOT NULL,owner_account TEXT NOT NULL,owner_profile TEXT NOT NULL,name TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',definition TEXT NOT NULL DEFAULT '{}',revision INTEGER NOT NULL DEFAULT 1,deleted INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN('private','server'))) STRICT;
CREATE TABLE saved_resource_shares(resource_id TEXT NOT NULL REFERENCES saved_resources(id) ON DELETE CASCADE,authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('viewer','editor')),PRIMARY KEY(resource_id,authority,account_id,profile_id)) STRICT;
CREATE TABLE saved_resource_entries(id TEXT PRIMARY KEY,resource_id TEXT NOT NULL REFERENCES saved_resources(id) ON DELETE CASCADE,item_id INTEGER REFERENCES catalog_entities(id) ON DELETE SET NULL,UNIQUE(resource_id,item_id)) STRICT;
CREATE TABLE saved_resource_receipts(owner_key TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(owner_key,operation_id)) STRICT;
CREATE TABLE saved_pins(owner_key TEXT NOT NULL,kind TEXT NOT NULL,resource_id TEXT NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner_key,kind,resource_id)) STRICT;
CREATE TABLE saved_resource_generation(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE playback_legacy_replacement_requests(account_id TEXT NOT NULL,profile_id TEXT NOT NULL,request_id TEXT NOT NULL,old_session_id TEXT NOT NULL,old_generation INTEGER NOT NULL,PRIMARY KEY(account_id,profile_id,request_id)) STRICT;
CREATE TABLE playback_physical_source_pins(session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,source_id TEXT NOT NULL,incarnation TEXT NOT NULL,configuration_generation INTEGER NOT NULL) STRICT;
CREATE TABLE subtitle_inventory_entries(source_id TEXT NOT NULL,incarnation TEXT NOT NULL,job_id TEXT NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,directory TEXT NOT NULL,path TEXT NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(source_id,job_id,path)) STRICT;
CREATE TABLE playback_vod_retries(playback_id TEXT PRIMARY KEY REFERENCES playback_occurrences(id),request_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending') STRICT;
CREATE TABLE playback_vod_subtitle_intents(playback_id TEXT PRIMARY KEY REFERENCES playback_occurrences(id),request_id TEXT NOT NULL,ownership_revision INTEGER NOT NULL,command_sequence INTEGER NOT NULL) STRICT;
CREATE TABLE playback_vod_observations(playback_id TEXT PRIMARY KEY REFERENCES playback_occurrences(id),acknowledged_seek_id TEXT) STRICT;
CREATE TABLE playback_personal_intents(
  ordinal INTEGER PRIMARY KEY AUTOINCREMENT, request_key TEXT NOT NULL UNIQUE
 ) STRICT;
CREATE TABLE playback_personal_claims(
  playback_id TEXT PRIMARY KEY, profile_key TEXT NOT NULL, item_id INTEGER NOT NULL,
  accepted_ordinal INTEGER NOT NULL CHECK(accepted_ordinal>=0)
 ) STRICT;
CREATE TABLE playback_personal_fences(
  profile_key TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
  through_ordinal INTEGER NOT NULL CHECK(through_ordinal>=0),PRIMARY KEY(profile_key,item_id)
 ) STRICT;
CREATE TABLE playback_personal_profile_fences(
  profile_key TEXT PRIMARY KEY,through_ordinal INTEGER NOT NULL CHECK(through_ordinal>=0)
 ) STRICT;
CREATE TABLE lyric_resources (
 id TEXT PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id TEXT NOT NULL REFERENCES catalog_assets(token), source_version TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(scope IN ('library','private')),
 authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>0), deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1))
) STRICT;
CREATE TABLE lyric_revisions (
 resource_id TEXT NOT NULL REFERENCES lyric_resources(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL,
 language TEXT NOT NULL, offset_ms INTEGER NOT NULL CHECK(offset_ms BETWEEN -600000 AND 600000),
 provenance TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL,
 deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1)),
 PRIMARY KEY(resource_id,revision)
) STRICT;
CREATE TABLE lyric_selections (
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL CHECK(revision>0), resource_id TEXT, lyric_revision INTEGER,
 FOREIGN KEY(resource_id,lyric_revision) REFERENCES lyric_revisions(resource_id,revision),
 CHECK((resource_id IS NULL AND lyric_revision IS NULL) OR (resource_id IS NOT NULL AND lyric_revision IS NOT NULL))
) STRICT;
CREATE TABLE lyric_candidates (
 id TEXT PRIMARY KEY, item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id TEXT NOT NULL REFERENCES catalog_assets(token), source_version TEXT NOT NULL,
 actor TEXT NOT NULL, target_id TEXT NOT NULL, expected_revision INTEGER NOT NULL,
 document TEXT NOT NULL, provenance TEXT NOT NULL, language TEXT NOT NULL,
 expires_at TEXT NOT NULL, provider_revision INTEGER NOT NULL
) STRICT;
CREATE TABLE lyric_fetch_runs (
 id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
 actor TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('queued','running','succeeded','failed','cancelled')),
 phase TEXT NOT NULL DEFAULT '', error_code TEXT NOT NULL DEFAULT '',
 provider_revision INTEGER NOT NULL DEFAULT 0, cursor TEXT NOT NULL DEFAULT '',
 candidates INTEGER NOT NULL DEFAULT 0, processed INTEGER NOT NULL DEFAULT 0,
 published INTEGER NOT NULL DEFAULT 0, skipped INTEGER NOT NULL DEFAULT 0,
 missing INTEGER NOT NULL DEFAULT 0, cancel_requested INTEGER NOT NULL DEFAULT 0,
 created_ms INTEGER NOT NULL, updated_ms INTEGER NOT NULL
) STRICT;
CREATE TABLE screen_metadata_consent(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL DEFAULT 1,
 confirmed INTEGER NOT NULL DEFAULT 0 CHECK(confirmed IN(0,1)),confirmed_at TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE screen_metadata_policies(
 library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL DEFAULT 1,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),
 providers TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en-US',region TEXT NOT NULL DEFAULT '',
 refresh_mode TEXT NOT NULL DEFAULT 'replace_unlocked' CHECK(refresh_mode IN('replace_unlocked','fill_missing'))) STRICT;
CREATE TABLE screen_metadata_work(
 target_kind TEXT NOT NULL CHECK(target_kind IN('item','show')),target_id INTEGER NOT NULL,
 library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
 title_seed TEXT NOT NULL,year_seed INTEGER NOT NULL DEFAULT 0,
 revision INTEGER NOT NULL DEFAULT 1,selection_revision INTEGER NOT NULL DEFAULT 1,generation INTEGER NOT NULL DEFAULT 1,
 status TEXT NOT NULL DEFAULT 'pending',lease TEXT NOT NULL DEFAULT '',lease_until TEXT NOT NULL DEFAULT '',
 attempts INTEGER NOT NULL DEFAULT 0,next_attempt TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',
 provider TEXT NOT NULL DEFAULT '',provider_type TEXT NOT NULL DEFAULT '',provider_id TEXT NOT NULL DEFAULT '',
 selection_mode TEXT NOT NULL DEFAULT 'none',episode_order TEXT NOT NULL DEFAULT 'official',
 requested_provider TEXT NOT NULL DEFAULT '',query_override TEXT NOT NULL DEFAULT '',
 accepted_publication TEXT NOT NULL DEFAULT '',child_cursor TEXT NOT NULL DEFAULT '',
 parent_id INTEGER NOT NULL DEFAULT 0,parent_publication TEXT NOT NULL DEFAULT '', year_override INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(target_kind,target_id)) STRICT;
CREATE TABLE screen_metadata_candidates(
 candidate_key TEXT PRIMARY KEY,target_kind TEXT NOT NULL,target_id INTEGER NOT NULL,
 provider TEXT NOT NULL,provider_type TEXT NOT NULL,provider_id TEXT NOT NULL,
 payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=524288),
 confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1),reasons TEXT NOT NULL,
 strong_signals INTEGER NOT NULL,contradiction INTEGER NOT NULL,
 input_digest TEXT NOT NULL,query_digest TEXT NOT NULL,source_kind TEXT NOT NULL,
 observed_at TEXT NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL,
 FOREIGN KEY(target_kind,target_id) REFERENCES screen_metadata_work(target_kind,target_id) ON DELETE CASCADE) STRICT;
CREATE TABLE screen_metadata_publications(
 id TEXT PRIMARY KEY,target_kind TEXT NOT NULL,target_id INTEGER NOT NULL,
 provider TEXT NOT NULL,provider_type TEXT NOT NULL,provider_id TEXT NOT NULL,
 payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=524288),confidence REAL NOT NULL,
 reasons TEXT NOT NULL,source_kind TEXT NOT NULL,input_digest TEXT NOT NULL,query_digest TEXT NOT NULL,
 observed_at TEXT NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL,
 selection_revision INTEGER NOT NULL,generation INTEGER NOT NULL,previous_id TEXT NOT NULL DEFAULT '',
 decision TEXT NOT NULL CHECK(decision IN('accepted','superseded')),
 FOREIGN KEY(target_kind,target_id) REFERENCES screen_metadata_work(target_kind,target_id) ON DELETE CASCADE) STRICT;
CREATE TABLE screen_metadata_fields(
 target_kind TEXT NOT NULL,target_id INTEGER NOT NULL,field TEXT NOT NULL,value TEXT NOT NULL,
 provider TEXT NOT NULL,source_kind TEXT NOT NULL,source_url TEXT NOT NULL,confidence REAL NOT NULL,
 observed_at TEXT NOT NULL,language TEXT NOT NULL,region TEXT NOT NULL,selection_revision INTEGER NOT NULL,
 publication_id TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(target_kind,target_id,field),
 FOREIGN KEY(target_kind,target_id) REFERENCES screen_metadata_work(target_kind,target_id) ON DELETE CASCADE) STRICT;
CREATE TABLE video_nfo_evidence(
 library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,asset_id TEXT NOT NULL REFERENCES catalog_assets(token) ON DELETE CASCADE,
 locator TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('movie','show','episode')),coordinate TEXT NOT NULL,
 digest TEXT NOT NULL,payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB))<=524288),
 source_size INTEGER NOT NULL,source_modified INTEGER NOT NULL,observed_at TEXT NOT NULL,
 PRIMARY KEY(library_id,asset_id,locator,kind,coordinate)) STRICT;
CREATE TABLE video_nfo_status(
 library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,asset_id TEXT NOT NULL REFERENCES catalog_assets(token) ON DELETE CASCADE,
 status TEXT NOT NULL,issue TEXT NOT NULL,PRIMARY KEY(library_id,asset_id)) STRICT;
CREATE TABLE screen_anime_seasons(
 show_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,season_number INTEGER NOT NULL CHECK(season_number BETWEEN 0 AND 99),
 anilist_id TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,source_publication TEXT NOT NULL,
 PRIMARY KEY(show_id,season_number)) STRICT;
CREATE TABLE metadata_repair_work_receipts(
 operation_id TEXT NOT NULL,item_id INTEGER NOT NULL,receipt TEXT NOT NULL,next_check TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(operation_id,item_id),FOREIGN KEY(operation_id,item_id) REFERENCES metadata_repair_cascade_items(operation_id,item_id) ON DELETE CASCADE) STRICT;
CREATE TABLE metadata_discovery_items(
 provider TEXT NOT NULL,media_kind TEXT NOT NULL CHECK(media_kind IN('movie','tv','anime')),
 provider_id TEXT NOT NULL,rank INTEGER NOT NULL CHECK(rank>=1),
 fetched_at TEXT NOT NULL,expires_at TEXT NOT NULL,
 PRIMARY KEY(provider,media_kind,provider_id)) STRICT;
CREATE TABLE metadata_discovery_refresh(
 provider TEXT NOT NULL,media_kind TEXT NOT NULL CHECK(media_kind IN('movie','tv','anime')),
 revision INTEGER NOT NULL DEFAULT 1,next_attempt TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',fetched_at TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(provider,media_kind)) STRICT;
CREATE TABLE metadata_tags(
 entity_kind TEXT NOT NULL CHECK(entity_kind IN('item','show')),entity_id INTEGER NOT NULL,
 provider TEXT NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,
 PRIMARY KEY(entity_kind,entity_id,provider,id)) STRICT;
CREATE TABLE audio_genre_projection(
 library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
 policy_revision INTEGER NOT NULL DEFAULT 0,cursor TEXT NOT NULL DEFAULT '',
 completed_at TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE metadata_document_freshness(
 provider TEXT NOT NULL, kind TEXT NOT NULL, resource TEXT NOT NULL,
 fetched_at INTEGER NOT NULL DEFAULT 0,
 checked_at INTEGER NOT NULL DEFAULT 0,
 etag TEXT NOT NULL DEFAULT '',
 last_modified TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(provider,kind,resource)
) STRICT;
CREATE TABLE metadata_refresh_budget(
 provider TEXT NOT NULL, span TEXT NOT NULL,
 window_start INTEGER NOT NULL, spent INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(provider,span)
) STRICT;
CREATE TABLE prepared_media_source_revisions(asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0)) STRICT;
CREATE TABLE prepared_media_jobs(
 id TEXT PRIMARY KEY, item_id INTEGER NOT NULL, asset_id TEXT NOT NULL, library_id TEXT NOT NULL,
 profile_id TEXT NOT NULL, target_id TEXT NOT NULL, selection_json TEXT NOT NULL, source_revision TEXT NOT NULL,
 principal_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('queued','running','cancelling','cancelled','failed','succeeded')),
 phase TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 0, cleaned_generation INTEGER NOT NULL DEFAULT 0, bytes INTEGER NOT NULL DEFAULT 0,
 error_code TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1,
 created_ms INTEGER NOT NULL, updated_ms INTEGER NOT NULL, version_id TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE prepared_media_versions(
 id TEXT PRIMARY KEY, item_id INTEGER NOT NULL, asset_id TEXT NOT NULL, library_id TEXT NOT NULL,
 profile_id TEXT NOT NULL, target_id TEXT NOT NULL, source_revision TEXT NOT NULL, selection_json TEXT NOT NULL,
 part_index INTEGER NOT NULL, edition_id TEXT, input_evidence TEXT NOT NULL, transformation_digest TEXT NOT NULL,
 digest TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0), facts_json TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN('published','deleting','deleted')), revision INTEGER NOT NULL DEFAULT 1,
 created_ms INTEGER NOT NULL, job_id TEXT NOT NULL REFERENCES prepared_media_jobs(id)) STRICT;
CREATE TABLE prepared_media_session_pins(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 version_id TEXT NOT NULL REFERENCES prepared_media_versions(id), digest TEXT NOT NULL, size INTEGER NOT NULL) STRICT;
CREATE TABLE hosted_profile_revisions(
 server_id TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 pin_revision INTEGER NOT NULL,profile_revision INTEGER NOT NULL,trust_revision INTEGER NOT NULL,account_epoch INTEGER NOT NULL,
 PRIMARY KEY(server_id,account_id,profile_id)) STRICT;
CREATE TABLE hosted_profile_erasure_receipts(
 job_id TEXT PRIMARY KEY,server_id TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 revision INTEGER NOT NULL,applied_at TEXT NOT NULL) STRICT;
CREATE TABLE direct_profiles(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 name TEXT NOT NULL, is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN(0,1)),
 position INTEGER NOT NULL DEFAULT 0, art TEXT NOT NULL DEFAULT 'blue',
 revision INTEGER NOT NULL DEFAULT 1, pin_revision INTEGER NOT NULL DEFAULT 1,
 pin_hash BLOB, pin_attempts INTEGER NOT NULL DEFAULT 0, pin_locked_until INTEGER NOT NULL DEFAULT 0,
 allowed_libraries TEXT CHECK(allowed_libraries IS NULL OR json_valid(allowed_libraries)),
 deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1)), UNIQUE(account_id,id)
) STRICT;
CREATE TABLE direct_profile_trust(
 token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 installation_id TEXT NOT NULL, pin_revision INTEGER NOT NULL, membership_revision INTEGER NOT NULL,
 profile_revision INTEGER NOT NULL, expires_at TEXT NOT NULL,
 FOREIGN KEY(account_id,profile_id) REFERENCES direct_profiles(account_id,id) ON DELETE CASCADE
) STRICT;
CREATE TABLE profile_restrictions(
 profile_id TEXT PRIMARY KEY REFERENCES direct_profiles(id) ON DELETE CASCADE,
 rating_system TEXT NOT NULL DEFAULT '' ,
 maximum_age_rating TEXT NOT NULL DEFAULT '',
 maximum_age INTEGER NOT NULL DEFAULT -1 CHECK(maximum_age>=-1),
 allow_unrated INTEGER NOT NULL DEFAULT 1 CHECK(allow_unrated IN(0,1)),
 blocked_labels TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(blocked_labels)),
 allow_downloads INTEGER NOT NULL DEFAULT 1 CHECK(allow_downloads IN(0,1)),
 allow_live_tv INTEGER NOT NULL DEFAULT 1 CHECK(allow_live_tv IN(0,1)),
 allow_dvr INTEGER NOT NULL DEFAULT 1 CHECK(allow_dvr IN(0,1)),
 allow_watch_together INTEGER NOT NULL DEFAULT 1 CHECK(allow_watch_together IN(0,1)),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)
) STRICT;
CREATE TABLE profile_avatar_objects(
 digest TEXT NOT NULL, rendition INTEGER NOT NULL CHECK(rendition>0),
 bytes INTEGER NOT NULL CHECK(bytes>0), image BLOB NOT NULL,
 PRIMARY KEY(digest,rendition)
) STRICT;
CREATE TABLE profile_avatars(
 profile_id TEXT PRIMARY KEY REFERENCES direct_profiles(id) ON DELETE CASCADE,
 digest TEXT NOT NULL, source_mime TEXT NOT NULL,
 version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), updated_at TEXT NOT NULL
) STRICT;
CREATE TABLE identity_devices(
 id TEXT PRIMARY KEY,
 authority TEXT NOT NULL DEFAULT 'local' CHECK(authority IN('local','hosted')),
 account_id TEXT NOT NULL,
 installation_id TEXT NOT NULL, name TEXT NOT NULL, platform TEXT NOT NULL,
 app TEXT NOT NULL, app_version TEXT NOT NULL, ip TEXT NOT NULL DEFAULT '',
 first_seen TEXT NOT NULL, last_seen TEXT NOT NULL,
 trusted INTEGER NOT NULL DEFAULT 0 CHECK(trusted IN(0,1)),
 approval_state TEXT NOT NULL DEFAULT 'approved' CHECK(approval_state IN('approved','pending','denied')),
 last_profile_id TEXT NOT NULL DEFAULT '',
 remember_account INTEGER NOT NULL DEFAULT 1 CHECK(remember_account IN(0,1)),
 UNIQUE(authority,account_id,installation_id)
) STRICT;
CREATE TABLE identity_device_families(
 family_id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES identity_devices(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE identity_browser_accounts(
 installation_id TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 username TEXT NOT NULL, display_name TEXT NOT NULL,
 avatar_version INTEGER NOT NULL DEFAULT 0 CHECK(avatar_version>=0),
 automatic_sign_in INTEGER NOT NULL DEFAULT 0 CHECK(automatic_sign_in IN(0,1)),
 last_used TEXT NOT NULL, PRIMARY KEY(installation_id,account_id)
) STRICT;
CREATE TABLE identity_account_factors(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 secret TEXT NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0 CHECK(confirmed IN(0,1)),
 last_step INTEGER NOT NULL DEFAULT 0, enrolled_at TEXT NOT NULL
) STRICT;
CREATE TABLE identity_recovery_codes(
 account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 code_hash TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0 CHECK(used IN(0,1)),
 PRIMARY KEY(account_id,code_hash)
) STRICT;
CREATE TABLE identity_factor_challenges(
 token_hash TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 expires_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0)
) STRICT;
CREATE TABLE topshelf_tokens(
 token_hash TEXT PRIMARY KEY, device_id TEXT NOT NULL,
 authority TEXT NOT NULL DEFAULT 'local' CHECK(authority IN('local','hosted')),
 account_id TEXT NOT NULL, profile_id TEXT NOT NULL, expires_at TEXT NOT NULL
) STRICT;
CREATE TABLE content_rating_ages(
 value_key TEXT PRIMARY KEY, minimum_age INTEGER NOT NULL CHECK(minimum_age>=-1)
) STRICT;
CREATE TABLE listening_book_groups(
  id TEXT PRIMARY KEY, library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK(kind IN('author','book_series')), name TEXT NOT NULL, name_key TEXT NOT NULL,
  UNIQUE(library_id,kind,name_key)) STRICT;
CREATE TABLE search_history(
  profile_key TEXT NOT NULL, normalized TEXT NOT NULL, query TEXT NOT NULL,
  updated_at TEXT NOT NULL, PRIMARY KEY(profile_key,normalized)) STRICT;
CREATE TABLE library_navigation(owner_key TEXT NOT NULL,library_id TEXT NOT NULL REFERENCES libraries(id) ON DELETE CASCADE,position INTEGER NOT NULL,PRIMARY KEY(owner_key,library_id)) STRICT;
CREATE TABLE library_navigation_revisions(owner_key TEXT PRIMARY KEY,revision INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE saved_pin_order(owner_key TEXT NOT NULL,kind TEXT NOT NULL,resource_id TEXT NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(owner_key,kind,resource_id)) STRICT;
CREATE TABLE saved_pin_order_revisions(owner_key TEXT PRIMARY KEY,revision INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE item_extras(
  item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
  library_id TEXT NOT NULL REFERENCES libraries(id),
  parent_path TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN('trailer','featurette','deleted_scene','behind_the_scenes','interview','scene','short','other')),
  title TEXT NOT NULL,
  asset_id TEXT NOT NULL REFERENCES catalog_assets(token),
  relative_path TEXT NOT NULL) STRICT;
CREATE TABLE personal_batch_receipts(profile_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(profile_id,operation_id)) STRICT;
CREATE TABLE telemetry_rollups(
 minute_ms INTEGER PRIMARY KEY CHECK(minute_ms>0),
 body TEXT NOT NULL
) STRICT;
CREATE TABLE social_groups(
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  host_member_id TEXT NOT NULL,
  host_authority TEXT NOT NULL CHECK(host_authority IN ('host-only','anyone')),
  state TEXT NOT NULL CHECK(state IN ('creating','lobby','preparing','ready','playing','paused','host-reconnecting-playing','host-reconnecting-paused','degraded','ending','ended','failed')),
  revision INTEGER NOT NULL DEFAULT 1,
  playback_revision INTEGER NOT NULL DEFAULT 1,
  queue_revision INTEGER NOT NULL DEFAULT 1,
  reconnect_generation INTEGER NOT NULL DEFAULT 1,
  event_ordinal INTEGER NOT NULL DEFAULT 0,
  item_id INTEGER NOT NULL DEFAULT 0,
  current_entry_id TEXT NOT NULL DEFAULT '',
  position_us INTEGER NOT NULL DEFAULT 0,
  position_updated_ms INTEGER NOT NULL DEFAULT 0,
  rate_numerator INTEGER NOT NULL DEFAULT 1,
  rate_denominator INTEGER NOT NULL DEFAULT 1,
  queue_position INTEGER NOT NULL DEFAULT 0,
  shuffle INTEGER NOT NULL DEFAULT 0,
  repeat_mode TEXT NOT NULL DEFAULT 'none' CHECK(repeat_mode IN ('none','one','all')),
  last_command TEXT NOT NULL DEFAULT '',
  last_command_id TEXT NOT NULL DEFAULT '',
  resume_state TEXT NOT NULL DEFAULT 'paused' CHECK(resume_state IN ('playing','paused')),
  host_seen_ms INTEGER NOT NULL DEFAULT 0,
  pause_after_seconds INTEGER NOT NULL DEFAULT 120,
  end_after_seconds INTEGER NOT NULL DEFAULT 600,
  ended_reason TEXT NOT NULL DEFAULT '',
  created_at_ms INTEGER NOT NULL,
  updated_at_ms INTEGER NOT NULL,
  ended_at_ms INTEGER, host_device_id TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE social_group_members(
  id TEXT PRIMARY KEY,
  group_id TEXT NOT NULL REFERENCES social_groups(id) ON DELETE CASCADE,
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('host','member')),
  state TEXT NOT NULL CHECK(state IN ('invited','joined','left','removed')),
  readiness TEXT NOT NULL DEFAULT 'buffering' CHECK(readiness IN ('buffering','ready','lagging')),
  readiness_position_us INTEGER NOT NULL DEFAULT 0,
  readiness_at_ms INTEGER NOT NULL DEFAULT 0,
  joined_at_ms INTEGER NOT NULL,
  left_at_ms INTEGER,
  UNIQUE(group_id,authority,account_id,profile_id)) STRICT;
CREATE TABLE social_group_invites(
  id TEXT PRIMARY KEY,
  group_id TEXT NOT NULL REFERENCES social_groups(id) ON DELETE CASCADE,
  code_digest TEXT NOT NULL UNIQUE,
  created_by TEXT NOT NULL,
  recipient_profile_id TEXT NOT NULL DEFAULT '',
  max_uses INTEGER NOT NULL,
  uses INTEGER NOT NULL DEFAULT 0,
  revoked INTEGER NOT NULL DEFAULT 0,
  expires_at_ms INTEGER NOT NULL,
  created_at_ms INTEGER NOT NULL) STRICT;
CREATE TABLE social_group_queue(
  group_id TEXT NOT NULL REFERENCES social_groups(id) ON DELETE CASCADE,
  entry_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  item_id INTEGER NOT NULL,
  added_by TEXT NOT NULL DEFAULT '',
  added_at_ms INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY(group_id,entry_id)) STRICT;
CREATE TABLE social_group_receipts(
  group_id TEXT NOT NULL REFERENCES social_groups(id) ON DELETE CASCADE,
  member_id TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  digest TEXT NOT NULL,
  response TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY(group_id,member_id,idempotency_key)) STRICT;
CREATE TABLE social_group_events(
  group_id TEXT NOT NULL REFERENCES social_groups(id) ON DELETE CASCADE,
  ordinal INTEGER NOT NULL,
  kind TEXT NOT NULL,
  payload TEXT NOT NULL,
  created_at_ms INTEGER NOT NULL,
  PRIMARY KEY(group_id,ordinal)) STRICT;
CREATE TABLE social_receivers(
  id TEXT PRIMARY KEY,
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('portico','cast')),
  device_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  platform TEXT NOT NULL DEFAULT '',
  key_fingerprint TEXT NOT NULL,
  public_key TEXT NOT NULL DEFAULT '',
  supported_commands TEXT NOT NULL DEFAULT '["load"]',
  grant_policy TEXT NOT NULL DEFAULT 'per-device' CHECK(grant_policy IN ('per-device','always-ask','open')),
  authorization_revision INTEGER NOT NULL DEFAULT 1,
  state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','retired')),
  created_at_ms INTEGER NOT NULL,
  last_seen_ms INTEGER NOT NULL,
  UNIQUE(authority,account_id,profile_id,device_id)) STRICT;
CREATE TABLE social_receiver_grants(
  id TEXT PRIMARY KEY,
  receiver_id TEXT NOT NULL REFERENCES social_receivers(id) ON DELETE CASCADE,
  controller_device_id TEXT NOT NULL,
  controller_display_name TEXT NOT NULL DEFAULT '',
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  key_fingerprint TEXT NOT NULL,
  allowed_commands TEXT NOT NULL,
  authorization_revision INTEGER NOT NULL,
  state TEXT NOT NULL CHECK(state IN ('pending','accepted','declined','revoked','expired')),
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  decided_at_ms INTEGER,
  UNIQUE(receiver_id,controller_device_id)) STRICT;
CREATE TABLE social_handoffs(
  id TEXT PRIMARY KEY,
  receiver_id TEXT NOT NULL REFERENCES social_receivers(id) ON DELETE CASCADE,
  grant_id TEXT NOT NULL,
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  request_id TEXT NOT NULL,
  request_digest TEXT NOT NULL,
  source_playback_id TEXT NOT NULL,
  item_id INTEGER NOT NULL,
  requested_position_us INTEGER NOT NULL DEFAULT 0,
  receiver_playback_id TEXT NOT NULL DEFAULT '',
  ready_position_us INTEGER NOT NULL DEFAULT 0,
  committed_position_us INTEGER NOT NULL DEFAULT 0,
  state TEXT NOT NULL CHECK(state IN ('prepared','committing','committed','rolled_back','expired','failed')),
  outcome TEXT NOT NULL CHECK(outcome IN ('waiting','pending','accepted','rejected')),
  reason TEXT NOT NULL DEFAULT '',
  revision INTEGER NOT NULL DEFAULT 1,
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  settled_at_ms INTEGER,
  UNIQUE(authority,account_id,profile_id,request_id)) STRICT;
CREATE TABLE social_cast_bootstraps(
  id TEXT PRIMARY KEY,
  code_digest TEXT NOT NULL UNIQUE,
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  role TEXT NOT NULL,
  account_epoch INTEGER NOT NULL,
  display_name TEXT NOT NULL,
  capabilities TEXT NOT NULL,
  state TEXT NOT NULL CHECK(state IN ('pending','redeemed','expired','cancelled')),
  attempts INTEGER NOT NULL DEFAULT 0,
  device_id TEXT NOT NULL DEFAULT '',
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  redeemed_at_ms INTEGER) STRICT;
CREATE TABLE social_cast_devices(
  id TEXT PRIMARY KEY,
  token_digest TEXT NOT NULL UNIQUE,
  bootstrap_id TEXT NOT NULL DEFAULT '',
  receiver_id TEXT NOT NULL DEFAULT '',
  authority TEXT NOT NULL,
  account_id TEXT NOT NULL,
  profile_id TEXT NOT NULL,
  role TEXT NOT NULL,
  account_epoch INTEGER NOT NULL,
  device_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  capabilities TEXT NOT NULL,
  generation INTEGER NOT NULL DEFAULT 1,
  state TEXT NOT NULL CHECK(state IN ('pending','active','stopped','expired','revoked')),
  created_at_ms INTEGER NOT NULL,
  expires_at_ms INTEGER NOT NULL,
  last_seen_ms INTEGER NOT NULL,
  UNIQUE(authority,account_id,profile_id,device_id)) STRICT;
CREATE TABLE social_rate(bucket TEXT PRIMARY KEY,window_start_ms INTEGER NOT NULL,count INTEGER NOT NULL) STRICT;
CREATE TABLE artwork_uploads(
 candidate_id TEXT PRIMARY KEY REFERENCES artwork_candidates(id) ON DELETE CASCADE,
 kind TEXT NOT NULL,entity_id INTEGER NOT NULL,role TEXT NOT NULL,subject TEXT NOT NULL DEFAULT '',
 digest TEXT NOT NULL,thumbnail_digest TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL,
 width INTEGER NOT NULL,height INTEGER NOT NULL,actor TEXT NOT NULL,observed_at TEXT NOT NULL) STRICT;
CREATE TABLE notification_revision(singleton INTEGER PRIMARY KEY CHECK(singleton=1),value INTEGER NOT NULL) STRICT;
CREATE TABLE notification_inbox(
 scope TEXT NOT NULL,
 audience TEXT NOT NULL CHECK(audience IN('profile','account-admin')),
 revision INTEGER NOT NULL,
 updated_ms INTEGER NOT NULL,
 PRIMARY KEY(scope,audience)) STRICT;
CREATE TABLE notification_records(
 sequence INTEGER PRIMARY KEY AUTOINCREMENT,
 id TEXT NOT NULL UNIQUE,
 scope TEXT NOT NULL,
 audience TEXT NOT NULL CHECK(audience IN('profile','account-admin')),
 severity TEXT NOT NULL CHECK(severity IN('info','warning','critical')),
 source TEXT NOT NULL,
 category TEXT NOT NULL,
 title TEXT NOT NULL,
 body TEXT NOT NULL,
 arguments TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(arguments)),
 actions TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(actions)),
 dedupe_key TEXT NOT NULL,
 revision INTEGER NOT NULL,
 created_ms INTEGER NOT NULL,
 updated_ms INTEGER NOT NULL,
 read_ms INTEGER,
 archived_ms INTEGER,
 expires_ms INTEGER NOT NULL,
 UNIQUE(scope,audience,source,dedupe_key),
 FOREIGN KEY(scope,audience) REFERENCES notification_inbox(scope,audience) ON DELETE CASCADE) STRICT;
CREATE TABLE feedback_details(
 report_id TEXT PRIMARY KEY REFERENCES console_reports(id) ON DELETE CASCADE,
 kind TEXT NOT NULL,
 reporter_name TEXT NOT NULL,
 reporter_authority TEXT NOT NULL,
 reporter_role TEXT NOT NULL,
 fingerprint TEXT NOT NULL,
 session_id TEXT NOT NULL,
 diagnostics_decision TEXT NOT NULL CHECK(diagnostics_decision IN('attached','unavailable','declined','not-requested')),
 diagnostics_ref TEXT NOT NULL,
 duplicate_of TEXT NOT NULL,
 duplicates INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE download_settings(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 max_prepared_bytes INTEGER NOT NULL DEFAULT 0 CHECK(max_prepared_bytes>=0),
 retention_days INTEGER NOT NULL DEFAULT 30 CHECK(retention_days>=1 AND retention_days<=365),
 revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE download_receipt_keys(
 id TEXT PRIMARY KEY, algorithm TEXT NOT NULL CHECK(algorithm='ed25519'),
 private_key BLOB NOT NULL, public_key BLOB NOT NULL,
 created_ms INTEGER NOT NULL, retired_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE download_preparations(
 id TEXT PRIMARY KEY,
 profile_key TEXT NOT NULL, authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 item_id INTEGER NOT NULL, library_id TEXT NOT NULL,
 quality TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN('item','items','container','next')),
 batch_id TEXT NOT NULL DEFAULT '',
 state TEXT NOT NULL CHECK(state IN('queued','running','ready','paused','failed','unavailable','cancelled','expired')),
 reason TEXT NOT NULL DEFAULT '',
 artifact_kind TEXT NOT NULL DEFAULT '' CHECK(artifact_kind IN('','source','prepared')),
 artifact_ref TEXT NOT NULL DEFAULT '', artifact_digest TEXT NOT NULL DEFAULT '',
 artifact_container TEXT NOT NULL DEFAULT '',
 source_version_json TEXT NOT NULL DEFAULT '',
 hash_state BLOB,
 bytes_done INTEGER NOT NULL DEFAULT 0 CHECK(bytes_done>=0),
 bytes_total INTEGER NOT NULL DEFAULT 0 CHECK(bytes_total>=0),
 estimated INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1,
 created_ms INTEGER NOT NULL, updated_ms INTEGER NOT NULL,
 started_ms INTEGER NOT NULL DEFAULT 0, ready_ms INTEGER NOT NULL DEFAULT 0, used_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE download_grants(
 hash TEXT PRIMARY KEY,
 preparation_id TEXT NOT NULL REFERENCES download_preparations(id) ON DELETE CASCADE,
 profile_key TEXT NOT NULL, item_id INTEGER NOT NULL,
 issued_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL,
 first_use_ms INTEGER NOT NULL DEFAULT 0, uses INTEGER NOT NULL DEFAULT 0,
 revoked INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE download_receipts(
 id TEXT PRIMARY KEY,
 profile_key TEXT NOT NULL, authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 item_id INTEGER NOT NULL, preparation_id TEXT NOT NULL, quality TEXT NOT NULL,
 artifact_digest TEXT NOT NULL, artifact_bytes INTEGER NOT NULL CHECK(artifact_bytes>0),
 key_id TEXT NOT NULL REFERENCES download_receipt_keys(id),
 issued_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL,
 revoked_ms INTEGER NOT NULL DEFAULT 0, revoked_reason TEXT NOT NULL DEFAULT '',
 revision INTEGER NOT NULL DEFAULT 1, sequence INTEGER NOT NULL) STRICT;
CREATE TABLE download_receipt_sequence(singleton INTEGER PRIMARY KEY CHECK(singleton=1),value INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE download_progress_marks(
 profile_key TEXT NOT NULL, item_id INTEGER NOT NULL, observed_ms INTEGER NOT NULL,
 PRIMARY KEY(profile_key,item_id)) STRICT;
CREATE TABLE admin_documents(scope TEXT PRIMARY KEY,revision INTEGER NOT NULL CHECK(revision>0),body TEXT NOT NULL,updated_ms INTEGER NOT NULL) STRICT;
CREATE TABLE admin_receipts(scope TEXT NOT NULL,operation_id TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL,created_ms INTEGER NOT NULL,PRIMARY KEY(scope,operation_id)) STRICT;
CREATE TABLE admin_trash(
 id TEXT PRIMARY KEY,library_id TEXT NOT NULL,item_id INTEGER NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,
 files_json TEXT NOT NULL,file_count INTEGER NOT NULL,bytes INTEGER NOT NULL,
 trashed_ms INTEGER NOT NULL,expires_ms INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN('held','restored','purged')),actor TEXT NOT NULL,operation_id TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE admin_dvr_groups(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('series','keyword')),name TEXT NOT NULL,
 match_text TEXT NOT NULL,source_id TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1,
 revision INTEGER NOT NULL DEFAULT 1,options_json TEXT NOT NULL DEFAULT '{}',
 created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL) STRICT;
CREATE TABLE admin_channel_presets(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,name_key TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL DEFAULT 1,
 body TEXT NOT NULL,created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL) STRICT;
CREATE TABLE admin_channel_logos(
 channel_id TEXT PRIMARY KEY,digest TEXT NOT NULL,media_type TEXT NOT NULL,bytes INTEGER NOT NULL,
 width INTEGER NOT NULL,height INTEGER NOT NULL,revision INTEGER NOT NULL,updated_ms INTEGER NOT NULL) STRICT;
CREATE TABLE admin_channel_numbers(
 source_id TEXT NOT NULL,channel_id TEXT NOT NULL,number TEXT NOT NULL DEFAULT '',
 guide_channel_id TEXT NOT NULL DEFAULT '',hidden INTEGER NOT NULL DEFAULT 0,updated_ms INTEGER NOT NULL,
 PRIMARY KEY(source_id,channel_id)) STRICT;
CREATE TABLE maintenance_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(revision>0),background_priority TEXT NOT NULL DEFAULT 'lower' CHECK(background_priority IN('lower','normal'))) STRICT;
CREATE TABLE maintenance_windows(id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),cadence TEXT NOT NULL,start_minute INTEGER NOT NULL CHECK(start_minute BETWEEN 0 AND 1439),duration_minutes INTEGER NOT NULL CHECK(duration_minutes BETWEEN 15 AND 1440),timezone TEXT NOT NULL) STRICT;
CREATE TABLE maintenance_window_days(window_id TEXT NOT NULL REFERENCES maintenance_windows(id) ON DELETE CASCADE,day TEXT NOT NULL,PRIMARY KEY(window_id,day)) STRICT;
CREATE TABLE dvr_recording_grants(
 authority TEXT NOT NULL CHECK(authority IN('local','hosted')),account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),inherit_profiles INTEGER NOT NULL CHECK(inherit_profiles IN(0,1)),revision INTEGER NOT NULL,
 PRIMARY KEY(authority,account_id,profile_id)) STRICT;
CREATE TABLE dvr_defaults(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL,before_seconds INTEGER NOT NULL,after_seconds INTEGER NOT NULL,retention_days INTEGER NOT NULL,episode_limit INTEGER NOT NULL) STRICT;
CREATE TABLE direct_memberships(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 role TEXT NOT NULL CHECK(role IN('owner','admin','member')),
 allowed_libraries TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(allowed_libraries)),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), disabled INTEGER NOT NULL DEFAULT 0 CHECK(disabled IN(0,1))
) STRICT;
CREATE TABLE access_invitations(
 id TEXT PRIMARY KEY, email TEXT NOT NULL, code_hash TEXT NOT NULL UNIQUE,
 role TEXT NOT NULL CHECK(role IN('admin','member')),
 allowed_libraries TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(allowed_libraries)),
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','accepted','revoked')),
 created_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL, accepted_ms INTEGER,
 created_by TEXT NOT NULL, account_id TEXT, revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE access_limits(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), updated_ms INTEGER NOT NULL,
 body TEXT NOT NULL CHECK(json_valid(body))) STRICT;
CREATE TABLE access_devices(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, profile_id TEXT NOT NULL DEFAULT '',
 name TEXT NOT NULL DEFAULT '', platform TEXT NOT NULL DEFAULT '',
 trust TEXT NOT NULL DEFAULT 'pending' CHECK(trust IN('pending','approved','blocked')),
 first_seen_ms INTEGER NOT NULL, last_seen_ms INTEGER NOT NULL,
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE access_api_keys(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 profile_id TEXT NOT NULL, name TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(scope IN('read-only','playback','library-management','full')),
 secret_hash TEXT NOT NULL UNIQUE, hint TEXT NOT NULL,
 created_ms INTEGER NOT NULL, last_used_ms INTEGER, created_by TEXT NOT NULL,
 revoked INTEGER NOT NULL DEFAULT 0 CHECK(revoked IN(0,1)),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TABLE access_receipts(
 scope TEXT NOT NULL, operation_id TEXT NOT NULL, digest TEXT NOT NULL,
 body TEXT NOT NULL, created_ms INTEGER NOT NULL, PRIMARY KEY(scope,operation_id)) STRICT;
CREATE TABLE client_log_uploads(
 id TEXT PRIMARY KEY, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 device_id TEXT NOT NULL, platform TEXT NOT NULL, app_version TEXT NOT NULL DEFAULT '',
 received_ms INTEGER NOT NULL, bytes INTEGER NOT NULL, body TEXT NOT NULL) STRICT;
CREATE TABLE diagnostics_debug_window(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), expires_ms INTEGER NOT NULL, opened_by TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE content_rating_pending(value_key TEXT PRIMARY KEY,value TEXT NOT NULL) WITHOUT ROWID, STRICT;
CREATE TABLE inventory_directory_cache(
 source_id TEXT NOT NULL REFERENCES library_sources(id) ON DELETE CASCADE,
 incarnation TEXT NOT NULL,relative_path TEXT NOT NULL,parent_path TEXT NOT NULL,
 parent_revision TEXT NOT NULL DEFAULT '',identity TEXT NOT NULL DEFAULT '',revision TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(source_id,incarnation,relative_path)) STRICT;
CREATE TABLE playback_client_profiles(
 session_hash TEXT PRIMARY KEY REFERENCES authorization_family_tokens(token_hash) ON DELETE CASCADE,
 account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 revision TEXT NOT NULL,family TEXT NOT NULL,
 document TEXT NOT NULL CHECK(length(document)<=65536),
 updated_at_ms INTEGER NOT NULL
 ) STRICT;
CREATE TABLE playback_route_failures(
 session_hash TEXT NOT NULL REFERENCES authorization_family_tokens(token_hash) ON DELETE CASCADE,
 asset_id TEXT NOT NULL,
 route TEXT NOT NULL CHECK(route IN ('original','copy_remux','audio_conversion')),
 code TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',
 reported_at_ms INTEGER NOT NULL,
 PRIMARY KEY(session_hash,asset_id,route)
 ) STRICT;
CREATE TABLE identity_refresh_credentials(
 family_id TEXT PRIMARY KEY REFERENCES authorization_session_families(id) ON DELETE CASCADE,
 device_id TEXT NOT NULL REFERENCES identity_devices(id),
 token_hash TEXT NOT NULL UNIQUE,
 generation INTEGER NOT NULL CHECK(generation>0),
 expires_at TEXT NOT NULL
) STRICT;
CREATE TABLE identity_refresh_receipts(
 predecessor_hash TEXT PRIMARY KEY,
 family_id TEXT NOT NULL REFERENCES authorization_session_families(id) ON DELETE CASCADE,
 request_id TEXT NOT NULL,
 ciphertext BLOB NOT NULL,
 expires_at TEXT NOT NULL
) STRICT;
CREATE TABLE hosted_trust_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL) STRICT;
CREATE TABLE hosted_signing_revocations(key_id TEXT PRIMARY KEY) STRICT;
CREATE TABLE hosted_policy_signers(server_id TEXT PRIMARY KEY,key_id TEXT NOT NULL) STRICT;
CREATE TABLE networking_web_claims(operation_id TEXT PRIMARY KEY,request TEXT NOT NULL) STRICT;
CREATE TABLE hosted_server_events(operation_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,revision INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(operation_id,kind)) STRICT;
CREATE TABLE managed_mounts(
 id TEXT PRIMARY KEY,name TEXT NOT NULL,executable TEXT NOT NULL,digest TEXT NOT NULL,
 remote TEXT NOT NULL,mount_path TEXT NOT NULL UNIQUE,desired TEXT NOT NULL DEFAULT 'stopped',
 observed TEXT NOT NULL DEFAULT 'stopped',error TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE mount_allocations(
 id TEXT PRIMARY KEY,directory_identity TEXT NOT NULL DEFAULT '',config_hash TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'reserved',created_at INTEGER NOT NULL) STRICT;
CREATE TABLE mount_backend_configs(
 mount_id TEXT PRIMARY KEY REFERENCES managed_mounts(id) ON DELETE CASCADE,
 generation INTEGER NOT NULL DEFAULT 1,config_file TEXT NOT NULL,
 version TEXT NOT NULL DEFAULT '',cache_bytes INTEGER NOT NULL DEFAULT 0,
 cache_floor INTEGER NOT NULL DEFAULT 2147483648) STRICT;
CREATE TABLE mount_controls(
 mount_id TEXT PRIMARY KEY REFERENCES managed_mounts(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL DEFAULT 1,restart_generation INTEGER NOT NULL DEFAULT 0,
 removal_pending INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE mount_operations(
 operation_id TEXT PRIMARY KEY,actor TEXT NOT NULL,fingerprint TEXT NOT NULL,
 mount_id TEXT NOT NULL,response TEXT NOT NULL,created_at INTEGER NOT NULL) STRICT;
CREATE TABLE mount_revision(id INTEGER PRIMARY KEY,revision INTEGER NOT NULL) STRICT;
CREATE TABLE live_source_identities(id TEXT PRIMARY KEY) STRICT;
CREATE TABLE live_sources(id TEXT PRIMARY KEY REFERENCES live_source_identities(id),name TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),state TEXT NOT NULL CHECK(state IN ('active','disabled')),tuner_count INTEGER NOT NULL CHECK(tuner_count>=0),active_generation TEXT NOT NULL,published_at TEXT NOT NULL) STRICT;
CREATE TABLE live_generations(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES live_source_identities(id),name TEXT NOT NULL,tuner_count INTEGER NOT NULL,channel_count INTEGER NOT NULL,programme_count INTEGER NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TABLE live_channel_versions(generation_id TEXT NOT NULL REFERENCES live_generations(id),channel_id TEXT NOT NULL,provider_key TEXT NOT NULL,name TEXT NOT NULL,number TEXT NOT NULL,group_name TEXT NOT NULL,position INTEGER NOT NULL,locator_sealed BLOB NOT NULL,available_start TEXT NOT NULL,available_end TEXT NOT NULL,PRIMARY KEY(generation_id,channel_id),UNIQUE(generation_id,position)) STRICT;
CREATE TABLE live_channel_logos(
 generation_id TEXT NOT NULL,
 channel_id TEXT NOT NULL,
 url TEXT NOT NULL,
 PRIMARY KEY(generation_id,channel_id),
 FOREIGN KEY(generation_id,channel_id) REFERENCES live_channel_versions(generation_id,channel_id)
) WITHOUT ROWID, STRICT;
CREATE TABLE live_logo_jobs(
 source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),
 generation_id TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','complete','failed')),
 imported INTEGER NOT NULL DEFAULT 0,
 skipped INTEGER NOT NULL DEFAULT 0
, last_channel TEXT NOT NULL DEFAULT '', next_attempt_ms INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID, STRICT;
CREATE TABLE identity_credential_state (
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 must_change INTEGER NOT NULL DEFAULT 0 CHECK(must_change IN (0,1))) STRICT;
CREATE TABLE identity_credential_attempts(
 account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 source_bucket TEXT NOT NULL,
 failed_attempts INTEGER NOT NULL,
 last_failure INTEGER NOT NULL,
 locked_until INTEGER NOT NULL,
 PRIMARY KEY(account_id,source_bucket)
) STRICT;
CREATE TABLE authorization_family_grants(
 family_id TEXT PRIMARY KEY REFERENCES authorization_session_families(id) ON DELETE CASCADE,
 grant_kind TEXT NOT NULL CHECK(grant_kind IN ('viewer_only'))
) STRICT;
CREATE TABLE direct_profile_pin_attempts(
 profile_id TEXT NOT NULL REFERENCES direct_profiles(id) ON DELETE CASCADE,
 device_id TEXT NOT NULL REFERENCES identity_devices(id) ON DELETE CASCADE,
 failed_attempts INTEGER NOT NULL DEFAULT 0,
 last_failed_ms INTEGER NOT NULL DEFAULT 0,
 locked_until_ms INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(profile_id,device_id)
) STRICT;
CREATE TABLE client_log_daily_usage(
 account_id TEXT NOT NULL,
 day_ms INTEGER NOT NULL,
 bytes INTEGER NOT NULL CHECK(bytes>=0),
 PRIMARY KEY(account_id,day_ms)
) STRICT;
CREATE TABLE quick_connect_v1(
 id TEXT PRIMARY KEY,create_hash TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,create_cipher BLOB NOT NULL,
 secret_hash TEXT NOT NULL UNIQUE,user_hash TEXT UNIQUE,device_name TEXT NOT NULL,platform TEXT NOT NULL,app_version TEXT NOT NULL,
 private_request INTEGER NOT NULL,expires_at INTEGER NOT NULL,next_poll INTEGER NOT NULL,interval_seconds INTEGER NOT NULL DEFAULT 5,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','consumed','denied','cancelled','expired')),
 approver_id TEXT,grant_cipher BLOB,family_id TEXT,token_hash TEXT,recovery_until INTEGER, installation_id TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE setup_rate_limits_v1(subject_hash TEXT NOT NULL,kind TEXT NOT NULL,window_start INTEGER NOT NULL,attempts INTEGER NOT NULL,PRIMARY KEY(subject_hash,kind)) STRICT;
CREATE TABLE onboarding_state_v1(singleton INTEGER PRIMARY KEY CHECK(singleton=1),auth_mode TEXT NOT NULL CHECK(auth_mode IN ('hosted','local')),
 operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,setup_hash TEXT NOT NULL,receipt BLOB,receipt_until INTEGER NOT NULL,
 recovery_account TEXT NOT NULL DEFAULT '',recovery_confirmed INTEGER NOT NULL DEFAULT 0,remote_recovery INTEGER NOT NULL DEFAULT 0,
 ready INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE identity_account_attempt_budget(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 failed_attempts INTEGER NOT NULL DEFAULT 0,
 last_failure INTEGER NOT NULL DEFAULT 0,
 next_allowed INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE api_idempotency(
 scope TEXT NOT NULL,
 key TEXT NOT NULL,
 digest TEXT NOT NULL,
 status INTEGER NOT NULL,
 body BLOB NOT NULL,
 expires_at INTEGER NOT NULL, headers TEXT NOT NULL DEFAULT '{}',
 PRIMARY KEY(scope,key)
) STRICT;
CREATE TABLE identity_refresh_predecessors(
 predecessor_hash TEXT PRIMARY KEY,
 family_id TEXT NOT NULL REFERENCES authorization_session_families(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE identity_unknown_attempts(
 subject_hash TEXT NOT NULL,
 source_bucket TEXT NOT NULL,
 failed_attempts INTEGER NOT NULL DEFAULT 0,
 last_failure INTEGER NOT NULL DEFAULT 0,
 locked_until INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(subject_hash,source_bucket)
) STRICT;
CREATE TABLE "networking_remote_settings"(singleton INTEGER PRIMARY KEY CHECK(singleton=1),authority TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1,enabled INTEGER NOT NULL DEFAULT 0,lan_sharing INTEGER NOT NULL DEFAULT 0,mapping INTEGER NOT NULL DEFAULT 0,pcp INTEGER NOT NULL DEFAULT 1,natpmp INTEGER NOT NULL DEFAULT 1,upnp INTEGER NOT NULL DEFAULT 1,public_port INTEGER NOT NULL DEFAULT 32500,gateway TEXT NOT NULL DEFAULT '',manual_url TEXT NOT NULL DEFAULT '',signature_key BLOB NOT NULL, ipv6_open INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE networking_remote_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),generation INTEGER NOT NULL DEFAULT 1,topology_digest TEXT NOT NULL DEFAULT '',route_digest TEXT NOT NULL DEFAULT '',next_attempt INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,retry_after INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT '{}') STRICT;
CREATE TABLE networking_mappings(id TEXT PRIMARY KEY,authority TEXT NOT NULL,protocol TEXT NOT NULL,expires_at INTEGER NOT NULL,next_attempt INTEGER NOT NULL,payload TEXT NOT NULL) STRICT;
CREATE TABLE networking_route_names(authority TEXT NOT NULL,address TEXT NOT NULL,port INTEGER NOT NULL,url TEXT NOT NULL,PRIMARY KEY(authority,address,port)) STRICT;
CREATE TABLE networking_address_absence(authority TEXT NOT NULL,family TEXT NOT NULL,since INTEGER NOT NULL,observations INTEGER NOT NULL,PRIMARY KEY(authority,family)) STRICT;
CREATE TABLE networking_certificate_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),enabled INTEGER NOT NULL DEFAULT 1,
 public_port INTEGER NOT NULL DEFAULT 32500 CHECK(public_port BETWEEN 1 AND 65535),
 public_address TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 1,
 server_id TEXT NOT NULL DEFAULT '',local_generation INTEGER NOT NULL DEFAULT -1,incarnation TEXT NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE networking_certificate_state (
 scope_id TEXT PRIMARY KEY,operation_id TEXT NOT NULL,server_id TEXT NOT NULL,
 local_generation INTEGER NOT NULL,claim_generation TEXT NOT NULL,credential_generation TEXT NOT NULL,incarnation TEXT NOT NULL,
 namespace TEXT NOT NULL DEFAULT '',issuer TEXT NOT NULL DEFAULT '',environment TEXT NOT NULL DEFAULT '',
 pending_id TEXT NOT NULL DEFAULT '',active_id TEXT NOT NULL DEFAULT '',previous_id TEXT NOT NULL DEFAULT '',
 state TEXT NOT NULL DEFAULT 'waiting',error_code TEXT NOT NULL DEFAULT '',next_attempt INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,
 route_address TEXT NOT NULL DEFAULT '',route_port INTEGER NOT NULL DEFAULT 0,route_hostname TEXT NOT NULL DEFAULT '',route_url TEXT NOT NULL DEFAULT '',route_next_attempt INTEGER NOT NULL DEFAULT 0,route_error_code TEXT NOT NULL DEFAULT ''
) STRICT;
CREATE TABLE networking_certificates (
 request_id TEXT PRIMARY KEY,scope_id TEXT NOT NULL REFERENCES networking_certificate_state(scope_id),
 key_nonce BLOB NOT NULL,key_cipher BLOB NOT NULL,csr BLOB NOT NULL,
 order_id TEXT NOT NULL DEFAULT '',state TEXT NOT NULL DEFAULT 'pending',chain BLOB NOT NULL DEFAULT X'',
 not_before INTEGER NOT NULL DEFAULT 0,not_after INTEGER NOT NULL DEFAULT 0,renew_at INTEGER NOT NULL DEFAULT 0,
 created_at INTEGER NOT NULL
) STRICT;
CREATE TABLE hosted_claim_cleanup_schedule(operation_id TEXT PRIMARY KEY REFERENCES networking_claim_intents(operation_id),next_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,retired INTEGER NOT NULL DEFAULT 0,complete INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE hosted_claim_cleanup_receipts(operation_id TEXT NOT NULL REFERENCES networking_claim_intents(operation_id),job_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision=1),target_digest TEXT NOT NULL,acknowledged INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(operation_id,job_id)) STRICT;
CREATE TABLE networking_control_schedule(
 operation_id TEXT PRIMARY KEY, claim_generation TEXT NOT NULL,
 credential_generation TEXT NOT NULL, heartbeat_at INTEGER NOT NULL DEFAULT 0,
 renewal_at INTEGER NOT NULL DEFAULT 0, retry_at INTEGER NOT NULL DEFAULT 0,
 attempts INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE networking_server_identities(
 server_id TEXT PRIMARY KEY CHECK(length(server_id)=47 AND substr(server_id,1,4)='srv_'),
 public_key BLOB NOT NULL UNIQUE CHECK(length(public_key)=32),
 key_incarnation TEXT NOT NULL UNIQUE CHECK(length(key_incarnation) BETWEEN 1 AND 128),
 created_at TEXT NOT NULL,
 UNIQUE(server_id,public_key)
) STRICT;
CREATE TABLE networking_claim_identity(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 server_id TEXT NOT NULL UNIQUE CHECK(length(server_id) BETWEEN 1 AND 128),
 public_key BLOB NOT NULL CHECK(length(public_key)=32),
 reset_generation INTEGER NOT NULL CHECK(reset_generation>=0),
 active_operation_id TEXT,
 installed_operation_id TEXT,
 FOREIGN KEY(server_id,public_key) REFERENCES networking_server_identities(server_id,public_key),
 CHECK(installed_operation_id IS NULL OR (active_operation_id IS NOT NULL AND installed_operation_id=active_operation_id))
) STRICT;
CREATE TABLE networking_claim_intents(
 operation_id TEXT PRIMARY KEY CHECK(length(operation_id) BETWEEN 1 AND 128),
 server_id TEXT NOT NULL,
 account_id TEXT NOT NULL CHECK(length(account_id) BETWEEN 1 AND 128),
 public_key BLOB NOT NULL CHECK(length(public_key)=32),
 local_generation INTEGER NOT NULL CHECK(local_generation>=0),
 revision INTEGER NOT NULL CHECK(revision>0),
 stage TEXT NOT NULL CHECK(stage IN('prepared','approved','finalizing','retrieving','installed','cancel_pending','cancelled')),
 owner_id TEXT NOT NULL CHECK(length(owner_id) BETWEEN 1 AND 128),
 owner_profile_id TEXT NOT NULL CHECK(length(owner_profile_id) BETWEEN 1 AND 128),
 owner_epoch INTEGER NOT NULL CHECK(owner_epoch>=0),
 approval_revision INTEGER NOT NULL DEFAULT 0 CHECK(approval_revision>=0),
 approval_issued_at TEXT NOT NULL DEFAULT '',
 approval_expires_at TEXT NOT NULL DEFAULT '',
 claim_generation TEXT NOT NULL DEFAULT '',
 credential_generation TEXT NOT NULL DEFAULT '',
 installation_acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(installation_acknowledged IN(0,1)),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
 FOREIGN KEY(server_id,public_key) REFERENCES networking_server_identities(server_id,public_key),
 UNIQUE(operation_id,server_id,account_id,local_generation,claim_generation,credential_generation),
 CHECK((claim_generation='')=(credential_generation='')),
 CHECK(stage NOT IN('retrieving','installed') OR claim_generation<>''),
 CHECK(installation_acknowledged=0 OR stage IN('installed','cancel_pending','cancelled'))
) STRICT;
CREATE TABLE networking_claim_cancellations(
 operation_id TEXT PRIMARY KEY REFERENCES networking_claim_intents(operation_id),
 request_id TEXT NOT NULL UNIQUE CHECK(length(request_id) BETWEEN 1 AND 128),
 mode TEXT NOT NULL CHECK(mode IN('intent','committed')),
 claim_generation TEXT NOT NULL,
 payload BLOB NOT NULL CHECK(length(payload) BETWEEN 1 AND 16384),
 signature BLOB NOT NULL CHECK(length(signature)=64),
 state TEXT NOT NULL CHECK(state IN('pending','acknowledged')),
 created_at TEXT NOT NULL, acknowledged_at TEXT NOT NULL DEFAULT '',
 CHECK((mode='intent' AND claim_generation='') OR (mode='committed' AND claim_generation<>''))
) STRICT;
CREATE TABLE networking_claim_authority(
 operation_id TEXT PRIMARY KEY,
 server_id TEXT NOT NULL, account_id TEXT NOT NULL,
 local_generation INTEGER NOT NULL CHECK(typeof(local_generation)='integer' AND local_generation>=0),
 claim_generation TEXT NOT NULL CHECK(CAST(CAST(claim_generation AS INTEGER) AS TEXT)=claim_generation AND CAST(claim_generation AS INTEGER)>0),
 credential_generation TEXT NOT NULL CHECK(CAST(CAST(credential_generation AS INTEGER) AS TEXT)=credential_generation AND CAST(credential_generation AS INTEGER)>0),
 observation_revision INTEGER NOT NULL CHECK(typeof(observation_revision)='integer' AND observation_revision>0),
 state TEXT NOT NULL CHECK(state IN('active','revoked','account_deleted','unclaimed','reassigned')),
 issued_at TEXT NOT NULL, expires_at TEXT NOT NULL,
 payload_sha256 BLOB NOT NULL CHECK(length(payload_sha256)=32),
 FOREIGN KEY(operation_id,server_id,account_id,local_generation,claim_generation,credential_generation) REFERENCES networking_claim_intents(operation_id,server_id,account_id,local_generation,claim_generation,credential_generation)
) STRICT;
CREATE TABLE networking_claim_schema(singleton INTEGER PRIMARY KEY CHECK(singleton=1),version INTEGER NOT NULL CHECK(version=3)) STRICT;
CREATE TABLE "artwork_variants"(
 source_digest TEXT NOT NULL REFERENCES artwork_objects(digest) ON DELETE CASCADE,
 width INTEGER NOT NULL CHECK(width IN(400,800,1920)),
 digest TEXT NOT NULL REFERENCES artwork_objects(digest),
 PRIMARY KEY(source_digest,width)
) STRICT;
CREATE TABLE playback_device_capabilities(
 device_id TEXT PRIMARY KEY REFERENCES identity_devices(id) ON DELETE CASCADE,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 revision INTEGER NOT NULL,
 document TEXT NOT NULL,
 updated_at_ms INTEGER NOT NULL
, planner_profile TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE playback_v1_sessions(
 id TEXT PRIMARY KEY,
 device_id TEXT NOT NULL,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 authority TEXT NOT NULL,
 start_key TEXT NOT NULL,
 start_digest TEXT NOT NULL,
 kind TEXT NOT NULL,
 role TEXT NOT NULL,
 state TEXT NOT NULL,
 item_id INTEGER NOT NULL DEFAULT 0,
 version_id TEXT NOT NULL DEFAULT '',
 part_index INTEGER NOT NULL DEFAULT 0,
 channel_id TEXT NOT NULL DEFAULT '',
 queue_id TEXT NOT NULL DEFAULT '',
 entry_id TEXT NOT NULL DEFAULT '',
 transfer_id TEXT NOT NULL DEFAULT '',
 group_id TEXT NOT NULL DEFAULT '',
 request TEXT NOT NULL,
 revision INTEGER NOT NULL,
 generation INTEGER NOT NULL,
 media_session_id TEXT NOT NULL DEFAULT '',
 media_generation INTEGER NOT NULL DEFAULT 0,
 presentation TEXT NOT NULL DEFAULT '',
 start_position_ms INTEGER NOT NULL DEFAULT 0,
 position_ms INTEGER NOT NULL DEFAULT 0,
 last_seq INTEGER NOT NULL DEFAULT 0,
 audio_track_id TEXT NOT NULL DEFAULT '',
 subtitle_track_id TEXT NOT NULL DEFAULT '',
 bandwidth_kbps INTEGER NOT NULL DEFAULT 0,
 location TEXT NOT NULL DEFAULT 'local',
 lease_expires_ms INTEGER NOT NULL,
 created_ms INTEGER NOT NULL,
 updated_ms INTEGER NOT NULL,
 ended_ms INTEGER NOT NULL DEFAULT 0,
 end_reason TEXT NOT NULL DEFAULT '',
 message TEXT NOT NULL DEFAULT '', paused_since_ms INTEGER NOT NULL DEFAULT 0,
 UNIQUE(device_id,start_key)
) STRICT;
CREATE TABLE api_events(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 audience TEXT NOT NULL,
 type TEXT NOT NULL,
 resource_kind TEXT NOT NULL DEFAULT '',
 resource_id TEXT NOT NULL DEFAULT '',
 revision TEXT NOT NULL DEFAULT '',
 data TEXT NOT NULL DEFAULT '',
 at_ms INTEGER NOT NULL
) STRICT;
CREATE TABLE queues_v1(
 id TEXT PRIMARY KEY,
 owner_kind TEXT NOT NULL CHECK(owner_kind IN('device','group')),
 owner_id TEXT NOT NULL,
 authority TEXT NOT NULL,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 revision INTEGER NOT NULL,
 current_position INTEGER NOT NULL DEFAULT 0,
 repeat TEXT NOT NULL DEFAULT 'off' CHECK(repeat IN('off','one','all')),
 shuffle_on INTEGER NOT NULL DEFAULT 0,
 shuffle_seed INTEGER NOT NULL DEFAULT 0,
 shuffle_lap INTEGER NOT NULL DEFAULT 0,
 shuffle_domain INTEGER NOT NULL DEFAULT 0,
 shuffle_first INTEGER NOT NULL DEFAULT 0,
 session_id TEXT NOT NULL DEFAULT '',
 created_ms INTEGER NOT NULL,
 updated_ms INTEGER NOT NULL
) STRICT;
CREATE TABLE queue_v1_snapshots(
 id TEXT PRIMARY KEY,
 queue_id TEXT NOT NULL REFERENCES queues_v1(id) ON DELETE CASCADE,
 kind TEXT NOT NULL,
 selector TEXT NOT NULL,
 label TEXT NOT NULL,
 count INTEGER NOT NULL,
 width INTEGER NOT NULL
, state TEXT NOT NULL DEFAULT 'ready' CHECK(state IN('building','ready','failed')), built INTEGER NOT NULL DEFAULT 0, seen INTEGER NOT NULL DEFAULT 0, caller TEXT NOT NULL DEFAULT '', start TEXT NOT NULL DEFAULT '', hint_ordinal INTEGER NOT NULL DEFAULT -1, hint_key TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE queue_v1_chunks(
 snapshot_id TEXT NOT NULL REFERENCES queue_v1_snapshots(id) ON DELETE CASCADE,
 chunk_no INTEGER NOT NULL,
 keys BLOB NOT NULL,
 PRIMARY KEY(snapshot_id,chunk_no)
) WITHOUT ROWID, STRICT;
CREATE TABLE queue_v1_segments(
 id TEXT PRIMARY KEY,
 queue_id TEXT NOT NULL REFERENCES queues_v1(id) ON DELETE CASCADE,
 sort_key TEXT NOT NULL,
 snapshot_id TEXT NOT NULL REFERENCES queue_v1_snapshots(id) ON DELETE CASCADE,
 first_ordinal INTEGER NOT NULL,
 count INTEGER NOT NULL,
 removed INTEGER NOT NULL DEFAULT 0,
 UNIQUE(queue_id,sort_key)
) STRICT;
CREATE TABLE queue_v1_removals(
 snapshot_id TEXT NOT NULL REFERENCES queue_v1_snapshots(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL,
 PRIMARY KEY(snapshot_id,ordinal)
) WITHOUT ROWID, STRICT;
CREATE TABLE queue_v1_container_counts(
 selector TEXT PRIMARY KEY,
 catalog TEXT NOT NULL,
 keys INTEGER NOT NULL,
 counted_ms INTEGER NOT NULL
) WITHOUT ROWID, STRICT;
CREATE TABLE queue_v1_create_receipts(
 device_id TEXT NOT NULL,
 create_key TEXT NOT NULL,
 digest TEXT NOT NULL,
 queue_id TEXT NOT NULL,
 response TEXT NOT NULL DEFAULT '',
 created_ms INTEGER NOT NULL,
 PRIMARY KEY(device_id,create_key)
) WITHOUT ROWID, STRICT;
CREATE TABLE live_remote_save_bindings(request_id TEXT PRIMARY KEY,preview_id TEXT NOT NULL,source_id TEXT NOT NULL,sealed BLOB NOT NULL,created_ms INTEGER NOT NULL) STRICT;
CREATE TABLE live_remote_previews(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,expected_revision INTEGER NOT NULL,fence TEXT NOT NULL,sealed BLOB NOT NULL,expires_ms INTEGER NOT NULL) STRICT;
CREATE TABLE live_remote_configs(source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),sealed BLOB NOT NULL,next_due_ms INTEGER NOT NULL,failures INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'healthy',error_code TEXT NOT NULL DEFAULT '',lease_token TEXT NOT NULL DEFAULT '',lease_until_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE live_source_settings(source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),physical_count INTEGER NOT NULL DEFAULT 0,owner_limit INTEGER NOT NULL DEFAULT 0,viewer_access TEXT NOT NULL DEFAULT 'owner-only' CHECK(viewer_access IN ('owner-only','server-members'))) STRICT;
CREATE TABLE live_source_dependencies(source_id TEXT NOT NULL REFERENCES live_source_identities(id),kind TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(source_id,kind,id)) STRICT;
CREATE TABLE live_source_removals(source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),request_id TEXT NOT NULL UNIQUE,revision INTEGER NOT NULL,removed_at TEXT NOT NULL) STRICT;
CREATE TABLE live_allocations(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES live_source_identities(id),channel_id TEXT NOT NULL,resource_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('live','recording')),authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,token TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),state TEXT NOT NULL CHECK(state IN ('active','preempting','released')),lease_until_ms INTEGER NOT NULL,created_ms INTEGER NOT NULL,preempt_at_ms INTEGER NOT NULL DEFAULT 0,UNIQUE(kind,resource_id)) STRICT;
CREATE TABLE live_allocation_reconcile_cursor(singleton INTEGER PRIMARY KEY CHECK(singleton=1),cursor TEXT NOT NULL) STRICT;
CREATE TABLE live_reservations(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES live_source_identities(id),start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,priority INTEGER NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),CHECK(end_ms>start_ms)) STRICT;
CREATE TABLE live_channel_preferences(authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,source_id TEXT NOT NULL,channel_id TEXT NOT NULL,favorite INTEGER NOT NULL CHECK(favorite IN(0,1)),hidden INTEGER NOT NULL CHECK(hidden IN(0,1)),revision INTEGER NOT NULL,PRIMARY KEY(authority,account_id,profile_id,source_id,channel_id)) STRICT;
CREATE TABLE live_preference_receipts(authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,request_id TEXT NOT NULL,digest TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(authority,account_id,profile_id,request_id)) STRICT;
CREATE TABLE live_operations(request_id TEXT PRIMARY KEY,input_hash TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES live_source_identities(id),generation_id TEXT NOT NULL REFERENCES live_generations(id),expected_revision INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('staging','published','superseded')),result_revision INTEGER NOT NULL DEFAULT 0,result_state TEXT NOT NULL DEFAULT '',published_at TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE live_programmes(generation_id TEXT NOT NULL REFERENCES live_generations(id),id TEXT NOT NULL,channel_id TEXT NOT NULL,provider_key TEXT NOT NULL,title TEXT NOT NULL,start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,lineage TEXT NOT NULL,CHECK(end_utc>start_utc),PRIMARY KEY(generation_id,id),FOREIGN KEY(generation_id,channel_id) REFERENCES live_channel_versions(generation_id,channel_id)) STRICT;
CREATE TABLE live_programme_metadata(generation_id TEXT NOT NULL,id TEXT NOT NULL,series_id TEXT NOT NULL,episode_id TEXT NOT NULL,new_evidence TEXT NOT NULL,description TEXT NOT NULL, facts TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(generation_id,id),FOREIGN KEY(generation_id,id) REFERENCES live_programmes(generation_id,id)) STRICT;
CREATE TABLE live_enable_receipts(request_id TEXT PRIMARY KEY,input_hash TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES live_sources(id),result_revision INTEGER NOT NULL) STRICT;
CREATE TABLE lc_maintenance_cursor(singleton INTEGER PRIMARY KEY CHECK(singleton=1),position INTEGER NOT NULL DEFAULT -1,channel_id TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE lc_channels(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,config_json TEXT NOT NULL,enabled INTEGER NOT NULL,position INTEGER NOT NULL,name TEXT NOT NULL,active_generation TEXT NOT NULL DEFAULT '',state TEXT NOT NULL,health_code TEXT NOT NULL DEFAULT '',generated_through_ms INTEGER NOT NULL DEFAULT 0,removed INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE lc_receipts(request_id TEXT PRIMARY KEY,digest TEXT NOT NULL,result_json TEXT NOT NULL) STRICT;
CREATE TABLE lc_generations(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES lc_channels(id),config_revision INTEGER NOT NULL,config_json TEXT NOT NULL,catalog_fence TEXT NOT NULL,seed TEXT NOT NULL,status TEXT NOT NULL,phase TEXT NOT NULL,base_generation TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,boundary_ms INTEGER NOT NULL,copy_after_ms INTEGER NOT NULL DEFAULT -1,scan_rule INTEGER NOT NULL DEFAULT 0,scan_after TEXT NOT NULL DEFAULT '',cursor_ms INTEGER NOT NULL,candidate_count INTEGER NOT NULL DEFAULT 0,unresolved_count INTEGER NOT NULL DEFAULT 0,lease_token TEXT NOT NULL DEFAULT '',lease_until_ms INTEGER NOT NULL DEFAULT 0,created_ms INTEGER NOT NULL,published_ms INTEGER NOT NULL DEFAULT 0,error_code TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE lc_candidates(generation_id TEXT NOT NULL REFERENCES lc_generations(id),rule_id TEXT NOT NULL,item_id INTEGER NOT NULL,ordinal INTEGER NOT NULL,library_id TEXT NOT NULL,asset_id TEXT NOT NULL,source_fence TEXT NOT NULL,duration_ms INTEGER NOT NULL CHECK(duration_ms>0),title TEXT NOT NULL,show_id INTEGER NOT NULL,season INTEGER NOT NULL,episode INTEGER NOT NULL,weight REAL NOT NULL CHECK(weight>0),sort_key TEXT NOT NULL,PRIMARY KEY(generation_id,rule_id,item_id),UNIQUE(generation_id,rule_id,ordinal)) STRICT;
CREATE TABLE lc_entries(generation_id TEXT NOT NULL REFERENCES lc_generations(id),occurrence_id TEXT NOT NULL,channel_id TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL CHECK(end_ms>start_ms),item_id INTEGER NOT NULL,asset_id TEXT NOT NULL,library_id TEXT NOT NULL,source_fence TEXT NOT NULL,title TEXT NOT NULL,rule_id TEXT NOT NULL,block_id TEXT NOT NULL,source_offset_ms INTEGER NOT NULL,slate_reason TEXT NOT NULL,PRIMARY KEY(generation_id,occurrence_id),UNIQUE(generation_id,start_ms)) STRICT;
CREATE TABLE lc_rule_state(generation_id TEXT NOT NULL,rule_id TEXT NOT NULL,draw INTEGER NOT NULL,cycle INTEGER NOT NULL,last_sort TEXT NOT NULL,last_show TEXT NOT NULL,last_block TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(generation_id,rule_id)) STRICT;
CREATE TABLE lc_used(generation_id TEXT NOT NULL,rule_id TEXT NOT NULL,item_id INTEGER NOT NULL,cycle INTEGER NOT NULL,PRIMARY KEY(generation_id,rule_id,item_id)) STRICT;
CREATE TABLE lc_playback_refs(playback_id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,generation_id TEXT NOT NULL,occurrence_id TEXT NOT NULL,end_ms INTEGER NOT NULL,lease_until_ms INTEGER NOT NULL) STRICT;
CREATE TABLE lc_template_installs(template_key TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES lc_channels(id),template_version INTEGER NOT NULL) STRICT;
CREATE TABLE dvr_owner_revisions(owner_key TEXT PRIMARY KEY,revision INTEGER NOT NULL) STRICT;
CREATE TABLE dvr_receipts(owner_key TEXT NOT NULL,request_id TEXT NOT NULL,digest TEXT NOT NULL,result_json TEXT NOT NULL,created_ms INTEGER NOT NULL,PRIMARY KEY(owner_key,request_id)) STRICT;
CREATE TABLE dvr_rules(
 id TEXT PRIMARY KEY,owner_key TEXT NOT NULL,authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES live_source_identities(id),series_id TEXT NOT NULL,revision INTEGER NOT NULL,
 config_json TEXT NOT NULL,enabled INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,updated_ms INTEGER NOT NULL,
 UNIQUE(owner_key,source_id,series_id)) STRICT;
CREATE TABLE dvr_recordings(
 id TEXT PRIMARY KEY,owner_key TEXT NOT NULL,authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 source_id TEXT NOT NULL REFERENCES live_source_identities(id),channel_id TEXT NOT NULL,programme_id TEXT NOT NULL,guide_generation TEXT NOT NULL,
 programme_json TEXT NOT NULL,rule_id TEXT NOT NULL DEFAULT '',rule_revision INTEGER NOT NULL DEFAULT 0,manual INTEGER NOT NULL DEFAULT 0,
 options_json TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,priority INTEGER NOT NULL,
 revision INTEGER NOT NULL,state TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',keep INTEGER NOT NULL DEFAULT 0,
 cancel_generation INTEGER NOT NULL DEFAULT 0,claim_generation INTEGER NOT NULL DEFAULT 0,claim_token TEXT NOT NULL DEFAULT '',
 next_attempt_ms INTEGER NOT NULL DEFAULT 0,recovery_attempt INTEGER NOT NULL DEFAULT 0,checkpoint_json TEXT NOT NULL DEFAULT '{}',
 lease_until_ms INTEGER NOT NULL DEFAULT 0,owner_instance TEXT NOT NULL DEFAULT '',allocation_id TEXT NOT NULL DEFAULT '',
 item_id INTEGER NOT NULL DEFAULT 0,artifact_id TEXT NOT NULL DEFAULT '',artifact_digest TEXT NOT NULL DEFAULT '',
 captured_start_ms INTEGER NOT NULL DEFAULT 0,captured_end_ms INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,
 created_ms INTEGER NOT NULL,updated_ms INTEGER NOT NULL,finished_ms INTEGER NOT NULL DEFAULT 0,
 UNIQUE(owner_key,source_id,programme_id),CHECK(end_ms>start_ms)) STRICT;
CREATE TABLE dvr_rule_work(
 rule_id TEXT PRIMARY KEY REFERENCES dvr_rules(id),rule_revision INTEGER NOT NULL,generation TEXT NOT NULL,
 phase TEXT NOT NULL,cursor TEXT NOT NULL DEFAULT '',not_before_ms INTEGER NOT NULL DEFAULT 0,updated_ms INTEGER NOT NULL,
 diagnostic TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE dvr_maintenance_cursors(kind TEXT PRIMARY KEY,cursor TEXT NOT NULL) STRICT;
CREATE TABLE dvr_delete_work(
 recording_id TEXT PRIMARY KEY REFERENCES dvr_recordings(id),revision INTEGER NOT NULL,requested_ms INTEGER NOT NULL,
 not_before_ms INTEGER NOT NULL,phase TEXT NOT NULL,attempt INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE dvr_retention_retry(recording_id TEXT PRIMARY KEY REFERENCES dvr_recordings(id),not_before_ms INTEGER NOT NULL) STRICT;
CREATE TABLE dvr_cleanup_work(recording_id TEXT PRIMARY KEY REFERENCES dvr_recordings(id),not_before_ms INTEGER NOT NULL) STRICT;
CREATE TABLE dvr_storage_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL,
 retention_days INTEGER NOT NULL,episode_limit INTEGER NOT NULL,floor_bytes INTEGER NOT NULL,cap_bytes INTEGER NOT NULL) STRICT;
CREATE TABLE remote_sources(
 id TEXT PRIMARY KEY,kind TEXT NOT NULL,name TEXT NOT NULL,root TEXT NOT NULL UNIQUE,
 generation INTEGER NOT NULL DEFAULT 1,config BLOB,state TEXT NOT NULL DEFAULT 'ready',error_code TEXT NOT NULL DEFAULT '',
 range_support TEXT NOT NULL DEFAULT 'unknown',origin TEXT NOT NULL DEFAULT '',insecure INTEGER NOT NULL DEFAULT 0,
 credential_present INTEGER NOT NULL DEFAULT 0,mount_id TEXT NOT NULL DEFAULT '',removed INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE remote_source_operations(operation_id TEXT PRIMARY KEY,actor TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,created_at INTEGER NOT NULL) STRICT;
CREATE TABLE remote_listing_sessions(id TEXT PRIMARY KEY,job_id TEXT NOT NULL,source_id TEXT NOT NULL,generation TEXT NOT NULL,directory TEXT NOT NULL,ready INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(job_id,directory)) STRICT;
CREATE TABLE remote_native_listings(listing_id TEXT PRIMARY KEY REFERENCES remote_listing_sessions(id) ON DELETE CASCADE,owner TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('running','complete','failed')),error_code TEXT NOT NULL DEFAULT '',entries INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE remote_listing_progress(listing_id TEXT PRIMARY KEY REFERENCES remote_listing_sessions(id) ON DELETE CASCADE,token BLOB,mode TEXT NOT NULL,steps INTEGER NOT NULL DEFAULT 0,restarted INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE remote_listing_entries(listing_id TEXT NOT NULL REFERENCES remote_listing_sessions(id) ON DELETE CASCADE,name TEXT NOT NULL,snapshot TEXT NOT NULL,PRIMARY KEY(listing_id,name)) STRICT;
CREATE TABLE remote_inventory_checks(job_id TEXT NOT NULL,directory TEXT NOT NULL,listing_id TEXT NOT NULL,check_job TEXT NOT NULL,verified_ms INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(job_id,directory)) STRICT;
CREATE TABLE remote_scan_cursors(job_id TEXT NOT NULL,path TEXT NOT NULL,listing_id TEXT NOT NULL,cursor TEXT NOT NULL DEFAULT '',PRIMARY KEY(job_id,path)) STRICT;
CREATE TABLE remote_scan_generations(job_id TEXT NOT NULL,source_id TEXT NOT NULL,generation TEXT NOT NULL,PRIMARY KEY(job_id,source_id)) STRICT;
CREATE TABLE remote_object_refs(path TEXT PRIMARY KEY,revision TEXT NOT NULL) STRICT;
CREATE TABLE remote_analysis_status(path TEXT PRIMARY KEY,code TEXT NOT NULL,observed_at INTEGER NOT NULL) STRICT;
CREATE TABLE live_logo_failures(
 url TEXT PRIMARY KEY,
 attempts INTEGER NOT NULL DEFAULT 0,
 retry_after_ms INTEGER NOT NULL DEFAULT 0
) WITHOUT ROWID, STRICT;
CREATE TABLE profile_show_activity(
 profile_id TEXT NOT NULL,
 show_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id TEXT NOT NULL,
 last_activity TEXT NOT NULL,
 last_item_id TEXT NOT NULL,
 PRIMARY KEY(profile_id,show_id)) STRICT;
CREATE TABLE continue_show_dismissals(
 profile_id TEXT NOT NULL,
 show_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 item_id INTEGER NOT NULL,
 playback_id TEXT NOT NULL,
 last_activity TEXT NOT NULL,
 PRIMARY KEY(profile_id,show_id)) STRICT;
CREATE TABLE listening_book_series(
 book_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id TEXT NOT NULL,
 series_key TEXT NOT NULL,
 series_name TEXT NOT NULL) WITHOUT ROWID, STRICT;
CREATE TABLE library_metadata_agents(
 library_id TEXT PRIMARY KEY REFERENCES libraries(id) ON DELETE CASCADE,
 agent TEXT NOT NULL DEFAULT 'online' CHECK(length(agent) BETWEEN 1 AND 64),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(typeof(revision)='integer' AND revision>0)) WITHOUT ROWID, STRICT;
CREATE TABLE artwork_compaction_failures(
 digest TEXT PRIMARY KEY REFERENCES artwork_objects(digest) ON DELETE CASCADE,
 reason TEXT NOT NULL,
 failed_at TEXT NOT NULL) WITHOUT ROWID, STRICT;
CREATE TABLE playback_private_presentations(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 owner_session_id TEXT NOT NULL,
 expires_ms INTEGER NOT NULL
) WITHOUT ROWID, STRICT;
CREATE TABLE playback_v1_prepared(
 token TEXT PRIMARY KEY,
 queue_id TEXT NOT NULL REFERENCES queues_v1(id) ON DELETE CASCADE,
 device_id TEXT NOT NULL,
 create_key TEXT NOT NULL,
 digest TEXT NOT NULL,
 session_id TEXT NOT NULL,
 session_generation INTEGER NOT NULL,
 session_state TEXT NOT NULL,
 queue_revision INTEGER NOT NULL,
 next_position INTEGER NOT NULL,
 entry_id TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 media_session_id TEXT NOT NULL,
 request TEXT NOT NULL,
 presentation TEXT NOT NULL,
 expires_ms INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN('prepared','committed','canceled')),
 cancel_reason TEXT NOT NULL DEFAULT '',
 response TEXT NOT NULL DEFAULT '',
 created_ms INTEGER NOT NULL,
 UNIQUE(device_id,create_key)
) STRICT;
CREATE TABLE audio_render_facts(
 asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,
 size INTEGER NOT NULL,
 modified_ns INTEGER NOT NULL,
 container TEXT NOT NULL,
 codec TEXT NOT NULL,
 sample_rate INTEGER NOT NULL CHECK(sample_rate>0),
 channels INTEGER NOT NULL CHECK(channels>0),
 bit_depth INTEGER NOT NULL DEFAULT 0,
 raw_frames INTEGER NOT NULL CHECK(raw_frames>0),
 duration_frames INTEGER NOT NULL CHECK(duration_frames>0),
 start_frames INTEGER NOT NULL CHECK(start_frames>=0),
 end_frames INTEGER NOT NULL CHECK(end_frames>=0),
 trim_source TEXT NOT NULL,
 decoder_config TEXT NOT NULL DEFAULT '',
 measured_ms INTEGER NOT NULL,
 CHECK(start_frames+duration_frames+end_frames=raw_frames)
) WITHOUT ROWID, STRICT;
CREATE TABLE audio_render_fact_failures(
 asset_id TEXT PRIMARY KEY REFERENCES catalog_assets(token) ON DELETE CASCADE,
 size INTEGER NOT NULL,
 modified_ns INTEGER NOT NULL,
 code TEXT NOT NULL,
 failed_ms INTEGER NOT NULL
) WITHOUT ROWID, STRICT;
CREATE TABLE playback_audio_plans(
 session_id TEXT PRIMARY KEY REFERENCES playback_sessions(id) ON DELETE CASCADE,
 plan_json TEXT NOT NULL
) WITHOUT ROWID, STRICT;
CREATE TABLE playback_channel_sessions(
 session_id TEXT PRIMARY KEY REFERENCES playback_v1_sessions(id) ON DELETE CASCADE,
 authority TEXT NOT NULL,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 server_id TEXT NOT NULL,
 role TEXT NOT NULL,
 account_epoch INTEGER NOT NULL,
 family_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN('live-source','library-channel')),
 source_id TEXT NOT NULL,
 channel_id TEXT NOT NULL,
 selection_json TEXT NOT NULL,
 transport_json TEXT NOT NULL,
 client_profile_json TEXT NOT NULL DEFAULT '',
 source_revision INTEGER NOT NULL DEFAULT 1,
 retry_revision INTEGER NOT NULL DEFAULT 0,
 buffer_ordinal INTEGER NOT NULL DEFAULT 0,
 producer_ordinal INTEGER NOT NULL DEFAULT 0,
 observation_sequence INTEGER NOT NULL DEFAULT 0,
 observation_generation TEXT NOT NULL DEFAULT '',
 confirmed_position_us INTEGER,
 acknowledged_seek_id TEXT,
 seek_error TEXT NOT NULL DEFAULT '',
 error_code TEXT NOT NULL DEFAULT '',
 status TEXT NOT NULL DEFAULT 'preparing' CHECK(status IN('preparing','attachable','active','recoverable')),
 stage TEXT NOT NULL DEFAULT 'source' CHECK(stage IN('source','production','delivery','engine','recovery')),
 created_ms INTEGER NOT NULL,
 ended_ms INTEGER NOT NULL DEFAULT 0
) WITHOUT ROWID, STRICT;
CREATE TABLE account_portico_links(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 hosted_account_id TEXT NOT NULL UNIQUE CHECK(length(hosted_account_id) BETWEEN 1 AND 128),
 -- The account's own latest identity assertion for this server (a Hosted-
 -- signed envelope, JSON): its consent to be listed here. Forwarded with the
 -- membership push; Hosted indexes an account only with it (INT M6).
 consent TEXT NOT NULL DEFAULT '',
 -- Hosted declined to index it (no usable consent yet); left out of the
 -- check-in digest until a new consent arrives.
 unindexed INTEGER NOT NULL DEFAULT 0 CHECK(unindexed IN(0,1))) STRICT;
CREATE TABLE hosted_membership_journal(
 sequence INTEGER PRIMARY KEY AUTOINCREMENT,
 hosted_account_id TEXT NOT NULL) STRICT;
CREATE TABLE hosted_membership_sync(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 acked INTEGER NOT NULL DEFAULT 0 CHECK(acked>=0),
 full_pending INTEGER NOT NULL DEFAULT 1 CHECK(full_pending IN(0,1)),
 next_at INTEGER NOT NULL DEFAULT 0,
 attempts INTEGER NOT NULL DEFAULT 0,
 -- A full list goes in pages; these say how far the current one got.
 full_through INTEGER NOT NULL DEFAULT 0,
 full_page INTEGER NOT NULL DEFAULT 0,
 full_cursor TEXT NOT NULL DEFAULT '',
 -- The Hosted account holding custody of this server's claim, as Hosted's
 -- last push answer said: '' while custody is released, NULL before any
 -- answer. An owner whose Hosted account is not it is asked to accept
 -- custody (INT M6, M10).
 custodian TEXT) STRICT;
CREATE TABLE hosted_identity_nonces(
 nonce TEXT PRIMARY KEY,
 expires_ms INTEGER NOT NULL) STRICT;
CREATE TABLE hosted_identity_challenges(
 challenge_hash TEXT PRIMARY KEY,
 installation_id TEXT NOT NULL,
 expires_ms INTEGER NOT NULL) STRICT;
CREATE TABLE portico_admitted_families(
 family_id TEXT PRIMARY KEY REFERENCES authorization_session_families(id) ON DELETE CASCADE) STRICT;
CREATE TABLE portico_factor_challenges(
 token_hash TEXT PRIMARY KEY REFERENCES identity_factor_challenges(token_hash) ON DELETE CASCADE) STRICT;
CREATE TABLE hosted_migrated_families(family_id TEXT PRIMARY KEY, refresh_hash TEXT UNIQUE) STRICT;
CREATE TABLE live_programme_icons(
 generation_id TEXT NOT NULL,
 programme_id TEXT NOT NULL,
 url TEXT NOT NULL,
 PRIMARY KEY(generation_id,programme_id)
) WITHOUT ROWID, STRICT;
CREATE TABLE live_programme_images(
 url TEXT PRIMARY KEY,
 digest TEXT NOT NULL,
 media_type TEXT NOT NULL,
 width INTEGER NOT NULL,
 height INTEGER NOT NULL,
 stored_ms INTEGER NOT NULL
) WITHOUT ROWID, STRICT;
CREATE TABLE live_icon_jobs(
 source_id TEXT PRIMARY KEY REFERENCES live_source_identities(id),
 generation_id TEXT NOT NULL,
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','complete','failed')),
 last_url TEXT NOT NULL DEFAULT '',
 imported INTEGER NOT NULL DEFAULT 0,
 skipped INTEGER NOT NULL DEFAULT 0,
 next_attempt_ms INTEGER NOT NULL DEFAULT 0
) WITHOUT ROWID, STRICT;
CREATE TABLE "maintenance_window_tasks"(window_id TEXT NOT NULL REFERENCES maintenance_windows(id) ON DELETE CASCADE,task TEXT NOT NULL CHECK(task IN('library-scan','metadata-refresh','analysis','trickplay','backup')),PRIMARY KEY(window_id,task)) STRICT;
CREATE TABLE networking_claim_credentials(
 operation_id TEXT PRIMARY KEY REFERENCES networking_claim_intents(operation_id),
 server_id TEXT NOT NULL, local_generation INTEGER NOT NULL CHECK(local_generation>=0),
 claim_generation TEXT NOT NULL, credential_generation TEXT NOT NULL,
 nonce BLOB NOT NULL,
 ciphertext BLOB NOT NULL CHECK(length(ciphertext) BETWEEN 1 AND 2048),
 installed_at TEXT NOT NULL
) STRICT;
CREATE TABLE catalog_terms(
