 rating_key TEXT NOT NULL,label_key TEXT NOT NULL,dated INTEGER NOT NULL,retired INTEGER NOT NULL,total INTEGER NOT NULL CHECK(total>=0),
 PRIMARY KEY(library_id,kind,available,recent,backdrop,rating_key,label_key,dated,retired)) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_collection_visible_edges(
