-- ===== triggeres
CREATE TRIGGER library_revision_create AFTER INSERT ON libraries BEGIN INSERT INTO library_revisions VALUES(NEW.id,1);END;
CREATE TRIGGER revision_progress_INSERT AFTER INSERT ON progress_activity BEGIN INSERT INTO viewer_revisions(profile_id,library_id,revision) VALUES(NEW.profile_id,NEW.library_id,1) ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;END;
CREATE TRIGGER revision_progress_UPDATE AFTER UPDATE ON progress_activity BEGIN INSERT INTO viewer_revisions(profile_id,library_id,revision) VALUES(NEW.profile_id,NEW.library_id,1) ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;END;
CREATE TRIGGER revision_progress_DELETE AFTER DELETE ON progress_activity BEGIN INSERT INTO viewer_revisions(profile_id,library_id,revision) VALUES(OLD.profile_id,OLD.library_id,1) ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;END;
CREATE TRIGGER library_revision_update AFTER UPDATE ON libraries BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=NEW.id;END;
CREATE TRIGGER playlist_share_insert AFTER INSERT ON playlist_shares BEGIN
 INSERT INTO playlist_directory_revisions VALUES(NEW.authority,NEW.account_id,NEW.profile_id,1) ON CONFLICT(authority,account_id,profile_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER playlist_share_delete AFTER DELETE ON playlist_shares BEGIN
 INSERT INTO playlist_directory_revisions VALUES(OLD.authority,OLD.account_id,OLD.profile_id,1) ON CONFLICT(authority,account_id,profile_id) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER library_configuration_create AFTER INSERT ON libraries BEGIN INSERT INTO library_configuration(library_id) VALUES(NEW.id);END;
CREATE TRIGGER library_configuration_update AFTER UPDATE OF name,kind,root ON libraries BEGIN UPDATE library_configuration SET revision=revision+1 WHERE library_id=NEW.id;END;
CREATE TRIGGER job_observation_create AFTER INSERT ON jobs BEGIN INSERT INTO job_observations VALUES(NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL);END;
CREATE TRIGGER admin_revision_libraries_INSERT AFTER INSERT ON libraries BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER admin_revision_libraries_UPDATE AFTER UPDATE ON libraries BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER admin_revision_libraries_DELETE AFTER DELETE ON libraries BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER admin_revision_jobs_INSERT AFTER INSERT ON jobs BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER admin_revision_jobs_UPDATE AFTER UPDATE ON jobs BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER admin_revision_jobs_DELETE AFTER DELETE ON jobs BEGIN UPDATE admin_revision SET revision=revision+1 WHERE id=1;END;
CREATE TRIGGER metadata_publication_library_create AFTER INSERT ON libraries BEGIN
 INSERT INTO metadata_provider_policies(library_id,provider) VALUES(NEW.id,'tmdb');
END;
CREATE TRIGGER metadata_policy_changed AFTER UPDATE OF enabled,language,region,refresh_mode,algorithm ON metadata_provider_policies
 WHEN OLD.enabled IS NOT NEW.enabled OR OLD.language IS NOT NEW.language OR OLD.region IS NOT NEW.region OR OLD.refresh_mode IS NOT NEW.refresh_mode OR OLD.algorithm IS NOT NEW.algorithm
 BEGIN UPDATE metadata_provider_policies SET revision=revision+1 WHERE library_id=NEW.library_id AND provider=NEW.provider;END;
CREATE TRIGGER metadata_publication_provider_evidence_INSERT AFTER INSERT ON provider_evidence BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(NEW.item_id);END;
CREATE TRIGGER metadata_identity_INSERT AFTER INSERT ON provider_evidence BEGIN UPDATE metadata_publication_heads SET identity_revision=identity_revision+1 WHERE item_id IN(NEW.item_id);END;
CREATE TRIGGER metadata_publication_provider_evidence_UPDATE AFTER UPDATE ON provider_evidence BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id,NEW.item_id);END;
CREATE TRIGGER metadata_identity_UPDATE AFTER UPDATE ON provider_evidence WHEN OLD.item_id IS NOT NEW.item_id OR OLD.provider IS NOT NEW.provider OR OLD.provider_id IS NOT NEW.provider_id BEGIN UPDATE metadata_publication_heads SET identity_revision=identity_revision+1 WHERE item_id IN(OLD.item_id,NEW.item_id);END;
CREATE TRIGGER metadata_publication_provider_evidence_DELETE AFTER DELETE ON provider_evidence BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id);END;
CREATE TRIGGER metadata_identity_DELETE AFTER DELETE ON provider_evidence BEGIN UPDATE metadata_publication_heads SET identity_revision=identity_revision+1 WHERE item_id IN(OLD.item_id);END;
CREATE TRIGGER metadata_publication_metadata_details_INSERT AFTER INSERT ON metadata_details BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(NEW.item_id);END;
CREATE TRIGGER metadata_publication_metadata_details_UPDATE AFTER UPDATE ON metadata_details BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id,NEW.item_id);END;
CREATE TRIGGER metadata_publication_metadata_details_DELETE AFTER DELETE ON metadata_details BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id);END;
CREATE TRIGGER metadata_publication_metadata_ratings_INSERT AFTER INSERT ON metadata_ratings BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(NEW.item_id);END;
CREATE TRIGGER metadata_publication_metadata_ratings_UPDATE AFTER UPDATE ON metadata_ratings BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id,NEW.item_id);END;
CREATE TRIGGER metadata_publication_metadata_ratings_DELETE AFTER DELETE ON metadata_ratings BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.item_id);END;
CREATE TRIGGER mb_library_created AFTER INSERT ON libraries BEGIN INSERT INTO mb_provider_policies(library_id) VALUES(NEW.id);END;
CREATE TRIGGER mb_policy_changed AFTER UPDATE OF enabled,algorithm ON mb_provider_policies WHEN OLD.enabled IS NOT NEW.enabled OR OLD.algorithm IS NOT NEW.algorithm BEGIN UPDATE mb_provider_policies SET revision=revision+1 WHERE library_id=NEW.library_id;END;
CREATE TRIGGER mb_recording_evidence_immutable BEFORE UPDATE OF revision_id,provider_id,digest,title,artist,observed_at,payload,disambiguation,length_millis ON mb_recording_evidence BEGIN SELECT RAISE(ABORT,'immutable MusicBrainz evidence');END;
CREATE TRIGGER mb_recording_evidence_initial_open BEFORE INSERT ON mb_recording_evidence WHEN NEW.sealed<>0 OR EXISTS(SELECT 1 FROM mb_recording_evidence WHERE revision_id=NEW.revision_id OR (provider_id=NEW.provider_id AND digest=NEW.digest)) BEGIN SELECT RAISE(ABORT,'MusicBrainz evidence requires new construction');END;
CREATE TRIGGER mb_recording_evidence_seal_once BEFORE UPDATE OF sealed ON mb_recording_evidence WHEN OLD.sealed<>0 OR NEW.sealed<>1 BEGIN SELECT RAISE(ABORT,'MusicBrainz evidence seal is terminal');END;
CREATE TRIGGER mb_release_evidence_immutable BEFORE UPDATE OF revision_id,provider_id,digest,title,artist,observed_at,payload,disambiguation,release_group_id,group_title,primary_type,date,country,barcode ON mb_release_evidence BEGIN SELECT RAISE(ABORT,'immutable MusicBrainz evidence');END;
CREATE TRIGGER mb_release_evidence_initial_open BEFORE INSERT ON mb_release_evidence WHEN NEW.sealed<>0 OR EXISTS(SELECT 1 FROM mb_release_evidence WHERE revision_id=NEW.revision_id OR (provider_id=NEW.provider_id AND digest=NEW.digest)) BEGIN SELECT RAISE(ABORT,'MusicBrainz evidence requires new construction');END;
CREATE TRIGGER mb_release_evidence_seal_once BEFORE UPDATE OF sealed ON mb_release_evidence WHEN OLD.sealed<>0 OR NEW.sealed<>1 BEGIN SELECT RAISE(ABORT,'MusicBrainz evidence seal is terminal');END;
CREATE TRIGGER mb_recording_credits_immutable BEFORE UPDATE ON mb_recording_credits BEGIN SELECT RAISE(ABORT,'immutable MusicBrainz evidence child');END;
CREATE TRIGGER mb_recording_credits_sealed_insert BEFORE INSERT ON mb_recording_credits WHEN COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.revision_id),0)=1 BEGIN SELECT RAISE(ABORT,'sealed MusicBrainz child set');END;
CREATE TRIGGER mb_recording_credits_sealed_delete BEFORE DELETE ON mb_recording_credits WHEN COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=OLD.revision_id),0)=1 BEGIN SELECT RAISE(ABORT,'sealed MusicBrainz child set');END;
CREATE TRIGGER mb_release_credits_immutable BEFORE UPDATE ON mb_release_credits BEGIN SELECT RAISE(ABORT,'immutable MusicBrainz evidence child');END;
CREATE TRIGGER mb_release_credits_sealed_insert BEFORE INSERT ON mb_release_credits WHEN COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.revision_id),0)=1 BEGIN SELECT RAISE(ABORT,'sealed MusicBrainz child set');END;
CREATE TRIGGER mb_release_credits_sealed_delete BEFORE DELETE ON mb_release_credits WHEN COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=OLD.revision_id),0)=1 BEGIN SELECT RAISE(ABORT,'sealed MusicBrainz child set');END;
