CREATE TRIGGER mb_release_tracks_requires_sealed_update BEFORE UPDATE ON mb_release_tracks WHEN (NEW.recording_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.recording_revision),0)<>1) BEGIN SELECT RAISE(ABORT,'MusicBrainz reference requires sealed evidence');END;
CREATE TRIGGER mb_publication_operations_requires_sealed_insert BEFORE INSERT ON mb_publication_operations WHEN (NEW.accepted_recording_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.accepted_recording_revision),0)<>1) OR (NEW.accepted_release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.accepted_release_revision),0)<>1) OR (NEW.result_recording_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.result_recording_revision),0)<>1) OR (NEW.result_release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.result_release_revision),0)<>1) BEGIN SELECT RAISE(ABORT,'MusicBrainz reference requires sealed evidence');END;
CREATE TRIGGER mb_publication_operations_requires_sealed_update BEFORE UPDATE ON mb_publication_operations WHEN (NEW.accepted_recording_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.accepted_recording_revision),0)<>1) OR (NEW.accepted_release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.accepted_release_revision),0)<>1) OR (NEW.result_recording_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_recording_evidence WHERE revision_id=NEW.result_recording_revision),0)<>1) OR (NEW.result_release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.result_release_revision),0)<>1) BEGIN SELECT RAISE(ABORT,'MusicBrainz reference requires sealed evidence');END;
CREATE TRIGGER mb_album_reconciliations_requires_sealed_insert BEFORE INSERT ON mb_album_reconciliations WHEN (NEW.release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.release_revision),0)<>1) BEGIN SELECT RAISE(ABORT,'MusicBrainz reference requires sealed evidence');END;
CREATE TRIGGER mb_album_reconciliations_requires_sealed_update BEFORE UPDATE ON mb_album_reconciliations WHEN (NEW.release_revision IS NOT NULL AND COALESCE((SELECT sealed FROM mb_release_evidence WHERE revision_id=NEW.release_revision),0)<>1) BEGIN SELECT RAISE(ABORT,'MusicBrainz reference requires sealed evidence');END;
CREATE TRIGGER audio_metadata_library_created AFTER INSERT ON libraries WHEN NEW.kind IN('music','audiobook') BEGIN
  INSERT INTO audio_metadata_policies(library_id) VALUES(NEW.id);END;
CREATE TRIGGER tvdb_publication_policy_create AFTER INSERT ON libraries BEGIN
 INSERT INTO tvdb_provider_policies(library_id) VALUES(NEW.id);
END;
CREATE TRIGGER tvdb_publication_policy_changed AFTER UPDATE OF enabled,algorithm,refresh_mode ON tvdb_provider_policies
 WHEN OLD.enabled IS NOT NEW.enabled OR OLD.algorithm IS NOT NEW.algorithm OR OLD.refresh_mode IS NOT NEW.refresh_mode
 BEGIN UPDATE tvdb_provider_policies SET revision=revision+1 WHERE library_id=NEW.library_id;END;
CREATE TRIGGER tvdb_publication_job_selection AFTER UPDATE OF show_id,provider_id,episode_order,generation ON tvdb_jobs
 WHEN OLD.show_id IS NOT NEW.show_id OR OLD.provider_id IS NOT NEW.provider_id OR OLD.episode_order IS NOT NEW.episode_order OR OLD.generation IS NOT NEW.generation
 BEGIN UPDATE tvdb_publication_heads SET selection_revision=selection_revision+1 WHERE show_id IN(OLD.show_id,NEW.show_id);END;
CREATE TRIGGER tvdb_publication_coverage_changed AFTER UPDATE OF source_revision,hierarchy_revision ON tvdb_publication_heads
 WHEN OLD.source_revision IS NOT NEW.source_revision OR OLD.hierarchy_revision IS NOT NEW.hierarchy_revision
 BEGIN UPDATE tvdb_jobs SET status='pending_apply',apply_after='',revision=revision+1,lease='',lease_until='' WHERE show_id=NEW.show_id AND provider_id>0 AND episode_order<>'' AND status IN('complete','pending_apply');END;
CREATE TRIGGER tvdb_head_identity_immutable BEFORE UPDATE OF show_id,incarnation ON tvdb_publication_heads
 WHEN OLD.show_id IS NOT NEW.show_id OR OLD.incarnation IS NOT NEW.incarnation
 BEGIN SELECT RAISE(ABORT,'TVDB show identity is immutable');END;
CREATE TRIGGER tvdb_head_revision_monotonic BEFORE UPDATE ON tvdb_publication_heads
 WHEN NEW.source_revision<OLD.source_revision OR NEW.hierarchy_revision<OLD.hierarchy_revision OR NEW.selection_revision<OLD.selection_revision OR NEW.descriptive_revision<OLD.descriptive_revision
 BEGIN SELECT RAISE(ABORT,'TVDB show revision cannot decrease');END;
CREATE TRIGGER tvdb_policy_identity_immutable BEFORE UPDATE OF library_id,incarnation ON tvdb_provider_policies
 WHEN OLD.library_id IS NOT NEW.library_id OR OLD.incarnation IS NOT NEW.incarnation
 BEGIN SELECT RAISE(ABORT,'TVDB policy identity is immutable');END;
CREATE TRIGGER tvdb_policy_revision_monotonic BEFORE UPDATE OF revision ON tvdb_provider_policies
 WHEN NEW.revision<OLD.revision
 BEGIN SELECT RAISE(ABORT,'TVDB policy revision cannot decrease');END;
CREATE TRIGGER tvdb_set_revision_monotonic BEFORE UPDATE OF revision ON tvdb_publication_sets
 WHEN NEW.revision<OLD.revision
 BEGIN SELECT RAISE(ABORT,'TVDB evidence revision cannot decrease');END;
CREATE TRIGGER tvdb_page_revision_monotonic BEFORE UPDATE OF content_revision ON tvdb_publication_pages
 WHEN NEW.content_revision<OLD.content_revision
 BEGIN SELECT RAISE(ABORT,'TVDB page revision cannot decrease');END;
CREATE TRIGGER tvdb_set_identity_immutable BEFORE UPDATE OF show_id,incarnation,generation,provider_id,episode_order,policy_incarnation,policy_revision ON tvdb_publication_sets
 WHEN OLD.show_id IS NOT NEW.show_id OR OLD.incarnation IS NOT NEW.incarnation OR OLD.generation IS NOT NEW.generation OR OLD.provider_id IS NOT NEW.provider_id OR OLD.episode_order IS NOT NEW.episode_order OR OLD.policy_incarnation IS NOT NEW.policy_incarnation OR OLD.policy_revision IS NOT NEW.policy_revision
 BEGIN SELECT RAISE(ABORT,'TVDB evidence set identity is immutable');END;
CREATE TRIGGER tvdb_page_key_changed AFTER UPDATE OF show_id,set_incarnation,page ON tvdb_publication_pages
 WHEN OLD.show_id IS NOT NEW.show_id OR OLD.set_incarnation IS NOT NEW.set_incarnation OR OLD.page IS NOT NEW.page
 BEGIN
 UPDATE tvdb_publication_sets SET revision=revision+1,complete=0 WHERE show_id=OLD.show_id AND incarnation=OLD.set_incarnation;
 UPDATE tvdb_publication_pages SET content_revision=content_revision+1 WHERE show_id=NEW.show_id AND set_incarnation=NEW.set_incarnation AND page=NEW.page;
 END;
CREATE TRIGGER tvdb_page_descriptor_changed AFTER UPDATE OF next_page,row_count,byte_count,result_digest ON tvdb_publication_pages
 WHEN OLD.next_page IS NOT NEW.next_page OR OLD.row_count IS NOT NEW.row_count OR OLD.byte_count IS NOT NEW.byte_count OR OLD.result_digest IS NOT NEW.result_digest
 BEGIN UPDATE tvdb_publication_pages SET content_revision=content_revision+1 WHERE show_id=NEW.show_id AND set_incarnation=NEW.set_incarnation AND page=NEW.page;END;
CREATE TRIGGER tvdb_page_revision_changed AFTER UPDATE OF content_revision ON tvdb_publication_pages
 WHEN OLD.content_revision IS NOT NEW.content_revision
 BEGIN UPDATE tvdb_publication_sets SET revision=revision+1,complete=0 WHERE show_id=NEW.show_id AND incarnation=NEW.set_incarnation;END;
CREATE TRIGGER tvdb_operation_inputs_immutable BEFORE UPDATE OF id,show_id,show_incarnation,phase,library_id,query_title,query_year,job_generation,job_revision,lease_until,accepted_provider_id,episode_order,policy_incarnation,policy_revision,algorithm,refresh_mode,source_revision,hierarchy_revision,selection_revision,descriptive_revision,set_incarnation,set_revision,page,after_item,input_digest,created_at ON tvdb_publication_operations WHEN OLD.id IS NOT NEW.id OR OLD.show_id IS NOT NEW.show_id OR OLD.show_incarnation IS NOT NEW.show_incarnation OR OLD.phase IS NOT NEW.phase OR OLD.library_id IS NOT NEW.library_id OR OLD.query_title IS NOT NEW.query_title OR OLD.query_year IS NOT NEW.query_year OR OLD.job_generation IS NOT NEW.job_generation OR OLD.job_revision IS NOT NEW.job_revision OR OLD.lease_until IS NOT NEW.lease_until OR OLD.accepted_provider_id IS NOT NEW.accepted_provider_id OR OLD.episode_order IS NOT NEW.episode_order OR OLD.policy_incarnation IS NOT NEW.policy_incarnation OR OLD.policy_revision IS NOT NEW.policy_revision OR OLD.algorithm IS NOT NEW.algorithm OR OLD.refresh_mode IS NOT NEW.refresh_mode OR OLD.source_revision IS NOT NEW.source_revision OR OLD.hierarchy_revision IS NOT NEW.hierarchy_revision OR OLD.selection_revision IS NOT NEW.selection_revision OR OLD.descriptive_revision IS NOT NEW.descriptive_revision OR OLD.set_incarnation IS NOT NEW.set_incarnation OR OLD.set_revision IS NOT NEW.set_revision OR OLD.page IS NOT NEW.page OR OLD.after_item IS NOT NEW.after_item OR OLD.input_digest IS NOT NEW.input_digest OR OLD.created_at IS NOT NEW.created_at BEGIN SELECT RAISE(ABORT,'TVDB captured inputs are immutable');END;
