CREATE TRIGGER tvdb_page_ownership_UPDATE AFTER UPDATE ON tvdb_evidence_page_ownership BEGIN UPDATE tvdb_publication_pages SET content_revision=content_revision+1 WHERE (show_id=OLD.show_id AND set_incarnation=OLD.set_incarnation AND page=OLD.page) OR (show_id=NEW.show_id AND set_incarnation=NEW.set_incarnation AND page=NEW.page);END;
CREATE TRIGGER tvdb_owned_evidence_DELETE BEFORE DELETE ON tvdb_episode_evidence BEGIN UPDATE tvdb_publication_pages SET content_revision=content_revision+1 WHERE (show_id,set_incarnation,page) IN(SELECT o.show_id,o.set_incarnation,o.page FROM tvdb_evidence_page_ownership o WHERE (o.show_id=OLD.show_id AND o.generation=OLD.generation AND o.provider_id=OLD.provider_id));END;
CREATE TRIGGER tvdb_page_ownership_DELETE AFTER DELETE ON tvdb_evidence_page_ownership BEGIN UPDATE tvdb_publication_pages SET content_revision=content_revision+1 WHERE (show_id=OLD.show_id AND set_incarnation=OLD.set_incarnation AND page=OLD.page);END;
