CREATE TRIGGER tvdb_page_DELETE AFTER DELETE ON tvdb_publication_pages BEGIN UPDATE tvdb_publication_sets SET revision=revision+1,complete=0 WHERE show_id=OLD.show_id AND incarnation=OLD.set_incarnation;END;
