CREATE TRIGGER playback_origin_roots_create AFTER INSERT ON libraries BEGIN INSERT INTO playback_origin_roots(id) VALUES(NEW.id); END;
CREATE TRIGGER playback_origin_roots_move_old BEFORE UPDATE OF id ON libraries WHEN OLD.id IS NOT NEW.id BEGIN DELETE FROM playback_origin_roots WHERE id=OLD.id; END;
CREATE TRIGGER playback_origin_roots_move_new AFTER UPDATE OF id ON libraries WHEN OLD.id IS NOT NEW.id BEGIN INSERT INTO playback_origin_roots(id) VALUES(NEW.id); END;
CREATE TRIGGER playback_origin_roots_changed AFTER UPDATE OF root,kind ON libraries WHEN NOT(OLD.id IS NOT NEW.id) AND (OLD.root IS NOT NEW.root OR OLD.kind IS NOT NEW.kind) BEGIN UPDATE playback_origin_roots SET revision=revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER playback_origin_roots_monotonic BEFORE UPDATE ON playback_origin_roots WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_assets_monotonic BEFORE UPDATE ON playback_origin_assets WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_items_monotonic BEFORE UPDATE ON playback_origin_items WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_associations_monotonic BEFORE UPDATE ON playback_origin_associations WHEN (OLD.item_id IS NOT NEW.item_id OR OLD.asset_id IS NOT NEW.asset_id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_shows_monotonic BEFORE UPDATE ON playback_origin_shows WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_seasons_monotonic BEFORE UPDATE ON playback_origin_seasons WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_books_monotonic BEFORE UPDATE ON playback_origin_books WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_albums_monotonic BEFORE UPDATE ON playback_origin_albums WHEN (OLD.id IS NOT NEW.id) OR NEW.incarnation IS NOT OLD.incarnation OR typeof(NEW.revision)<>'integer' OR OLD.revision=9223372036854775807 OR NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'invalid playback origin revision'); END;
CREATE TRIGGER playback_origin_episode_boundary_insert AFTER INSERT ON episode_asset_boundaries BEGIN UPDATE playback_origin_associations SET revision=revision+1 WHERE item_id=NEW.item_id AND asset_id=NEW.asset_id; END;
CREATE TRIGGER playback_origin_episode_boundary_update AFTER UPDATE ON episode_asset_boundaries WHEN OLD.item_id IS NOT NEW.item_id OR OLD.asset_id IS NOT NEW.asset_id OR OLD.status IS NOT NEW.status BEGIN UPDATE playback_origin_associations SET revision=revision+1 WHERE (item_id=OLD.item_id AND asset_id=OLD.asset_id) OR (item_id=NEW.item_id AND asset_id=NEW.asset_id); END;
