CREATE TRIGGER playback_observation_create AFTER INSERT ON playback_sessions BEGIN INSERT INTO playback_observations(session_id,created_at) VALUES(NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now'));END;
CREATE TRIGGER authorization_account_epoch AFTER UPDATE OF epoch,profile_id ON accounts
 WHEN NEW.epoch<>OLD.epoch OR NEW.profile_id<>OLD.profile_id
 BEGIN
 UPDATE authorization_session_families SET revoked=1 WHERE authority='local' AND account_id=NEW.id;
 END;
CREATE TRIGGER authorization_account_deleted AFTER DELETE ON accounts
 BEGIN
 UPDATE authorization_session_families SET revoked=1 WHERE authority='local' AND account_id=OLD.id;
 END;
CREATE TRIGGER inventory_policy_handoff AFTER UPDATE OF revision ON library_scan_policies BEGIN
 INSERT INTO inventory_policy_pending(library_id,revision) VALUES(NEW.library_id,NEW.revision)
 ON CONFLICT(library_id) DO UPDATE SET revision=excluded.revision;
END;
CREATE TRIGGER inventory_library_create AFTER INSERT ON libraries BEGIN
 INSERT INTO library_sources(id,library_id,name,configured_root,root) VALUES(NEW.id,NEW.id,NEW.name,NEW.root,NEW.root);
 INSERT INTO library_scan_policies(library_id) VALUES(NEW.id);
END;
CREATE TRIGGER inventory_source_configuration AFTER UPDATE OF name,root,configured_root,classification,follow_symlinks,missing_grace_seconds,interval_seconds,enabled,root_identity,identity_confirmed ON library_sources BEGIN
 UPDATE library_configuration SET revision=revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_source_add AFTER INSERT ON library_sources BEGIN
 UPDATE library_configuration SET revision=revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_policy_change AFTER UPDATE ON library_scan_policies BEGIN
 UPDATE library_configuration SET revision=revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_availability_source AFTER UPDATE OF health,enabled,incarnation,generation ON library_sources BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_availability_object AFTER UPDATE OF state,retired,root_incarnation,unsupported_reason ON inventory_objects BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT library_id FROM library_sources WHERE id=NEW.source_id);
END;
CREATE TRIGGER job_observation_update AFTER UPDATE ON jobs BEGIN
 INSERT INTO job_observations(job_id,updated_at,finished_at) VALUES(NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),CASE WHEN NEW.status IN('complete','complete_with_warnings','failed','cancelled') THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') END)
 ON CONFLICT(job_id) DO UPDATE SET updated_at=excluded.updated_at,finished_at=COALESCE(job_observations.finished_at,excluded.finished_at);
END;
CREATE TRIGGER console_audit_immutable BEFORE UPDATE ON console_audit BEGIN SELECT RAISE(ABORT,'audit is append only'); END;
CREATE TRIGGER console_settings_name_insert AFTER INSERT ON configuration WHEN NEW.key='name' BEGIN UPDATE console_settings_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER console_settings_name_update AFTER UPDATE ON configuration WHEN (NEW.key='name' OR OLD.key='name') AND (NEW.value IS NOT OLD.value OR NEW.key!=OLD.key) BEGIN UPDATE console_settings_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER console_settings_name_delete AFTER DELETE ON configuration WHEN OLD.key='name' BEGIN UPDATE console_settings_revision SET revision=revision+1 WHERE singleton=1; END;
