CREATE TRIGGER console_settings_policy_update AFTER UPDATE ON playback_owner_policy BEGIN UPDATE console_settings_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER console_settings_policy_delete AFTER DELETE ON playback_owner_policy BEGIN UPDATE console_settings_revision SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER dvr_managed_library_root BEFORE UPDATE OF root,kind ON libraries
 WHEN EXISTS(SELECT 1 FROM dvr_private_libraries WHERE library_id=OLD.id) AND (OLD.root!=NEW.root OR OLD.kind!=NEW.kind)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
CREATE TRIGGER dvr_managed_library_delete BEFORE DELETE ON libraries
 WHEN EXISTS(SELECT 1 FROM dvr_private_libraries WHERE library_id=OLD.id)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
CREATE TRIGGER dvr_managed_source_insert BEFORE INSERT ON library_sources
 WHEN EXISTS(SELECT 1 FROM dvr_private_libraries WHERE library_id=NEW.library_id)
 AND NOT EXISTS(SELECT 1 FROM library_sources WHERE id=NEW.id)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
CREATE TRIGGER dvr_managed_source_update BEFORE UPDATE ON library_sources
 WHEN EXISTS(SELECT 1 FROM dvr_private_libraries WHERE library_id=OLD.library_id OR library_id=NEW.library_id)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
CREATE TRIGGER dvr_managed_source_delete BEFORE DELETE ON library_sources
 WHEN EXISTS(SELECT 1 FROM dvr_private_libraries WHERE library_id=OLD.library_id)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
CREATE TRIGGER dvr_managed_inventory_reject BEFORE INSERT ON inventory_runs
 WHEN EXISTS(SELECT 1 FROM library_sources s JOIN dvr_private_libraries d ON d.library_id=s.library_id WHERE s.id=NEW.source_id)
 BEGIN SELECT RAISE(ABORT,'dvr-managed-library'); END;
