-- ===== ported triggers and views (rewrites.sql)
-- Hand-ported triggers and views for the baseline (gen_baseline.py includes
-- these in place of the 265 definitions of the same names). A catalogue
-- entity's library is found through the backbone:
--   (SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=X)

-- ===== views
CREATE VIEW inventory_item_availability AS
 SELECT l.entity_id AS item_id,a.token AS asset_id,
 CASE WHEN EXISTS(SELECT 1 FROM admin_trash held WHERE held.item_id=l.entity_id AND held.state='held') THEN 0
 WHEN EXISTS(SELECT 1 FROM dvr_catalog_retirements gone WHERE gone.item_id=l.entity_id) THEN 0
 WHEN EXISTS(SELECT 1 FROM inventory_objects o JOIN library_sources s ON s.id=o.source_id WHERE o.asset_id=a.token AND s.library_id=cl.library_id)
 THEN EXISTS(SELECT 1 FROM inventory_objects o JOIN library_sources s ON s.id=o.source_id WHERE o.asset_id=a.token AND s.library_id=cl.library_id AND o.retired=0 AND o.state='available' AND o.unsupported_reason='' AND s.enabled=1 AND s.health NOT IN('offline','root_changed','removing') AND o.root_incarnation=s.incarnation)
 ELSE a.available=1 AND NOT EXISTS(SELECT 1 FROM library_sources s WHERE s.id=cl.library_id AND (s.enabled=0 OR s.health IN('offline','root_changed','removing'))) END AS available
 FROM catalog_asset_links l JOIN catalog_entities e ON e.id=l.entity_id JOIN catalog_libraries cl ON cl.id=e.library_id JOIN catalog_assets a ON a.id=l.asset_id;

CREATE VIEW listening_book_context AS
 SELECT e.id,cl.library_id,e.title,b.author,b.narrator,b.local_key,b.series,b.series_position,
 COALESCE((SELECT min(trim(t.value)) FROM catalog_book_files f
   CROSS JOIN catalog_asset_links l ON l.entity_id=f.entity_id CROSS JOIN catalog_assets a ON a.id=l.asset_id
   CROSS JOIN audio_tag_evidence t ON t.asset_id=a.token AND t.library_id=cl.library_id
   WHERE f.book_id=e.id AND t.field IN('series','series_title','show') AND trim(t.value)<>''
   HAVING count(DISTINCT lower(trim(t.value)))=1),'') AS series_name,
 COALESCE((SELECT min(CAST(t.value AS REAL)) FROM catalog_book_files f
   CROSS JOIN catalog_asset_links l ON l.entity_id=f.entity_id CROSS JOIN catalog_assets a ON a.id=l.asset_id
   CROSS JOIN audio_tag_evidence t ON t.asset_id=a.token AND t.library_id=cl.library_id
   WHERE f.book_id=e.id AND t.field IN('series_position','series_index','series-part','series_part')
     AND trim(t.value)<>'' AND trim(t.value) NOT GLOB '*[^0-9.]*'
     AND length(trim(t.value))-length(replace(trim(t.value),'.',''))<=1
     AND CAST(t.value AS REAL)>0 AND CAST(t.value AS REAL)<999999
   HAVING count(DISTINCT CAST(t.value AS REAL))=1),0) AS series_index
 FROM catalog_books b JOIN catalog_entities e ON e.id=b.entity_id JOIN catalog_libraries cl ON cl.id=e.library_id
 WHERE e.retired=0;

-- ===== library and viewer revisions through the entity's library
