 UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id IN(SELECT album_id FROM catalog_songs WHERE entity_id IN(OLD.item_id,NEW.item_id));
 UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.item_id)) OR (kind='album' AND entity_id IN(SELECT album_id FROM catalog_songs WHERE entity_id IN(OLD.item_id,NEW.item_id)));END;
