 UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE entity_id IN(SELECT l.entity_id FROM catalog_assets a JOIN catalog_asset_links l ON l.asset_id=a.id WHERE a.token IN(OLD.asset_id,NEW.asset_id) UNION SELECT s.album_id FROM catalog_assets a JOIN catalog_asset_links l ON l.asset_id=a.id JOIN catalog_songs s ON s.entity_id=l.entity_id WHERE a.token IN(OLD.asset_id,NEW.asset_id));END;
