 DELETE FROM listening_book_series WHERE book_id IN(SELECT f.book_id FROM catalog_assets a JOIN catalog_asset_links l ON l.asset_id=a.id JOIN catalog_book_files f ON f.entity_id=l.entity_id WHERE a.token=NEW.asset_id);
 INSERT INTO listening_book_series(book_id,library_id,series_key,series_name) SELECT b.id,b.library_id,lower(trim(b.series_name)),b.series_name FROM listening_book_context b
  WHERE b.id IN(SELECT f.book_id FROM catalog_assets a JOIN catalog_asset_links l ON l.asset_id=a.id JOIN catalog_book_files f ON f.entity_id=l.entity_id WHERE a.token=NEW.asset_id) AND b.series_name<>'';END;
