CREATE TRIGGER catalog_availability_trash_insert AFTER INSERT ON admin_trash BEGIN
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 20,id,1 FROM catalog_entities WHERE id=NEW.item_id
