CREATE TRIGGER catalog_book_group_insert AFTER INSERT ON listening_book_groups BEGIN
 INSERT INTO catalog_book_groups(token,library_id,kind,name,name_key)
 SELECT NEW.id,cl.id,CASE NEW.kind WHEN 'author' THEN 1 ELSE 2 END,NEW.name,NEW.name_key FROM catalog_libraries cl WHERE cl.library_id=NEW.library_id
 ON CONFLICT(token) DO UPDATE SET library_id=excluded.library_id,kind=excluded.kind,name=excluded.name,name_key=excluded.name_key,retired=0;
