-- (ON CONFLICT DO NOTHING, not INSERT OR IGNORE: catalog_item_details is
-- upserted, and an upsert's conflict rule would turn IGNORE into an abort.)
-- catalog_container_added follows each episode's show, season and added date,
-- and a change re-derives the containers' rows (their added date).
CREATE TRIGGER catalog_container_added_episode_insert AFTER INSERT ON catalog_episodes BEGIN
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT NEW.show_id,d.added_text,NEW.entity_id FROM catalog_item_details d WHERE d.entity_id=NEW.entity_id AND d.added_text IS NOT NULL AND d.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT NEW.season_id,d.added_text,NEW.entity_id FROM catalog_item_details d WHERE d.entity_id=NEW.entity_id AND NEW.season_id IS NOT NULL AND d.added_text IS NOT NULL AND d.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 18,value,1 FROM (SELECT NEW.show_id value UNION ALL SELECT NEW.season_id) WHERE value IS NOT NULL
  ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_container_added_episode_move AFTER UPDATE OF show_id,season_id ON catalog_episodes
 WHEN OLD.show_id IS NOT NEW.show_id OR OLD.season_id IS NOT NEW.season_id BEGIN
 DELETE FROM catalog_container_added WHERE item_id=OLD.entity_id;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT NEW.show_id,d.added_text,NEW.entity_id FROM catalog_item_details d WHERE d.entity_id=NEW.entity_id AND d.added_text IS NOT NULL AND d.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT NEW.season_id,d.added_text,NEW.entity_id FROM catalog_item_details d WHERE d.entity_id=NEW.entity_id AND NEW.season_id IS NOT NULL AND d.added_text IS NOT NULL AND d.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 18,value,1 FROM (SELECT OLD.show_id value UNION ALL SELECT OLD.season_id UNION ALL SELECT NEW.show_id UNION ALL SELECT NEW.season_id) WHERE value IS NOT NULL
  ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_container_added_episode_delete AFTER DELETE ON catalog_episodes BEGIN
 DELETE FROM catalog_container_added WHERE item_id=OLD.entity_id;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 18,value,1 FROM (SELECT OLD.show_id value UNION ALL SELECT OLD.season_id) WHERE value IS NOT NULL
  ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_container_added_details_insert AFTER INSERT ON catalog_item_details
 WHEN NEW.added_text IS NOT NULL AND EXISTS(SELECT 1 FROM catalog_episodes WHERE entity_id=NEW.entity_id) BEGIN
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT ep.show_id,NEW.added_text,NEW.entity_id FROM catalog_episodes ep WHERE ep.entity_id=NEW.entity_id AND NEW.added_text IS NOT NULL AND NEW.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT ep.season_id,NEW.added_text,NEW.entity_id FROM catalog_episodes ep WHERE ep.entity_id=NEW.entity_id AND ep.season_id IS NOT NULL AND NEW.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 18,value,1 FROM (SELECT show_id value FROM catalog_episodes WHERE entity_id=NEW.entity_id UNION ALL SELECT season_id FROM catalog_episodes WHERE entity_id=NEW.entity_id) WHERE value IS NOT NULL
  ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_container_added_details_update AFTER UPDATE OF added_text ON catalog_item_details
 WHEN OLD.added_text IS NOT NEW.added_text AND EXISTS(SELECT 1 FROM catalog_episodes WHERE entity_id=NEW.entity_id) BEGIN
 DELETE FROM catalog_container_added WHERE item_id=NEW.entity_id;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT ep.show_id,NEW.added_text,NEW.entity_id FROM catalog_episodes ep WHERE ep.entity_id=NEW.entity_id AND NEW.added_text IS NOT NULL AND NEW.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_container_added(container_id,added_text,item_id)
  SELECT ep.season_id,NEW.added_text,NEW.entity_id FROM catalog_episodes ep WHERE ep.entity_id=NEW.entity_id AND ep.season_id IS NOT NULL AND NEW.added_text IS NOT NULL AND NEW.added_text<>''
  ON CONFLICT DO NOTHING;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 18,value,1 FROM (SELECT show_id value FROM catalog_episodes WHERE entity_id=NEW.entity_id UNION ALL SELECT season_id FROM catalog_episodes WHERE entity_id=NEW.entity_id) WHERE value IS NOT NULL
  ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
