CREATE TRIGGER mb_song_artist_update AFTER UPDATE ON catalog_song_artists BEGIN UPDATE mb_song_heads SET revision=revision+1 WHERE item_id IN(OLD.song_id,NEW.song_id);UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT entity_id FROM catalog_songs WHERE entity_id IN(OLD.song_id,NEW.song_id)));END;
CREATE TRIGGER mb_song_automatic_row_deleted AFTER DELETE ON metadata_owner_fields WHEN OLD.kind='item' AND OLD.field='title' BEGIN UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT OLD.entity_id));END;
CREATE TRIGGER mb_song_automatic_row_inserted AFTER INSERT ON metadata_owner_fields WHEN NEW.kind='item' AND NEW.field='title' BEGIN UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.entity_id));END;
CREATE TRIGGER mb_song_automatic_title_changed AFTER UPDATE OF value,automatic_value ON metadata_owner_fields WHEN (NEW.kind='item' AND NEW.field='title') AND (OLD.value IS NOT NEW.value OR OLD.automatic_value IS NOT NEW.automatic_value) BEGIN UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.entity_id));END;
CREATE TRIGGER mb_song_created AFTER INSERT ON catalog_songs BEGIN INSERT INTO mb_song_heads(item_id) VALUES(NEW.entity_id);INSERT INTO mb_jobs(kind,entity_id,item_id) VALUES('song',NEW.entity_id,NEW.entity_id);UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id=NEW.album_id;UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='album' AND entity_id IN(SELECT NEW.album_id));END;
CREATE TRIGGER mb_song_delete BEFORE DELETE ON catalog_songs BEGIN UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id IN(OLD.album_id);UPDATE mb_song_heads SET revision=revision+1 WHERE item_id IN(OLD.entity_id);UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='album' AND entity_id IN(SELECT OLD.album_id));END;
CREATE TRIGGER mb_song_fallback_title_changed AFTER UPDATE OF title ON catalog_entities WHEN NEW.kind=7 AND OLD.title IS NOT NEW.title BEGIN UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.id));END;
-- Only the song's local facts (as the old songs table held): MusicBrainz
-- publication writes its own facts into catalog_songs and must not reset the
-- job that is publishing them.
CREATE TRIGGER mb_song_update AFTER UPDATE OF album_id,disc_number,track_number ON catalog_songs BEGIN UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id IN(OLD.album_id,NEW.album_id);UPDATE mb_song_heads SET revision=revision+1 WHERE item_id IN(OLD.entity_id,NEW.entity_id);UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.entity_id)) OR (kind='album' AND entity_id IN(SELECT OLD.album_id UNION SELECT NEW.album_id));END;
-- ===== metadata publication heads (items TEXT -> catalog_entities item-kinds 1,4,7,9,11,12; manual -> owner fields; credits/genres -> compact vocab)
CREATE TRIGGER metadata_publication_item_create AFTER INSERT ON catalog_entities WHEN NEW.kind IN(1,4,7,9,11,12) BEGIN
 INSERT INTO metadata_publication_heads(item_id) VALUES(NEW.id);
END;
CREATE TRIGGER metadata_publication_item_fields AFTER UPDATE OF title,kind,year,library_id ON catalog_entities WHEN NEW.kind IN(1,4,7,9,11,12) AND (OLD.title IS NOT NEW.title OR OLD.kind IS NOT NEW.kind OR OLD.year IS NOT NEW.year OR OLD.library_id IS NOT NEW.library_id) BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id=NEW.id;END;
CREATE TRIGGER metadata_publication_item_details AFTER UPDATE OF overview,poster_url,backdrop_url ON catalog_item_details WHEN OLD.overview IS NOT NEW.overview OR OLD.poster_url IS NOT NEW.poster_url OR OLD.backdrop_url IS NOT NEW.backdrop_url BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id=NEW.entity_id;END;
CREATE TRIGGER metadata_publication_item_manual_metadata_DELETE AFTER DELETE ON metadata_owner_fields WHEN OLD.kind='item' BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.entity_id);END;
CREATE TRIGGER metadata_publication_item_manual_metadata_INSERT AFTER INSERT ON metadata_owner_fields WHEN NEW.kind='item' BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(NEW.entity_id);END;
CREATE TRIGGER metadata_publication_item_manual_metadata_UPDATE AFTER UPDATE ON metadata_owner_fields WHEN (OLD.kind='item' OR NEW.kind='item') AND (OLD.entity_id IS NOT NEW.entity_id OR OLD.value IS NOT NEW.value OR OLD.automatic_value IS NOT NEW.automatic_value) BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER metadata_publication_item_scope AFTER UPDATE OF library_id,kind ON catalog_entities WHEN NEW.kind IN(1,4,7,9,11,12) AND (OLD.library_id IS NOT NEW.library_id OR OLD.kind IS NOT NEW.kind) BEGIN UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id=NEW.id;END;
