CREATE TRIGGER playback_origin_albums_changed AFTER UPDATE OF library_id ON catalog_entities WHEN NEW.kind=6 AND OLD.library_id IS NOT NEW.library_id BEGIN UPDATE playback_origin_albums SET revision=revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER playback_origin_albums_create AFTER INSERT ON catalog_entities WHEN NEW.kind=6 BEGIN INSERT INTO playback_origin_albums(id) VALUES(NEW.id);END;
CREATE TRIGGER playback_origin_assets_changed AFTER UPDATE OF path,size,modified_ns,available,container ON catalog_assets WHEN OLD.path IS NOT NEW.path OR OLD.size IS NOT NEW.size OR OLD.modified_ns IS NOT NEW.modified_ns OR OLD.available IS NOT NEW.available OR OLD.container IS NOT NEW.container BEGIN UPDATE playback_origin_assets SET revision=revision+1 WHERE id=NEW.token;END;
CREATE TRIGGER playback_origin_assets_create AFTER INSERT ON catalog_assets BEGIN INSERT INTO playback_origin_assets(id) VALUES(NEW.token);END;
CREATE TRIGGER playback_origin_associations_changed AFTER UPDATE OF part_index,start_seconds,end_seconds ON catalog_asset_links WHEN OLD.part_index IS NOT NEW.part_index OR OLD.start_seconds IS NOT NEW.start_seconds OR OLD.end_seconds IS NOT NEW.end_seconds BEGIN UPDATE playback_origin_associations SET revision=revision+1 WHERE item_id=NEW.entity_id AND asset_id=(SELECT token FROM catalog_assets WHERE id=NEW.asset_id);END;
CREATE TRIGGER playback_origin_associations_create AFTER INSERT ON catalog_asset_links BEGIN INSERT INTO playback_origin_associations(item_id,asset_id) VALUES(NEW.entity_id,(SELECT token FROM catalog_assets WHERE id=NEW.asset_id));END;
CREATE TRIGGER playback_origin_book_files_delete AFTER DELETE ON catalog_book_files BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id=OLD.entity_id;END;
