CREATE TRIGGER playback_origin_book_files_update AFTER UPDATE OF book_id,disc_number,part_number ON catalog_book_files WHEN OLD.book_id IS NOT NEW.book_id OR OLD.disc_number IS NOT NEW.disc_number OR OLD.part_number IS NOT NEW.part_number BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER playback_origin_books_changed AFTER UPDATE OF library_id ON catalog_entities WHEN NEW.kind=8 AND OLD.library_id IS NOT NEW.library_id BEGIN UPDATE playback_origin_books SET revision=revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER playback_origin_books_create AFTER INSERT ON catalog_entities WHEN NEW.kind=8 BEGIN INSERT INTO playback_origin_books(id) VALUES(NEW.id);END;
CREATE TRIGGER playback_origin_episodes_delete AFTER DELETE ON catalog_episodes BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id=OLD.entity_id;END;
CREATE TRIGGER playback_origin_episodes_insert AFTER INSERT ON catalog_episodes BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id=NEW.entity_id;END;
CREATE TRIGGER playback_origin_episodes_update AFTER UPDATE OF show_id,season_id,numbering,number,ordering_basis,local_identity_status ON catalog_episodes WHEN OLD.show_id IS NOT NEW.show_id OR OLD.season_id IS NOT NEW.season_id OR OLD.numbering IS NOT NEW.numbering OR OLD.number IS NOT NEW.number OR OLD.ordering_basis IS NOT NEW.ordering_basis OR OLD.local_identity_status IS NOT NEW.local_identity_status BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER playback_origin_items_changed AFTER UPDATE OF library_id,kind ON catalog_entities WHEN OLD.library_id IS NOT NEW.library_id OR OLD.kind IS NOT NEW.kind BEGIN UPDATE playback_origin_items SET revision=revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER playback_origin_items_create AFTER INSERT ON catalog_entities WHEN NEW.kind IN(1,4,7,9,11,12) BEGIN INSERT INTO playback_origin_items(id) VALUES(NEW.id);END;
CREATE TRIGGER playback_origin_seasons_changed_entities AFTER UPDATE OF parent_id ON catalog_entities WHEN NEW.kind=3 AND OLD.parent_id IS NOT NEW.parent_id BEGIN UPDATE playback_origin_seasons SET revision=revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER playback_origin_seasons_changed AFTER UPDATE OF show_id,number ON catalog_seasons WHEN OLD.show_id IS NOT NEW.show_id OR OLD.number IS NOT NEW.number BEGIN UPDATE playback_origin_seasons SET revision=revision+1 WHERE id=NEW.entity_id;END;
CREATE TRIGGER playback_origin_seasons_create AFTER INSERT ON catalog_entities WHEN NEW.kind=3 BEGIN INSERT INTO playback_origin_seasons(id) VALUES(NEW.id);END;
CREATE TRIGGER playback_origin_shows_changed AFTER UPDATE OF library_id ON catalog_entities WHEN NEW.kind=2 AND OLD.library_id IS NOT NEW.library_id BEGIN UPDATE playback_origin_shows SET revision=revision+1 WHERE id=NEW.id;END;
CREATE TRIGGER playback_origin_shows_create AFTER INSERT ON catalog_entities WHEN NEW.kind=2 BEGIN INSERT INTO playback_origin_shows(id) VALUES(NEW.id);END;
