CREATE TRIGGER revision_books_UPDATE AFTER UPDATE ON catalog_books BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_shows_UPDATE AFTER UPDATE ON catalog_shows BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_seasons_UPDATE AFTER UPDATE ON catalog_seasons BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_episodes_UPDATE AFTER UPDATE ON catalog_episodes BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_songs_UPDATE AFTER UPDATE ON catalog_songs BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_book_files_UPDATE AFTER UPDATE ON catalog_book_files BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_collections_UPDATE AFTER UPDATE ON catalog_collections BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_item_details_UPDATE AFTER UPDATE ON catalog_item_details BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_assets_DELETE AFTER DELETE ON catalog_assets BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT DISTINCT cl.library_id FROM catalog_asset_links l JOIN catalog_entities ce ON ce.id=l.entity_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE l.asset_id=OLD.id);END;
CREATE TRIGGER revision_assets_INSERT AFTER INSERT ON catalog_assets BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT DISTINCT cl.library_id FROM catalog_asset_links l JOIN catalog_entities ce ON ce.id=l.entity_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE l.asset_id=NEW.id);END;
CREATE TRIGGER revision_assets_UPDATE AFTER UPDATE ON catalog_assets BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT DISTINCT cl.library_id FROM catalog_asset_links l JOIN catalog_entities ce ON ce.id=l.entity_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE l.asset_id=NEW.id);END;
CREATE TRIGGER revision_book_chapters_DELETE AFTER DELETE ON catalog_book_chapters BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_book_files f JOIN catalog_entities ce ON ce.id=f.book_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE f.entity_id=OLD.file_id);END;
CREATE TRIGGER revision_book_chapters_INSERT AFTER INSERT ON catalog_book_chapters BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_book_files f JOIN catalog_entities ce ON ce.id=f.book_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE f.entity_id=NEW.file_id);END;
CREATE TRIGGER revision_book_chapters_UPDATE AFTER UPDATE ON catalog_book_chapters BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_book_files f JOIN catalog_entities ce ON ce.id=f.book_id JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE f.entity_id=NEW.file_id);END;
CREATE TRIGGER revision_collection_members_DELETE AFTER DELETE ON catalog_collection_members BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=OLD.collection_id);END;
CREATE TRIGGER revision_collection_members_INSERT AFTER INSERT ON catalog_collection_members BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.collection_id);END;
CREATE TRIGGER revision_collection_members_UPDATE AFTER UPDATE ON catalog_collection_members BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.collection_id,NEW.collection_id));END;
CREATE TRIGGER revision_song_artists_DELETE AFTER DELETE ON catalog_song_artists BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=OLD.artist_id);END;
CREATE TRIGGER revision_song_artists_INSERT AFTER INSERT ON catalog_song_artists BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.artist_id);END;
CREATE TRIGGER revision_song_artists_UPDATE AFTER UPDATE ON catalog_song_artists BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.artist_id,NEW.artist_id));END;
CREATE TRIGGER revision_asset_links_DELETE AFTER DELETE ON catalog_asset_links BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=OLD.entity_id);END;
CREATE TRIGGER revision_asset_links_INSERT AFTER INSERT ON catalog_asset_links BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id);END;
CREATE TRIGGER revision_asset_links_UPDATE AFTER UPDATE OF entity_id,asset_id,part_index,start_seconds,end_seconds ON catalog_asset_links BEGIN UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.entity_id,NEW.entity_id));END;
-- ===== screen metadata work (items/shows TEXT -> entities INTEGER; item_assets TEXT -> links INTEGER; assets TEXT id -> INTEGER id)
CREATE TRIGGER screen_asset_change AFTER UPDATE OF size,modified_ns,path ON catalog_assets WHEN NEW.size IS NOT OLD.size OR NEW.modified_ns IS NOT OLD.modified_ns OR NEW.path IS NOT OLD.path BEGIN
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error=''
 WHERE (target_kind='item' AND target_id IN(SELECT entity_id FROM catalog_asset_links WHERE asset_id=NEW.id)) OR (target_kind='show' AND target_id IN(SELECT e.show_id FROM catalog_episodes e JOIN catalog_asset_links a ON a.entity_id=e.entity_id WHERE a.asset_id=NEW.id));END;
CREATE TRIGGER screen_episode_create AFTER INSERT ON catalog_episodes BEGIN
 INSERT OR IGNORE INTO screen_metadata_work(target_kind,target_id,library_id,title_seed,year_seed,parent_id)
 SELECT 'item',ce.id,cl.library_id,ce.title,ce.year,NEW.show_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id=NEW.entity_id;
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error='' WHERE target_kind='show' AND target_id=NEW.show_id;
END;
CREATE TRIGGER screen_episode_identity_change AFTER UPDATE OF show_id,season_id,numbering,number,local_identity_status ON catalog_episodes WHEN OLD.show_id IS NOT NEW.show_id OR OLD.season_id IS NOT NEW.season_id OR OLD.numbering IS NOT NEW.numbering OR OLD.number IS NOT NEW.number OR OLD.local_identity_status IS NOT NEW.local_identity_status BEGIN
 UPDATE screen_metadata_work SET parent_id=NEW.show_id,status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error='' WHERE target_kind='item' AND target_id=NEW.entity_id;
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error='' WHERE target_kind='show' AND target_id IN(OLD.show_id,NEW.show_id);
END;
CREATE TRIGGER screen_item_delete AFTER DELETE ON catalog_entities WHEN OLD.kind IN(1,4,7,9,11,12) BEGIN DELETE FROM screen_metadata_work WHERE target_kind='item' AND target_id=OLD.id;END;
CREATE TRIGGER screen_movie_create AFTER INSERT ON catalog_entities WHEN NEW.kind=1 BEGIN
 INSERT OR IGNORE INTO screen_metadata_work(target_kind,target_id,library_id,title_seed,year_seed) VALUES('item',NEW.id,(SELECT library_id FROM catalog_libraries WHERE id=NEW.library_id),NEW.title,NEW.year);
END;
CREATE TRIGGER screen_show_create AFTER INSERT ON catalog_entities WHEN NEW.kind=2 BEGIN
 INSERT OR IGNORE INTO screen_metadata_work(target_kind,target_id,library_id,title_seed,year_seed) VALUES('show',NEW.id,(SELECT library_id FROM catalog_libraries WHERE id=NEW.library_id),NEW.title,NEW.year);
END;
CREATE TRIGGER screen_show_delete AFTER DELETE ON catalog_entities WHEN OLD.kind=2 BEGIN DELETE FROM screen_metadata_work WHERE target_kind='show' AND target_id=OLD.id;END;
CREATE TRIGGER screen_wake_item_assets_DELETE AFTER DELETE ON catalog_asset_links BEGIN
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error=''
 WHERE (target_kind='item' AND target_id IN(OLD.entity_id)) OR (target_kind='show' AND target_id IN(SELECT show_id FROM catalog_episodes WHERE entity_id IN(OLD.entity_id)));END;
CREATE TRIGGER screen_wake_item_assets_INSERT AFTER INSERT ON catalog_asset_links BEGIN
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error=''
 WHERE (target_kind='item' AND target_id IN(NEW.entity_id)) OR (target_kind='show' AND target_id IN(SELECT show_id FROM catalog_episodes WHERE entity_id IN(NEW.entity_id)));END;
CREATE TRIGGER screen_wake_item_assets_UPDATE AFTER UPDATE OF entity_id,asset_id,part_index,start_seconds,end_seconds ON catalog_asset_links BEGIN
 UPDATE screen_metadata_work SET status='pending',generation=generation+1,revision=revision+1,lease='',lease_until='',next_attempt='',error=''
 WHERE (target_kind='item' AND target_id IN(OLD.entity_id,NEW.entity_id)) OR (target_kind='show' AND target_id IN(SELECT show_id FROM catalog_episodes WHERE entity_id IN(OLD.entity_id,NEW.entity_id)));END;
-- ===== TVDB jobs and publication heads (episodes/seasons TEXT ids -> INTEGER entity_ids; shows -> entities kind 2)
CREATE TRIGGER tvdb_episode_created AFTER INSERT ON catalog_episodes BEGIN UPDATE tvdb_jobs SET status=CASE WHEN provider_id>0 AND episode_order<>'' THEN 'pending_apply' ELSE status END,apply_after='',revision=revision+1,lease='',lease_until='' WHERE show_id=NEW.show_id AND status IN('complete','pending_apply');END;
CREATE TRIGGER tvdb_publication_episodes_DELETE AFTER DELETE ON catalog_episodes BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(OLD.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(OLD.entity_id);END;
CREATE TRIGGER tvdb_publication_episodes_INSERT AFTER INSERT ON catalog_episodes BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(NEW.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_episodes_UPDATE AFTER UPDATE OF show_id,season_id,numbering,number,local_identity_status ON catalog_episodes WHEN OLD.show_id IS NOT NEW.show_id OR OLD.season_id IS NOT NEW.season_id OR OLD.numbering IS NOT NEW.numbering OR OLD.number IS NOT NEW.number OR OLD.local_identity_status IS NOT NEW.local_identity_status BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(OLD.show_id,NEW.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_ordering_projection AFTER UPDATE OF ordering_basis ON catalog_episodes WHEN OLD.ordering_basis IS NOT NEW.ordering_basis BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_seasons_DELETE AFTER DELETE ON catalog_seasons BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(OLD.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(SELECT entity_id FROM catalog_episodes WHERE season_id=OLD.entity_id);END;
CREATE TRIGGER tvdb_publication_seasons_INSERT AFTER INSERT ON catalog_seasons BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(NEW.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(SELECT entity_id FROM catalog_episodes WHERE season_id=NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_seasons_UPDATE AFTER UPDATE OF show_id,number ON catalog_seasons WHEN OLD.show_id IS NOT NEW.show_id OR OLD.number IS NOT NEW.number BEGIN UPDATE tvdb_publication_heads SET hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(OLD.show_id,NEW.show_id);UPDATE metadata_publication_heads SET source_revision=source_revision+1 WHERE item_id IN(SELECT entity_id FROM catalog_episodes WHERE season_id=OLD.entity_id UNION SELECT entity_id FROM catalog_episodes WHERE season_id=NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_show_create AFTER INSERT ON catalog_entities WHEN NEW.kind=2 BEGIN
 INSERT INTO tvdb_publication_heads(show_id) VALUES(NEW.id);
END;
CREATE TRIGGER tvdb_publication_show_description AFTER UPDATE OF title,year,library_id ON catalog_entities WHEN NEW.kind=2 AND (OLD.title IS NOT NEW.title OR OLD.year IS NOT NEW.year OR OLD.library_id IS NOT NEW.library_id) BEGIN UPDATE tvdb_publication_heads SET descriptive_revision=descriptive_revision+1 WHERE show_id IN(OLD.id,NEW.id);END;
CREATE TRIGGER tvdb_publication_show_local_key AFTER UPDATE OF local_key ON catalog_shows BEGIN UPDATE tvdb_publication_heads SET descriptive_revision=descriptive_revision+1 WHERE show_id IN(OLD.entity_id,NEW.entity_id);END;
CREATE TRIGGER tvdb_publication_show_scope AFTER UPDATE OF library_id ON catalog_entities WHEN NEW.kind=2 AND OLD.library_id IS NOT NEW.library_id BEGIN UPDATE tvdb_publication_heads SET source_revision=source_revision+1,hierarchy_revision=hierarchy_revision+1 WHERE show_id IN(OLD.id,NEW.id);END;
CREATE TRIGGER tvdb_show_created AFTER INSERT ON catalog_entities WHEN NEW.kind=2 BEGIN INSERT OR IGNORE INTO tvdb_jobs(show_id) VALUES(NEW.id);END;
-- ===== visibility rating ages (catalog_visibility_dirty_entities dropped; keep the library revision bumps via edges)
CREATE TRIGGER visibility_dirty_rating_age_delete AFTER DELETE ON content_rating_ages BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id IN
 (SELECT DISTINCT cl.library_id FROM catalog_item_attribute_edges e JOIN catalog_attribute_terms t ON t.id=e.term_id JOIN catalog_attribute_fields f ON f.id=t.field_id JOIN catalog_entities ce ON ce.id=e.item_id JOIN catalog_libraries cl ON cl.id=ce.library_id
  WHERE f.field='contentRating' AND t.value_key=OLD.value_key);
END;
CREATE TRIGGER visibility_dirty_rating_age_insert AFTER INSERT ON content_rating_ages BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id IN
 (SELECT DISTINCT cl.library_id FROM catalog_item_attribute_edges e JOIN catalog_attribute_terms t ON t.id=e.term_id JOIN catalog_attribute_fields f ON f.id=t.field_id JOIN catalog_entities ce ON ce.id=e.item_id JOIN catalog_libraries cl ON cl.id=ce.library_id
  WHERE f.field='contentRating' AND t.value_key=NEW.value_key);
END;
CREATE TRIGGER visibility_dirty_rating_age_update AFTER UPDATE OF minimum_age ON content_rating_ages WHEN OLD.minimum_age IS NOT NEW.minimum_age BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id IN
 (SELECT DISTINCT cl.library_id FROM catalog_item_attribute_edges e JOIN catalog_attribute_terms t ON t.id=e.term_id JOIN catalog_attribute_fields f ON f.id=t.field_id JOIN catalog_entities ce ON ce.id=e.item_id JOIN catalog_libraries cl ON cl.id=ce.library_id
  WHERE f.field='contentRating' AND t.value_key=NEW.value_key);
END;

